INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "包线是包住电线的塑料皮。", "primary_collocate": null, "pronunciation": "bāo xiàn", "ipa": "pɑʊ̯˥ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这根线的包线是红色的塑料皮。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用剪刀剪开了耳机线的包线。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包线太软了，一拉就破。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的网线包线是白色的。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠咬破了电视机后面的包线。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线的铜丝在里面，包线在外面。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧电线用久了，包线变硬了。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别用力拉扯，包线会裂开的。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈发现台灯的包线坏了，马上换了新线。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包线破了的地方要用胶带缠好。", "target_word": "包线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根包线", "label": "量词"}, {"form": "包線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "包在电线外面的塑料皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包线", "is_correct": true, "explanation": "包线：包在电线外面的塑料皮，与句中“红色的塑料皮”的描述相符。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：“是红色的塑料皮”描述的是实物，“长度”是抽象的量，不能作这一判断的主语。"}, {"text": "开关", "is_correct": false, "explanation": "语义：开关是控制电路的装置，不是红色的塑料皮，句意不通。"}, {"text": "铜丝", "is_correct": false, "explanation": "语义：铜丝是电线内部导电的金属，不是红色的塑料皮，句意不通。"}], "explanations": {"包线": "包线：包在电线外面的塑料皮，与句中“红色的塑料皮”的描述相符。", "长度": "搭配：“是红色的塑料皮”描述的是实物，“长度”是抽象的量，不能作这一判断的主语。", "开关": "语义：开关是控制电路的装置，不是红色的塑料皮，句意不通。", "铜丝": "语义：铜丝是电线内部导电的金属，不是红色的塑料皮，句意不通。"}, "sentence_index": 0, "correct_answer": "包线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只包线。", "explanation": "量词错误：这里应该用〈根〉。包线是细长的线状物，“只”用于动物或成对的东西，不用于包线。"}, {"text": "电线里面的包线很细。", "explanation": "这里应该用〈铜丝〉。铜丝是电线内部导电的部分，包线是外面的绝缘层，不能说包线很细。"}, {"text": "用包线包住水果。", "explanation": "这里应该用〈塑料袋〉。塑料袋用来包东西，包线是电线外层，不能用来包水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包线", "is_correct": true, "explanation": "包线：包在旧电线外面的塑料皮，用久了会老化变硬，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会变硬，“颜色变硬了”句意不通。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“变硬”描述有形的东西，“亮度”是属性，不能说亮度变硬。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是气味或口感，不会变硬，句意不通。"}], "explanations": {"包线": "包线：包在旧电线外面的塑料皮，用久了会老化变硬，符合句意。", "颜色": "语义：颜色不会变硬，“颜色变硬了”句意不通。", "亮度": "搭配：“变硬”描述有形的东西，“亮度”是属性，不能说亮度变硬。", "味道": "语义：味道是气味或口感，不会变硬，句意不通。"}, "sentence_index": 6, "correct_answer": "包线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手机包线破了，要换一个新的。", "explanation": "这里应该用〈外壳〉。包线指电线外的保护层，手机的外壳不能叫包线。"}, {"text": "用包线把伤口包起来。", "explanation": "这里应该用〈胶带〉。包线是电线的保护层，不能用来包扎伤口。"}, {"text": "我买了一张包线。", "explanation": "量词错误：这里应该用〈根〉。包线呈细长线状，“张”用于平面的东西，不用于包线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电工小心地剥下一颗包线。", "corrected_sentence": "电工小心地剥下一段包线。", "error_description": "量词错误：包线是细长的线状物，量词应用“段”；“颗”用于圆粒状的东西，不能用于包线，应说“一段包线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗包线老化了，要换掉。", "corrected_sentence": "这根包线老化了，要换掉。", "error_description": "量词错误：包线是细长的线状物，量词应用“根”；“颗”用于圆粒状的东西，不能用于包线，应说“这根包线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
