INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或东西不再在一起。", "primary_collocate": null, "pronunciation": "fēn lí", "ipa": "fən˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "战争让一家人分离了很多年。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分离了十年，终于又见面了。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友毕业后就要分离了。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不愿意和主人分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想和家人分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分离的时候，大家都哭了。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间的分离让他们很想念对方。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为工作，夫妻只好长期分离。", "target_word": "分离", "complexity_tier": "T3", "furigana": "yīn wèi gōng zuò, fū qī zhǐ hǎo cháng qī fēn lí.", "sentence_source": "generated"}, {"text": "那只小鸟和妈妈分离了，叫个不停。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次和妈妈分离，哭得很厉害。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分離", "label": "繁体"}, {"form": "分离了", "label": "体标"}, {"form": "分离过", "label": "体标"}], "register": "通用", "sense_fingerprint": "人或事物离别，不再在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分离", "is_correct": true, "explanation": "与听到的读音一致，fēn lí，意思是两个人或东西不再在一起。"}, {"text": "奋力", "is_correct": false, "explanation": "fèn lì（第四声）与 fēn lí 的声调不同，意思是尽力、用力。"}, {"text": "分立", "is_correct": false, "explanation": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。"}, {"text": "分理", "is_correct": false, "explanation": "fēn lǐ（第三声）与 fēn lí 的 lí 声调不同，意思是条理，较少用。"}], "explanations": {"分离": "与听到的读音一致，fēn lí，意思是两个人或东西不再在一起。", "奋力": "fèn lì（第四声）与 fēn lí 的声调不同，意思是尽力、用力。", "分立": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。", "分理": "fēn lǐ（第三声）与 fēn lí 的 lí 声调不同，意思是条理，较少用。"}, "sentence_index": null, "correct_answer": "分离"}, "level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：指一家人长期被隔开、不在一起，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与战争造成的隔开毫无关系，“战争让一家人游泳了很多年”句意荒谬。"}, {"text": "合唱", "is_correct": false, "explanation": "搭配：“合唱”是多人一起唱歌，不能作“战争让……”这类结构的结果。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与战争造成的隔开毫无关系，“战争让一家人跳舞了很多年”句意荒谬。"}], "explanations": {"分离": "分离：指一家人长期被隔开、不在一起，符合句意。", "游泳": "语义：“游泳”与战争造成的隔开毫无关系，“战争让一家人游泳了很多年”句意荒谬。", "合唱": "搭配：“合唱”是多人一起唱歌，不能作“战争让……”这类结构的结果。", "跳舞": "语义：“跳舞”与战争造成的隔开毫无关系，“战争让一家人跳舞了很多年”句意荒谬。"}, "sentence_index": 0, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中分离了冠军的机会。", "explanation": "这里应该用〈失去〉。分离指两者原本在一起后不再在一起，丢掉机会要用失去，不能说分离机会。"}, {"text": "我一个人在家，很快就分离了。", "explanation": "这里应该用〈出门〉。分离至少需要两者，句中只有“我”一人，一个人离家不是分离，应说出门。"}, {"text": "他的心情很快就分离了。", "explanation": "这里应该用〈好转〉。分离要求两者原本在一起，心情只是一个人的状态，不能说分离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：指长时间不在一起，符合“很想念对方”的语境。"}, {"text": "聚会", "is_correct": false, "explanation": "语义：“聚会”指大家在一起，与“很想念对方”所需的分开语境相反。"}, {"text": "欢笑", "is_correct": false, "explanation": "语义：“欢笑”是高兴的表现，不会使人很想念对方。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”不能使人长时间想念对方，“长时间的笑话让他们很想念对方”句意不通。"}], "explanations": {"分离": "分离：指长时间不在一起，符合“很想念对方”的语境。", "聚会": "语义：“聚会”指大家在一起，与“很想念对方”所需的分开语境相反。", "欢笑": "语义：“欢笑”是高兴的表现，不会使人很想念对方。", "笑话": "语义：“笑话”不能使人长时间想念对方，“长时间的笑话让他们很想念对方”句意不通。"}, "sentence_index": 6, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵们很快分离了阵地。", "explanation": "这里应该用〈撤离〉。分离指两者原本在一起后不再在一起，士兵离开阵地要用撤离，不能说分离阵地。"}, {"text": "列车分离了站台。", "explanation": "这里应该用〈离开〉。分离要求双方原本在一起，列车与站台不是这种关系，应说列车离开站台。"}, {"text": "他终于分离了危险。", "explanation": "这里应该用〈脱离〉。危险不是可以与人分开的事物，应说脱离危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们因为误会分离着两年，最后又团聚了。", "corrected_sentence": "他们因为误会分离了两年，最后又团聚了。", "error_description": "体标错误：叙述的是已经结束的两年分开，“分离”后应用“了”，用“着”表示持续状态不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子给父母分离了很久。", "corrected_sentence": "孩子和父母分离了很久。", "error_description": "介词错误：“分离”的对象应由“和”引出，“给”表示给予，不能说“给父母分离”，应为“和父母分离”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
