INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最新的、最好的技术。", "primary_collocate": null, "pronunciation": "qián yán jì shù", "ipa": "t͡ɕʰi̯ɛn˧˥ i̯ɛn˧˥ t͡ɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "这款手机采用了前沿技术，拍照效果非常好。", "target_word": "前沿技术", "complexity_tier": "T3", "furigana": "zhè kuǎn shǒujī cǎiyòng le qiányán jìshù, pāizhào xiàoguǒ fēicháng hǎo", "sentence_source": "generated"}, {"text": "他们的工厂有很多前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学习国外的前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆电动车用的是世界上最好的前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，前沿技术就是最新最好的技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院买了用前沿技术做的新机器。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让公司发展得快，就要用前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城市的工厂也开始用前沿技术了。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前沿技术很贵，不是每家公司都买得起。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看新闻，了解各种前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项前沿技术", "label": "量词"}, {"form": "前沿技術", "label": "繁体"}], "register": "书面", "sense_fingerprint": "最新最好的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前沿技术", "is_correct": true, "explanation": "正确：“采用了”后接的是手机所用的技术，“前沿技术”与拍照效果的描述相符。"}, {"text": "古法造纸", "is_correct": false, "explanation": "语义：古法造纸与手机的拍照效果毫无关系，句子无法成立。"}, {"text": "家庭作业", "is_correct": false, "explanation": "语义：家庭作业不是手机的组成部分，不能被手机“采用”。"}, {"text": "家常菜", "is_correct": false, "explanation": "语义：“家常菜”不是手机能“采用”的东西，“这款手机采用了家常菜”句意荒谬。"}], "explanations": {"前沿技术": "正确：“采用了”后接的是手机所用的技术，“前沿技术”与拍照效果的描述相符。", "古法造纸": "语义：古法造纸与手机的拍照效果毫无关系，句子无法成立。", "家庭作业": "语义：家庭作业不是手机的组成部分，不能被手机“采用”。", "家常菜": "语义：“家常菜”不是手机能“采用”的东西，“这款手机采用了家常菜”句意荒谬。"}, "sentence_index": 0, "correct_answer": "前沿技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们工厂买了一只前沿技术。", "explanation": "这里应该用〈一项〉。“只”用于动物或单件物品，技术要用“项”或“门”计数。"}, {"text": "这家农场的前沿技术就是那片靠近国界线的田地，一年到头几乎没人来。", "explanation": "这里应该用〈边境地带〉。“前沿”另有边境地带的意思，而“前沿技术”指最新、最好的技术，不能指一片田地。"}, {"text": "这位木匠的前沿技术是祖传的老手艺，做的桌子很结实。", "explanation": "这里应该用〈传统手艺〉。“前沿技术”指最新、最好的技术，与“祖传的老手艺”自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前沿技术", "is_correct": true, "explanation": "正确：“用”后接的是促进发展的手段，“前沿技术”符合这一语境。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”与公司发展的快慢没有关系，“用午睡发展公司”句意不通。"}, {"text": "老式家具", "is_correct": false, "explanation": "语义：老式家具与公司发展的快慢之间没有因果关系。"}, {"text": "加班费", "is_correct": false, "explanation": "搭配：“用”后接的应是手段、方法，“加班费”是报酬，不能作为手段。"}], "explanations": {"前沿技术": "正确：“用”后接的是促进发展的手段，“前沿技术”符合这一语境。", "午睡": "语义：“午睡”与公司发展的快慢没有关系，“用午睡发展公司”句意不通。", "老式家具": "语义：老式家具与公司发展的快慢之间没有因果关系。", "加班费": "搭配：“用”后接的应是手段、方法，“加班费”是报酬，不能作为手段。"}, "sentence_index": 6, "correct_answer": "前沿技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小作坊的前沿技术全是几十年前的旧法子，一点也不新。", "explanation": "这里应该用〈传统工艺〉。“前沿技术”指最新、最好的技术，而几十年前沿用的旧法子属于传统工艺，两者不能指同一件事。"}, {"text": "这家小店引进了一台前沿技术。", "explanation": "这里应该用〈一项〉。“台”用于机器、设备，技术不是具体的机器，要用“项”或“门”计数。"}, {"text": "她去超市称了三斤前沿技术。", "explanation": "“斤”是重量单位，技术没有重量，不能称，也不能用“斤”计量；若要计数，应改用“项”或“门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们工厂引进了一本前沿技术。", "corrected_sentence": "我们工厂引进了一项前沿技术。", "error_description": "错误形式“一本前沿技术”，正确形式“一项前沿技术”。“本”用于书籍、册子，技术不是可以翻阅的书，应改用“项”计数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们学会着前沿技术。", "corrected_sentence": "他们学会了前沿技术。", "error_description": "错误形式“学会着前沿技术”，正确形式“学会了前沿技术”。“学会”表示动作完成后获得的结果，应用“了”表示完成；“着”表示动作或状态的持续，与“学会”这种瞬间完成的结果不搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
