INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "算出题目的答案。", "primary_collocate": null, "pronunciation": "qiú jiě", "ipa": "tɕʰjoʊ˧˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这道应用题我求解了很久。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请小明上台求解这道题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先看清题目，再开始求解。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题太难，我没办法求解。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看书，一边求解数学题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都在认真求解练习题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "求解这道题只要五分钟。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了三种方法求解这道几何题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，我先求解容易的题目。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道物理题他求解过两次。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "求解了", "label": "完成体"}, {"form": "求解过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "算出习题或题目的答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24631489-7be5-43ad-b7ec-de458e1dff98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "求解", "is_correct": true, "explanation": "“求解”指算出题目的答案，与“应用题”搭配，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：应用题不能被购买，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、房屋等实体，不用于应用题。"}, {"text": "煮", "is_correct": false, "explanation": "语义：应用题不能被煮，与“算出答案”的语境无关。"}], "explanations": {"求解": "“求解”指算出题目的答案，与“应用题”搭配，符合句意。", "购买": "语义：应用题不能被购买，句子不通。", "修理": "搭配：“修理”用于机器、房屋等实体，不用于应用题。", "煮": "语义：应用题不能被煮，与“算出答案”的语境无关。"}, "sentence_index": 0, "correct_answer": "求解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师耐心地求解了这个道理。", "explanation": "这里应该用〈解释〉。求解用于算出题目的答案，道理要用〈解释〉。"}, {"text": "他认真求解了这篇古文。", "explanation": "这里应该用〈解读〉。求解用于算出题目的答案，古文的意思要用〈解读〉。"}, {"text": "老师当场求解了那个破碎的花瓶。", "explanation": "这里应该用〈修补〉。求解只用于算出题目的答案，修复花瓶要用〈修补〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "求解", "is_correct": true, "explanation": "“求解”指算出题目的答案，“这道题”与“五分钟”的语境相符。"}, {"text": "浇", "is_correct": false, "explanation": "语义：题目不能被“浇”，与五分钟内算出题目的语境不符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、场地等，不用于题目。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”不能用来指做题，句子不通。"}], "explanations": {"求解": "“求解”指算出题目的答案，“这道题”与“五分钟”的语境相符。", "浇": "语义：题目不能被“浇”，与五分钟内算出题目的语境不符。", "打扫": "搭配：“打扫”用于房间、场地等，不用于题目。", "洗": "语义：“洗”不能用来指做题，句子不通。"}, "sentence_index": 6, "correct_answer": "求解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员把被困的人求解了出来。", "explanation": "这里应该用〈解救〉。求解只用于算出题目的答案，把被困的人救出来要用〈解救〉。"}, {"text": "政府终于求解了这项禁令。", "explanation": "这里应该用〈解除〉。求解只用于算出题目的答案，禁令要用〈解除〉。"}, {"text": "导游耐心地求解了每一处景点。", "explanation": "这里应该用〈解说〉。求解只用于算出题目的答案，景点的讲解要用〈解说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道几何题我终于求解出去了。", "corrected_sentence": "这道几何题我终于求解出来了。", "error_description": "“求解出去”错，应为“求解出来”。“出来”表示算出结果，“出去”表示向外离开，不能用于题目的答案。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在认真求解过这道奥数题。", "corrected_sentence": "我正在认真求解这道奥数题。", "error_description": "“求解过”错，应为“求解”。“正在”表示动作正在进行，而“过”表示经历过的动作，两者不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共性", "is_correct": true, "explanation": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。"}, {"text": "体积", "is_correct": false, "explanation": "体积指物体所占空间的大小，与特性不构成反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度指冷热程度，与特性不构成反义关系。"}, {"text": "规律", "is_correct": false, "explanation": "规律指事物发展中稳定的联系，与特性不构成反义关系。"}], "correct_answer": "共性", "explanations": {"共性": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。", "体积": "体积指物体所占空间的大小，与特性不构成反义关系。", "温度": "温度指冷热程度，与特性不构成反义关系。", "规律": "规律指事物发展中稳定的联系，与特性不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共性", "is_correct": true, "explanation": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。"}, {"text": "长度", "is_correct": false, "explanation": "长度指线状事物的长短，与特性不构成反义关系。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命指存续的时间，与特性不构成反义关系。"}, {"text": "密度", "is_correct": false, "explanation": "密度指单位体积内物质的多少，与特性不构成反义关系。"}], "correct_answer": "共性", "explanations": {"共性": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。", "长度": "长度指线状事物的长短，与特性不构成反义关系。", "寿命": "寿命指存续的时间，与特性不构成反义关系。", "密度": "密度指单位体积内物质的多少，与特性不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "特性就是一个人或东西特别的地方。", "primary_collocate": null, "pronunciation": "tè xìng", "ipa": "tʰɤ˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "每种材料都有自己的特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫的特性是喜欢安静，也喜欢睡觉。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种植物的特性是不怕冷。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要了解每个孩子的特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金属的特性是容易导电。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先看看这种动物有什么特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这个产品的特性写在了纸上。", "target_word": "特性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的茶有不同的特性，味道也不一样。", "target_word": "特性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子的特性让它很适合做桌子。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很喜欢这个手机的几个特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "人或事物独有的性质和特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9dc599-3173-4820-a892-52e831b34649') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特性", "is_correct": true, "explanation": "特性指事物本身独有的性质，每种材料都有自己独特的性质，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」是人的外形特征，材料不能说有身高。"}, {"text": "学历", "is_correct": false, "explanation": "语义：「学历」指人受教育的经历，材料不能有学历，句意不通。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：「嗓音」只与能发声的人或动物搭配，材料没有嗓音。"}], "explanations": {"特性": "特性指事物本身独有的性质，每种材料都有自己独特的性质，符合句意。", "身高": "体貌：「身高」是人的外形特征，材料不能说有身高。", "学历": "语义：「学历」指人受教育的经历，材料不能有学历，句意不通。", "嗓音": "搭配：「嗓音」只与能发声的人或动物搭配，材料没有嗓音。"}, "sentence_index": 0, "correct_answer": "特性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的特性下了一场大雨，我们没法去公园。", "explanation": "这里应该用〈天气〉。特性指事物本身的性质，不能下雨；说下雨要用〈天气〉。"}, {"text": "这个活动的特性开了三个小时，大家都累了。", "explanation": "这里应该用〈时间〉。特性不能「开」，说活动持续了多久要用〈时间〉。"}, {"text": "我去商店买了很多特性。", "explanation": "这里应该用〈商品〉。特性是事物本身的性质，不是可以买卖的东西；去商店买的是〈商品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特性", "is_correct": true, "explanation": "特性指产品本身的性质，「把这个产品的特性写在纸上」符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是人的情绪，产品没有心情。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：「辈分」指人际关系中的代际次序，不能用于产品。"}, {"text": "胃口", "is_correct": false, "explanation": "搭配：「胃口」指食欲，只能说人或动物的胃口，不能说产品的胃口。"}], "explanations": {"特性": "特性指产品本身的性质，「把这个产品的特性写在纸上」符合句意。", "心情": "语义：「心情」是人的情绪，产品没有心情。", "辈分": "语义：「辈分」指人际关系中的代际次序，不能用于产品。", "胃口": "搭配：「胃口」指食欲，只能说人或动物的胃口，不能说产品的胃口。"}, "sentence_index": 6, "correct_answer": "特性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的特性吃了三升油，很费钱。", "explanation": "这里应该用〈油耗〉。特性是事物本身的性质，不能「吃」油；说车耗油多少要用〈油耗〉。"}, {"text": "我把这只猫的特性抱回了家。", "explanation": "这里应该用〈猫〉。特性是抽象的性质，不能抱回家；被抱回家的是猫本身。"}, {"text": "我去厨房炒了一盘特性。", "explanation": "这里应该用〈菜〉。特性是抽象的性质，不能用来炒；炒的是菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种材料地特性很稳定，所以很常用。", "corrected_sentence": "这种材料的特性很稳定，所以很常用。", "error_description": "错误：「地」用错。「地」用于修饰动词或形容词，修饰名词「特性」要用「的」，应说「这种材料的特性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台相机有一把很实用的特性。", "corrected_sentence": "这台相机有一种很实用的特性。", "error_description": "错误：量词错误。〈把〉用于有柄的器具，修饰抽象名词「特性」应用〈种〉，应说「一种很实用的特性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
