INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24282, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水或空气流动得很快，很乱，像有很多小漩涡。", "primary_collocate": null, "pronunciation": "tuān liú", "ipa": "tʰwan˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "河里有一股湍流，不要靠近。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机遇到湍流，座位抖了起来。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湍流里的水又快又乱。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湍流把小船冲到了岸边。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的河水到这里变成了湍流。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空姐说前面有湍流，请坐好。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湍流里有很多小漩涡。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能在湍流里游泳。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机遇到湍流，我有点儿怕。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湍流过后，天空又安静了。", "target_word": "湍流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "水或空气流得又快又乱、带小漩涡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7c84d0d-b658-4011-a3cd-9d3d112aea10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湍流", "is_correct": true, "explanation": "正确：「一股湍流」指水流又快又乱，靠近有危险，与「不要靠近」相符。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声不是河里的水流，「河里有一股歌声」不成立。"}, {"text": "诗句", "is_correct": false, "explanation": "语义：诗句是文字作品，河中流动的不是文字，「河里有一股诗句」不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不在河水中流动，「河里有一股空气」与语境不符。"}], "explanations": {"湍流": "正确：「一股湍流」指水流又快又乱，靠近有危险，与「不要靠近」相符。", "歌声": "语义：歌声不是河里的水流，「河里有一股歌声」不成立。", "诗句": "语义：诗句是文字作品，河中流动的不是文字，「河里有一股诗句」不成立。", "空气": "语义：空气不在河水中流动，「河里有一股空气」与语境不符。"}, "sentence_index": 0, "correct_answer": "湍流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一股湍流缓缓流过石缝。", "explanation": "这里应该用〈细流〉。湍流水流又快又乱，不能用「缓缓」形容。"}, {"text": "前面有一只湍流，大家小心。", "explanation": "这里应该用〈股〉。「只」用于动物等个体，湍流应用「股」。"}, {"text": "湍流很平静，没有一点儿波澜。", "explanation": "这里应该用〈湖水〉。湍流水势湍急，不能用「平静、没有波澜」形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湍流", "is_correct": true, "explanation": "正确：湍流中有很多小漩涡，符合「水或空气流得又快又乱、带小漩涡」的定义。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室里不会有水或空气流动形成的漩涡。"}, {"text": "学堂", "is_correct": false, "explanation": "语域：「学堂」是旧式称谓，现代已不常用，且学堂里同样不会有漩涡。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本是纸页装订品，里面没有漩涡。"}], "explanations": {"湍流": "正确：湍流中有很多小漩涡，符合「水或空气流得又快又乱、带小漩涡」的定义。", "教室": "语义：教室里不会有水或空气流动形成的漩涡。", "学堂": "语域：「学堂」是旧式称谓，现代已不常用，且学堂里同样不会有漩涡。", "书本": "语义：书本是纸页装订品，里面没有漩涡。"}, "sentence_index": 6, "correct_answer": "湍流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湍流平缓地涌上沙滩。", "explanation": "这里应该用〈海浪〉。湍流水势湍急混乱，不能用「平缓」形容。"}, {"text": "湍流安静地流过村庄。", "explanation": "这里应该用〈溪流〉。湍流混乱湍急，不能用「安静」形容其流动。"}, {"text": "湍流很平静，映出了蓝天。", "explanation": "这里应该用〈积水〉。积水平静才能映出蓝天，湍流水面翻涌，映不出清晰的影像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渡船刚出港就遇到一座湍流。", "corrected_sentence": "渡船刚出港就遇到一股湍流。", "error_description": "量词错误：湍流应用「股」，「座」用于山、楼等大型固定物，不能用于水流。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在河边遇到了过湍流。", "corrected_sentence": "我们在河边遇到过湍流。", "error_description": "体标错误：「了」和「过」不能同时用在同一动词后，应说「遇到过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
