INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几个算式放在一起，要一起找到答案。", "primary_collocate": null, "pronunciation": "fāng chéng zǔ", "ipa": "faŋ˥ ʈʂʰɤŋ˧˥ tsu˨˩˦", "syllable_count": 3, "sentences": [{"text": "老师在黑板上写了一个方程组。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方程组有三个算式。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要一起解这个方程组。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题是一个方程组，要找出两个数。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明很快算出了方程组的答案。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方程组太难，我算了很久。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把方程组抄在本子上。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方程组里有两个未知数。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我看看这个方程组。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完这个方程组，我们就下课。", "target_word": "方程组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "方程組", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几个算式放在一起、要一起算出答案的题目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7c84d0d-b658-4011-a3cd-9d3d112aea10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方程组", "is_correct": true, "explanation": "正确：方程组指几个算式放在一起、要一起求出答案的题目，可以写在黑板上。"}, {"text": "诗", "is_correct": false, "explanation": "搭配：「诗」的量词是「首」，「一个」不能修饰诗，应说「写了一首诗」。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以写下的题目，「写了一个颜色」与题目的语义不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然状况，不是可以写在黑板上的题目。"}], "explanations": {"方程组": "正确：方程组指几个算式放在一起、要一起求出答案的题目，可以写在黑板上。", "诗": "搭配：「诗」的量词是「首」，「一个」不能修饰诗，应说「写了一首诗」。", "颜色": "语义：颜色不是可以写下的题目，「写了一个颜色」与题目的语义不符。", "天气": "语义：天气是自然状况，不是可以写在黑板上的题目。"}, "sentence_index": 0, "correct_answer": "方程组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方程组的规律是每项加二。", "explanation": "这里应该用〈数列〉。数列按规律逐项排列，方程组是几个算式放在一起求解，没有「每项加二」这样的逐项规律。"}, {"text": "我在作业本上抄了一根方程组。", "explanation": "这里应该用〈个〉。量词「根」用于细长的条状物，方程组应配「个」。"}, {"text": "这道题的答案是一个方程组。", "explanation": "这里应该用〈答案〉。方程组是题目本身的形式，答案应是求出的数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方程组", "is_correct": true, "explanation": "正确：「抄」的对象可以是题目或文字，方程组可以抄在本子上。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：「抄」的对象是文字或题目，不能抄花朵。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是表情，无法抄写在本子上。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能被抄在本子上。"}], "explanations": {"方程组": "正确：「抄」的对象可以是题目或文字，方程组可以抄在本子上。", "花朵": "搭配：「抄」的对象是文字或题目，不能抄花朵。", "微笑": "语义：微笑是表情，无法抄写在本子上。", "房子": "语义：房子是建筑，不能被抄在本子上。"}, "sentence_index": 6, "correct_answer": "方程组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方程组的意思是「一起」。", "explanation": "这里应该用〈词〉。方程组是数学术语，意思不能释义为「一起」；「一起」是某个词的释义。"}, {"text": "方程组是学习外语的好工具。", "explanation": "这里应该用〈词典〉。方程组是数学中的一组方程，不是学习外语的工具。"}, {"text": "程序里用方程组保存数据。", "explanation": "这里应该用〈数组〉。方程组是一组方程，不能用来保存数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她解了过一个方程组。", "corrected_sentence": "她解过一个方程组。", "error_description": "体标错误：「了」和「过」不能同时用在同一动词后，应说「解过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们把方程组抄笔记本上。", "corrected_sentence": "老师让我们把方程组抄在笔记本上。", "error_description": "介词漏用：「抄」后引出处所要用「在」，应说「抄在笔记本上」，漏掉「在」就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
