INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24296, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客机是专门运送乘客的飞机。", "primary_collocate": null, "pronunciation": "kè jī", "ipa": "kʰɤ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "这架客机每天飞两次。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客机降落在机场的跑道上。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客们走上客机，找到了自己的座位。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是客机的机长，已经飞了二十年。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种客机比货机更讲究舒适。", "target_word": "客机", "complexity_tier": "T3", "furigana": "kè jī", "sentence_source": "generated"}, {"text": "小朋友指着天上的客机大声喊。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客机上有一百多个座位。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从广州到成都，客机要飞三个小时。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在窗边看着一架客机起飞。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新客机的座位又宽又舒服。", "target_word": "客机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一架客机", "label": "量词"}, {"form": "客機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "专门运送乘客的飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24631489-7be5-43ad-b7ec-de458e1dff98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确答案。kè jī 指专门运送乘客的飞机。"}, {"text": "科技", "is_correct": false, "explanation": "kē jì（第一声、第四声）两个音节的声调都与 kè jī 不同，意思是科学技术。"}, {"text": "柯基", "is_correct": false, "explanation": "kē jī（第一声）第一个音节的声调与 kè jī 不同，指柯基犬，不是飞机。"}, {"text": "克己", "is_correct": false, "explanation": "kè jǐ（第四声、第三声）只第二个音节声调不同，意思是克制自己。"}], "explanations": {"客机": "正确答案。kè jī 指专门运送乘客的飞机。", "科技": "kē jì（第一声、第四声）两个音节的声调都与 kè jī 不同，意思是科学技术。", "柯基": "kē jī（第一声）第一个音节的声调与 kè jī 不同，指柯基犬，不是飞机。", "克己": "kè jǐ（第四声、第三声）只第二个音节声调不同，意思是克制自己。"}, "sentence_index": null, "correct_answer": "客机"}, "level_3": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确。客机是航班用的飞机，按航班每天往返，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“飞”用于飞行物，钢琴不能飞，“这架钢琴每天飞两次”搭配不当。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是固定在地面上的建筑，不会飞行，句意不合。"}, {"text": "梯子", "is_correct": false, "explanation": "语义：梯子用于攀登，不能在天空中飞行，句意不合。"}], "explanations": {"客机": "正确。客机是航班用的飞机，按航班每天往返，符合句意。", "钢琴": "搭配：“飞”用于飞行物，钢琴不能飞，“这架钢琴每天飞两次”搭配不当。", "桥": "语义：桥是固定在地面上的建筑，不会飞行，句意不合。", "梯子": "语义：梯子用于攀登，不能在天空中飞行，句意不合。"}, "sentence_index": 0, "correct_answer": "客机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天坐客机去对面的超市买菜。", "explanation": "这里应该用〈公交车〉。客机用于长途运送旅客，去对面超市这类近距离出行要乘公交车。"}, {"text": "我看见一座客机从头顶飞过。", "explanation": "量词用错。客机应该用“架”，“座”多用于山、桥、建筑等大型固定的东西。"}, {"text": "这架客机专门用来运送货物。", "explanation": "这里应该用〈货机〉。客机专门运送乘客，运送货物要用货机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24296, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确答案。kè jī 指专门运送乘客的飞机。"}, {"text": "客籍", "is_correct": false, "explanation": "kè jí（第四声、第二声）只第二个音节声调不同，指客居外地者的籍贯。"}, {"text": "可及", "is_correct": false, "explanation": "kě jí（第三声、第二声）两个音节的声调都与 kè jī 不同，意思是可以达到。"}, {"text": "客居", "is_correct": false, "explanation": "kè jū（第四声、第一声）只韵母不同（i 与 ü），指寄居在外地。"}], "explanations": {"客机": "正确答案。kè jī 指专门运送乘客的飞机。", "客籍": "kè jí（第四声、第二声）只第二个音节声调不同，指客居外地者的籍贯。", "可及": "kě jí（第三声、第二声）两个音节的声调都与 kè jī 不同，意思是可以达到。", "客居": "kè jū（第四声、第一声）只韵母不同（i 与 ü），指寄居在外地。"}, "sentence_index": null, "correct_answer": "客机"}, "level_3": {"options": [{"text": "客机", "is_correct": true, "explanation": "正确。客机是载客飞机，机上有座位，符合“一百多个座位”的语境。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，上面不会有一百多个座位。"}, {"text": "讲台", "is_correct": false, "explanation": "语义：讲台是供人站立讲话的平台，不是载客的交通工具，句中的座位数不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“座位”一般用于车辆、房间、场所，不能用于冰箱。"}], "explanations": {"客机": "正确。客机是载客飞机，机上有座位，符合“一百多个座位”的语境。", "书桌": "语义：书桌是家具，上面不会有一百多个座位。", "讲台": "语义：讲台是供人站立讲话的平台，不是载客的交通工具，句中的座位数不合。", "冰箱": "搭配：“座位”一般用于车辆、房间、场所，不能用于冰箱。"}, "sentence_index": 6, "correct_answer": "客机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这架客机是专门为训练飞行员设计的。", "explanation": "这里应该用〈教练机〉。客机是为运送乘客设计的，训练飞行员要用教练机。"}, {"text": "这架客机专门用于紧急救援。", "explanation": "这里应该用〈直升机〉。客机专门运送乘客，紧急救援通常由直升机完成。"}, {"text": "这架客机在马路上行驶。", "explanation": "这里应该用〈出租车〉。客机是飞机，在天空中飞行，不在马路上行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "跑道旁停着一条客机。", "corrected_sentence": "跑道旁停着一架客机。", "error_description": "量词错误：“客机”是飞机，应该用量词“架”，“条”多用于细长的东西（如船、河、路）。错误形式是“一条客机”，正确形式是“一架客机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几架客机们都很新。", "corrected_sentence": "这几架客机都很新。", "error_description": "后缀错误：“们”用于指人，不能加在“客机”这类无生命的物体后面。错误形式是“客机们”，正确形式是“客机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
