INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24297, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "事情和以前一样，没有变化。", "primary_collocate": null, "pronunciation": "yī rán", "ipa": "i˥˥ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "过了十年，他依然住在这里。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下着雨，他依然去跑步。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她依然是我最好的朋友。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，他依然笑着说话。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的饭菜依然很好吃。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年以后，老城依然那么安静。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试了三次，依然没有成功。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们依然保持着联系。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "已经很晚了，妈妈依然在等我。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都走了，只有他依然坐在那里。", "target_word": "依然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "情况照旧，仍然如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebd53f51-cdf0-46b6-96dd-99270f958475') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24297, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依然", "is_correct": true, "explanation": "正确：依然 yī rán，表示事情仍和以前一样，没有变化。"}, {"text": "易燃", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是容易燃烧。"}, {"text": "一人", "is_correct": false, "explanation": "rén 与 rán 韵母不同（-en 与 -an），意思是一个人。"}, {"text": "已然", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经，多用于书面语。"}], "explanations": {"依然": "正确：依然 yī rán，表示事情仍和以前一样，没有变化。", "易燃": "yì（第四声）与 yī（第一声）声调不同，意思是容易燃烧。", "一人": "rén 与 rán 韵母不同（-en 与 -an），意思是一个人。", "已然": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经，多用于书面语。"}, "sentence_index": null, "correct_answer": "依然"}, "level_3": {"options": [{"text": "依然", "is_correct": true, "explanation": "正确：依然表示状态仍旧不变，与“过了十年”和“住在这里”相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指事情出乎意料地发生，与“过了十年”的长时段相抵触。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚发生不久，与“过了十年”的时间跨度矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”用于即将发生的动作，不能与“过了十年，住在这里”这种长期状态搭配。"}], "explanations": {"依然": "正确：依然表示状态仍旧不变，与“过了十年”和“住在这里”相符。", "突然": "语义：“突然”指事情出乎意料地发生，与“过了十年”的长时段相抵触。", "刚刚": "语义：“刚刚”表示刚发生不久，与“过了十年”的时间跨度矛盾。", "马上": "搭配：“马上”用于即将发生的动作，不能与“过了十年，住在这里”这种长期状态搭配。"}, "sentence_index": 0, "correct_answer": "依然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气依然变冷了。", "explanation": "这里应该用〈突然〉。突然表示事情忽然出现，依然强调没有变化；“变冷”是新出现的变化，应改用突然。"}, {"text": "没想到，他依然考上了重点大学。", "explanation": "这里应该用〈居然〉。居然表示出乎意料，前面的“没想到”说明这是意外结果；依然表示和以前一样，不表示意外，应改用居然。"}, {"text": "昨天还下大雨，今天依然放晴了。", "explanation": "这里应该用〈竟然〉。依然表示照旧，昨天下雨、今天放晴是变化，应改用竟然表示出乎意料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依然", "is_correct": true, "explanation": "正确：依然表示尽管如此仍然，与“试了三次”的反复尝试相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上完成，与“试了三次”的反复过程矛盾。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”表示时间很短，与“试了三次”的持续尝试不符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指即刻发生，与“试了三次”的反复过程相抵，“马上没有成功”不通。"}], "explanations": {"依然": "正确：依然表示尽管如此仍然，与“试了三次”的反复尝试相符。", "立刻": "语义：“立刻”表示马上完成，与“试了三次”的反复过程矛盾。", "很快": "语义：“很快”表示时间很短，与“试了三次”的持续尝试不符。", "马上": "语义：“马上”指即刻发生，与“试了三次”的反复过程相抵，“马上没有成功”不通。"}, "sentence_index": 6, "correct_answer": "依然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过很久的等待，他依然坐到了座位上。", "explanation": "这里应该用〈终于〉。依然表示没有变化，“坐到座位上”是等待之后才出现的变化，应改用终于。"}, {"text": "他十二岁依然学会游泳。", "explanation": "这里应该用〈才〉。依然表示照旧，“学会游泳”出现得晚，表示晚才发生应改用才。"}, {"text": "树叶依然变红了。", "explanation": "这里应该用〈逐渐〉。依然表示没有变化，“变红”是逐渐发生的变化，应改用逐渐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他经历了那么多，依然没有依然放弃梦想。", "corrected_sentence": "他经历了那么多，依然没有放弃梦想。", "error_description": "“依然”在同一小句中只出现一次；本句“没有”后又重复出现“依然”，应删去第二个“依然”，说“依然没有放弃梦想”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "分开这么久，我们依然好朋友。", "corrected_sentence": "分开这么久，我们依然是好朋友。", "error_description": "“依然是好朋友”中判断词“是”不能省略；应说“我们依然是好朋友”，不说“我们依然好朋友”，少了“是”句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
