INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开动车子让它走。", "primary_collocate": null, "pronunciation": "jià shǐ", "ipa": "tɕja˥˩ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "哥哥刚拿到驾照，今天第一次驾驶汽车上路。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在喝酒后驾驶车辆。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他驾驶着一辆旧卡车去了城里。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨天驾驶汽车一定要慢一点。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天驾驶小汽车送孩子上学。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很窄，驾驶时要特别小心。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷七十岁了，还能驾驶拖拉机。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他驾驶过很多种车，但最爱这辆越野车。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友太累了，我来驾驶这辆车。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手驾驶汽车上高速路，容易紧张。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驾驶着", "label": "体标"}, {"form": "驾驶过", "label": "体标"}, {"form": "驾驶员", "label": "复合"}, {"form": "駕駛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "驾驶|开动汽车等车辆让它行驶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7c84d0d-b658-4011-a3cd-9d3d112aea10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。驾驶 jià shǐ，指开动车辆使其行驶。"}, {"text": "假使", "is_correct": false, "explanation": "jiǎ shǐ（第三声）与 jià shǐ（第四声）声调不同，意思是“假使”，表示假设。"}, {"text": "家事", "is_correct": false, "explanation": "jiā shì 与 jià shǐ 声调都不同，意思是“家里的事情”。"}, {"text": "驾师", "is_correct": false, "explanation": "jià shī 与 jià shǐ 第二音节声调不同（第一声与第三声），意思是“驾驶教练”。"}], "explanations": {"驾驶": "正确。驾驶 jià shǐ，指开动车辆使其行驶。", "假使": "jiǎ shǐ（第三声）与 jià shǐ（第四声）声调不同，意思是“假使”，表示假设。", "家事": "jiā shì 与 jià shǐ 声调都不同，意思是“家里的事情”。", "驾师": "jià shī 与 jià shǐ 第二音节声调不同（第一声与第三声），意思是“驾驶教练”。"}, "sentence_index": null, "correct_answer": "驾驶"}, "level_3": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。“驾驶汽车上路”指亲自开车，与“拿到驾照”的语境相符。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”用于自行车、摩托车等，不能说“骑汽车”。"}, {"text": "坐", "is_correct": false, "explanation": "语义：“坐”是乘客的动作，与句中“拿到驾照、第一次……上路”的语境相反。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”不表示上路行驶，与“第一次……上路”的语境不合。"}], "explanations": {"驾驶": "正确。“驾驶汽车上路”指亲自开车，与“拿到驾照”的语境相符。", "骑": "搭配：“骑”用于自行车、摩托车等，不能说“骑汽车”。", "坐": "语义：“坐”是乘客的动作，与句中“拿到驾照、第一次……上路”的语境相反。", "修理": "语义：“修理”不表示上路行驶，与“第一次……上路”的语境不合。"}, "sentence_index": 0, "correct_answer": "驾驶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨天驾驶自行车一定要慢一点。", "explanation": "这里应该用〈骑〉。驾驶用于汽车、船只等机动交通工具，自行车要用“骑”。"}, {"text": "汽车在山路上驾驶自己，一定要慢一点。", "explanation": "这里应该用〈行驶〉。车辆自己运行要用“行驶”，驾驶的动作者是人。"}, {"text": "骑手驾驶着烈马，一定要慢一点。", "explanation": "这里应该用〈驾驭〉。驾驶用于交通工具，烈马要用“驾驭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24300, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。驾驶 jià shǐ，指开动车辆使其行驶。"}, {"text": "家史", "is_correct": false, "explanation": "jiā shǐ（第一声）与 jià shǐ（第四声）第一音节声调不同，意思是“家族的历史”。"}, {"text": "加湿", "is_correct": false, "explanation": "jiā shī 与 jià shǐ 两个音节声调都不同，意思是“增加空气湿度”。"}, {"text": "架势", "is_correct": false, "explanation": "jià shì 与 jià shǐ 第二音节声调不同（第四声与第三声），意思是“姿势、样子”。"}], "explanations": {"驾驶": "正确。驾驶 jià shǐ，指开动车辆使其行驶。", "家史": "jiā shǐ（第一声）与 jià shǐ（第四声）第一音节声调不同，意思是“家族的历史”。", "加湿": "jiā shī 与 jià shǐ 两个音节声调都不同，意思是“增加空气湿度”。", "架势": "jià shì 与 jià shǐ 第二音节声调不同（第四声与第三声），意思是“姿势、样子”。"}, "sentence_index": null, "correct_answer": "驾驶"}, "level_3": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。“驾驶拖拉机”指操纵拖拉机，与“还能”的语境相符。"}, {"text": "摘", "is_correct": false, "explanation": "语义：拖拉机不能摘，“还能摘拖拉机”与句意不合。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，不能与“拖拉机”搭配。"}, {"text": "喂", "is_correct": false, "explanation": "语义：拖拉机不是可以喂养的对象，“还能喂拖拉机”不通。"}], "explanations": {"驾驶": "正确。“驾驶拖拉机”指操纵拖拉机，与“还能”的语境相符。", "摘": "语义：拖拉机不能摘，“还能摘拖拉机”与句意不合。", "戴": "搭配：“戴”用于帽子、眼镜等，不能与“拖拉机”搭配。", "喂": "语义：拖拉机不是可以喂养的对象，“还能喂拖拉机”不通。"}, "sentence_index": 6, "correct_answer": "驾驶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牧羊人驾驶羊群回家，很辛苦。", "explanation": "这里应该用〈驱赶〉。驾驶用于交通工具，赶羊群要用“驱赶”。"}, {"text": "工人驾驶刀具切割钢板，要特别小心。", "explanation": "这里应该用〈使用〉。驾驶用于车辆等交通工具，切割用的刀具要用“使用”。"}, {"text": "将军驾驶部队上高速路，容易紧张。", "explanation": "这里应该用〈指挥〉。驾驶的对象是交通工具，部队要用“指挥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来没驾驶了汽车。", "corrected_sentence": "我从来没驾驶过汽车。", "error_description": "“从来没”后表示经历要用“过”，不能用“了”，应说“从来没驾驶过汽车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈驾驶地很小心。", "corrected_sentence": "妈妈驾驶得很小心。", "error_description": "“地”用在动词前作状语，动词后作程度补语要用“得”，应说“驾驶得很小心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
