INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抬头和低头，比如人一会儿看天一会儿看地。", "primary_collocate": null, "pronunciation": "fǔ yǎng", "ipa": "fu˨˩˦ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他站在山顶，俯仰天地，心里很平静。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我做几次头部俯仰的动作。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸡吃米时，头不停地俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的头随着音乐轻轻俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一会儿看黑板，一会儿看本子，头不停俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子躺在草地上，随着云朵的移动，头不停地俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "furigana": "háizi tǎng zài cǎodì shàng, suízhe yúnduǒ de yídòng, tóu bù tíng de fǔyǎng", "sentence_source": "generated"}, {"text": "做颈部运动时，要慢慢俯仰，不要太快。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "啄木鸟的头一直在俯仰，不停地啄树。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在车里，头随着车的晃动俯仰着。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的白鹭俯仰着，一会儿喝水一会儿看天。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "俯仰着", "label": "体标"}, {"form": "俯仰了", "label": "体标"}, {"form": "俯仰角", "label": "复合"}], "register": "中性", "sense_fingerprint": "俯仰|头部一低一抬的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7c84d0d-b658-4011-a3cd-9d3d112aea10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "俯仰", "is_correct": true, "explanation": "正确：「俯仰天地」指抬头看天、低头看地，与站在山顶的环境相符。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：「修剪」指剪去多余的枝叶，用于天地不合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清除脏物，用于天地没有意义。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」只用于生物，不能搭配「天地」。"}], "explanations": {"俯仰": "正确：「俯仰天地」指抬头看天、低头看地，与站在山顶的环境相符。", "修剪": "语义：「修剪」指剪去多余的枝叶，用于天地不合语境。", "打扫": "语义：「打扫」指清除脏物，用于天地没有意义。", "喂养": "搭配：「喂养」只用于生物，不能搭配「天地」。"}, "sentence_index": 0, "correct_answer": "俯仰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他俯仰着向左右张望，没有说话。", "explanation": "这里应该用〈转头〉。「俯仰」指头部上下低抬，左右转动要用〈转头〉。"}, {"text": "时间过得真快，俯仰之间一个下午就没了。", "explanation": "这里是另一义项〈时间很短〉，与头部一低一抬的动作无关；「俯仰之间」不能用来说一个下午这样的时段。"}, {"text": "他俯仰着说不行。", "explanation": "这里应该用〈摇头〉。俯仰指头部上下低抬，表示否定要左右摇头，不能用俯仰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "俯仰", "is_correct": true, "explanation": "正确：「慢慢俯仰」指头部缓慢地低抬，与颈部运动相符。"}, {"text": "弹奏", "is_correct": false, "explanation": "搭配：「弹奏」需要乐器作对象，不能用于颈部运动。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「游泳」是在水中划动身体，与颈部运动的情境不合。"}, {"text": "书写", "is_correct": false, "explanation": "语义：「书写」是写字，与做颈部运动无关。"}], "explanations": {"俯仰": "正确：「慢慢俯仰」指头部缓慢地低抬，与颈部运动相符。", "弹奏": "搭配：「弹奏」需要乐器作对象，不能用于颈部运动。", "游泳": "语义：「游泳」是在水中划动身体，与颈部运动的情境不合。", "书写": "语义：「书写」是写字，与做颈部运动无关。"}, "sentence_index": 6, "correct_answer": "俯仰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫一俯仰跳上了窗台。", "explanation": "这里应该用〈纵身〉。俯仰指头部一低一抬，不能描述整个身体跃起。"}, {"text": "她轻轻俯仰手，向我挥手告别。", "explanation": "这里应该用〈摆〉。俯仰只指头部上下低抬，不能用于手的动作，手的摆动要用〈摆〉。"}, {"text": "她摇摇头，俯仰着表示不愿意。", "explanation": "俯仰指头部上下低抬，与左右摇头的动作相反，这里不能用俯仰来表示左右摇动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸡吃米时，头俯仰地很快。", "corrected_sentence": "小鸡吃米时，头俯仰得很快。", "error_description": "「地」误用。「俯仰」后带程度补语「很快」时须用「得」，不用「地」，应为「俯仰得很快」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸭子在水里俯仰了觅食。", "corrected_sentence": "小鸭子在水里俯仰着觅食。", "error_description": "体标误用。表示动作持续进行要在「俯仰」后用「着」，不能用「了」，应说「俯仰着觅食」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "飞机或船走错了方向。", "primary_collocate": null, "pronunciation": "piān háng", "ipa": "pʰiɛn˥ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "飞机偏航了，塔台马上通知飞行员。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在大海上偏航，船长一直没发现。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，小船偏航了很远。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长看错了地图，轮船就偏航了。", "target_word": "偏航", "complexity_tier": "T3", "furigana": "piān háng", "sentence_source": "generated"}, {"text": "这架飞机为什么偏航？因为指南针坏了。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船遇到大风，偏航到了别的海域。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开的游艇偏航了，差点撞上礁石。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员发现飞机偏航，赶紧回到原来的方向。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾太大，船长看不见灯塔，船偏航了。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方向舵坏了，飞机一直向右偏航。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏航了", "label": "体标（了）"}, {"form": "偏航过", "label": "体标（过）"}, {"form": "偏航角", "label": "复合词"}], "register": "中性", "sense_fingerprint": "飞机或船走错方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963f0013-655e-4f45-a7f7-7aacd94fb341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：飞机偏离航线，塔台通知飞行员。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”与飞机偏离航线无关，不能描述飞机的这种状态。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出新芽，与飞机偏离航线无关，不能用于飞机。"}, {"text": "停课", "is_correct": false, "explanation": "语义：“停课”指学校停止上课，不能用于飞机。"}], "explanations": {"偏航": "正确：飞机偏离航线，塔台通知飞行员。", "充电": "语义：“充电”与飞机偏离航线无关，不能描述飞机的这种状态。", "发芽": "语义：“发芽”指植物长出新芽，与飞机偏离航线无关，不能用于飞机。", "停课": "语义：“停课”指学校停止上课，不能用于飞机。"}, "sentence_index": 0, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山里偏航了，找不到回家的路。", "explanation": "这里应该用〈迷路〉。偏航只用于飞机、船只偏离航线，人在陆地上走错路说迷路。"}, {"text": "火车因为大雾偏航了，比原定时间晚到。", "explanation": "这里应该用〈误点〉。偏航专指飞机、船只偏离航线，火车晚到用误点。"}, {"text": "他因为堵车偏航了，错过了会议。", "explanation": "这里应该用〈迟到〉。偏航不用于人的时间延误，赶不上会议说迟到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：游艇偏离航线，差点撞上礁石。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：“发霉”指物品长霉，与撞上礁石的情境无关。"}, {"text": "褪色", "is_correct": false, "explanation": "语义：“褪色”指颜色变淡，不能解释游艇差点撞上礁石。"}, {"text": "降价", "is_correct": false, "explanation": "搭配：“降价”指商品价格下降，不能用于描述游艇的运行状态。"}], "explanations": {"偏航": "正确：游艇偏离航线，差点撞上礁石。", "发霉": "语义：“发霉”指物品长霉，与撞上礁石的情境无关。", "褪色": "语义：“褪色”指颜色变淡，不能解释游艇差点撞上礁石。", "降价": "搭配：“降价”指商品价格下降，不能用于描述游艇的运行状态。"}, "sentence_index": 6, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饼干在盘子里偏航了，挪到了盘边。", "explanation": "这里应该用〈挪动〉。偏航只用于飞机、船只偏离航线，饼干在盘子里挪位置应说挪动。"}, {"text": "画框偏航了，我把它扶正了。", "explanation": "这里应该用〈歪〉。偏航只用于飞机、船只，挂在墙上的画框歪了说歪。"}, {"text": "书从桌上偏航到了地上。", "explanation": "这里应该用〈滑落〉。偏航用于航行器，书本从桌上掉落说滑落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔船在雾里偏航的很远，船员用罗盘重新定位。", "corrected_sentence": "渔船在雾里偏航得很远，船员用罗盘重新定位。", "error_description": "错误：补语标记用了“的”（偏航的很远）；正确：“得”。“得”引出动词后的状态补语，“的”不能接在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游艇没偏航了，一直按原定航线行驶。", "corrected_sentence": "游艇没偏航，一直按原定航线行驶。", "error_description": "错误：否定句中用了“了”（没偏航了）；正确：“没偏航”，否定已发生的动作不带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
