INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24312, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或机器让东西动起来。", "primary_collocate": null, "pronunciation": "cāo zòng", "ipa": "tsʰɑʊ˥ tsʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "工人正在操纵起重机吊货。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用双手操纵着方向盘。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机熟练地操纵着挖掘机。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用手柄操纵游戏里的小人。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器很简单，一个人就能操纵。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次操纵机械手臂，动作很慢。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生通过屏幕操纵着手术机器人。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在学习怎样操纵这台新机床。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用左手轻轻操纵着摇杆。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，已经操纵不了那台拖拉机。", "target_word": "操纵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "操纵着", "label": "体标"}, {"form": "操纵了", "label": "体标"}, {"form": "操纵者", "label": "复合"}, {"form": "操縱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "操纵|用手或机器操作器械使其动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7c84d0d-b658-4011-a3cd-9d3d112aea10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操纵", "is_correct": true, "explanation": "正确：「操纵起重机」指用机械操作起重机，与吊货的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」是修复坏掉的东西，与句中「吊货」的动作不符。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」用于动物或幼儿，不能搭配起重机。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：「擦拭」是擦干净，与句中吊货的动作无关。"}], "explanations": {"操纵": "正确：「操纵起重机」指用机械操作起重机，与吊货的语境相符。", "修理": "语义：「修理」是修复坏掉的东西，与句中「吊货」的动作不符。", "喂养": "搭配：「喂养」用于动物或幼儿，不能搭配起重机。", "擦拭": "语义：「擦拭」是擦干净，与句中吊货的动作无关。"}, "sentence_index": 0, "correct_answer": "操纵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天操纵一封信。", "explanation": "这里应该用〈写〉。操纵指用手或机器使东西动起来，写信要用〈写〉。"}, {"text": "她操纵了一杯牛奶。", "explanation": "这里应该用〈喝〉。操纵指用手或机器使东西动起来，喝牛奶要用〈喝〉。"}, {"text": "奶奶在厨房操纵晚饭。", "explanation": "这里应该用〈烹饪〉。操纵用于操作器械，做饭要说〈烹饪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操纵", "is_correct": true, "explanation": "正确：「通过屏幕操纵」指远程操控机器人，与手术机器人的语境相符。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：「清洗」是把东西洗干净，无法通过屏幕完成对手术机器人的清洗。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」只用于活的生物，不能用于手术机器人。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：「拥抱」是用手臂环抱人或物，与隔着屏幕操作手术机器人的情境不合。"}], "explanations": {"操纵": "正确：「通过屏幕操纵」指远程操控机器人，与手术机器人的语境相符。", "清洗": "语义：「清洗」是把东西洗干净，无法通过屏幕完成对手术机器人的清洗。", "喂养": "搭配：「喂养」只用于活的生物，不能用于手术机器人。", "拥抱": "语义：「拥抱」是用手臂环抱人或物，与隔着屏幕操作手术机器人的情境不合。"}, "sentence_index": 6, "correct_answer": "操纵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用尺子操纵桌子的长度。", "explanation": "这里应该用〈测量〉。操纵指用手或机器使东西动起来，量长度要用〈测量〉。"}, {"text": "姐姐在墙上操纵了一幅画。", "explanation": "这里应该用〈装饰〉。操纵指操作器械，把画挂在墙上装饰要用〈装饰〉。"}, {"text": "他仔细操纵新型机床的结构。", "explanation": "这里应该用〈研究〉。操纵是操作器械使其动作，研究结构要用〈研究〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他再操纵起重机了。", "corrected_sentence": "他又操纵起重机了。", "error_description": "副词误用。「再」表示尚未发生的重复，已经发生的重复要用「又」，应说「又操纵起重机了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他操纵地很稳。", "corrected_sentence": "他操纵得很稳。", "error_description": "「地」误用。动词后表示程度的补语要用「得」，不用「地」；「地」用在动词前作状语。此处应说「他操纵得很稳」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa17407f-921e-4e00-a99f-899c413daa56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
