INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24314, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制定就是定下计划或规矩。", "primary_collocate": null, "pronunciation": "zhì dìng", "ipa": "ʈʂɻ̩⁵¹ tiŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "学校制定了新的规定。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起制定学习计划吧。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司制定了明年的目标。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给大家制定了一个计划。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府制定过很多新的政策。", "target_word": "制定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想制定一个减肥的计划。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家制定法律，大家都要遵守。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先制定好规则，再开始比赛。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划是谁制定的？", "target_word": "制定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们已经制定了旅行路线。", "target_word": "制定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "制定了", "label": "体标"}, {"form": "制定过", "label": "体标"}], "register": "书面", "sense_fingerprint": "定下计划、规定、法律等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e621cd-3813-46e8-abfa-9d13f45d7637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说吃规定。"}, {"text": "制定", "is_correct": true, "explanation": "正确：学校定下规定，与“新的规定”相合。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指物体掉落或碰撞，与定下规定的意思不相干。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，不能说唱规定。"}], "explanations": {"吃": "搭配：“吃”的宾语是食物，不能说吃规定。", "制定": "正确：学校定下规定，与“新的规定”相合。", "摔": "语义：“摔”指物体掉落或碰撞，与定下规定的意思不相干。", "唱": "搭配：“唱”的宾语是歌曲，不能说唱规定。"}, "sentence_index": 0, "correct_answer": "制定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们制定了一个新的学习小组。", "explanation": "这里应该用〈建立〉。成立组织、团体要用建立，制定只用于计划或规定。"}, {"text": "他制定了一座新房子。", "explanation": "这里应该用〈设计〉。画图构思房屋要用设计，制定只用于计划或规定。"}, {"text": "科学家制定了水的温度。", "explanation": "这里应该用〈测定〉。测量数值要用测定，制定不用于测量数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进入", "is_correct": false, "explanation": "配价：“进入”带的是处所或领域，不能以“法律”作宾语来表示定下法律。"}, {"text": "搞定", "is_correct": false, "explanation": "语域：“搞定”是口语，指把事情办妥，用在法律条文上语域不合。"}, {"text": "制定", "is_correct": true, "explanation": "正确：国家定下法律，与“大家都要遵守”前后呼应。"}, {"text": "出席", "is_correct": false, "explanation": "配价：“出席”带的是会议或场合，不能以“法律”作宾语。"}], "explanations": {"进入": "配价：“进入”带的是处所或领域，不能以“法律”作宾语来表示定下法律。", "搞定": "语域：“搞定”是口语，指把事情办妥，用在法律条文上语域不合。", "制定": "正确：国家定下法律，与“大家都要遵守”前后呼应。", "出席": "配价：“出席”带的是会议或场合，不能以“法律”作宾语。"}, "sentence_index": 6, "correct_answer": "制定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们制定了一部电影。", "explanation": "这里应该用〈拍摄〉。拍电影要用拍摄，制定不能用于制作影片。"}, {"text": "他制定了一桌好菜。", "explanation": "这里应该用〈做〉。做菜要用做，制定只用于计划或规定。"}, {"text": "她制定了一首歌。", "explanation": "这里应该用〈写〉。创作歌曲要用写，制定只用于计划或规定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份方案是谁制定了的？", "corrected_sentence": "这份方案是谁制定的？", "error_description": "错误形式：“制定了的”；正确形式：“制定的”。“是……的”句式中动词后不加“了”，应直接用“制定的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这套标准制定很严格。", "corrected_sentence": "他把这套标准制定得很严格。", "error_description": "错误形式：“制定很严格”；正确形式：“制定得很严格”。动词后带程度补语时要用“得”连接，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
