INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "飞机从地面飞上天。", "primary_collocate": null, "pronunciation": "qǐ fēi", "ipa": "tɕʰi²¹⁴ fei⁵⁵", "syllable_count": 2, "sentences": [{"text": "飞机已经起飞了，现在在天上。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起飞时，飞机的速度越来越快。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的飞机十点起飞，九点要到机场。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞以后，我看见城市变小了。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在跑道尽头慢慢转弯，准备起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员说，飞机五分钟后起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾散了以后，第一架飞机起飞了。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起飞的时候，我的耳朵有点不舒服。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机还没起飞，请把手机关掉。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风太大，所有的飞机都不能起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起飞了", "label": "体标"}, {"form": "起飞过", "label": "体标"}, {"form": "起飞线", "label": "复合"}], "register": "通用", "sense_fingerprint": "飞机离开地面，飞上天空", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963f0013-655e-4f45-a7f7-7aacd94fb341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”指飞机离开地面，与“现在在天上”的状态相衔接。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”是从空中落回地面，与“现在在天上”矛盾。"}, {"text": "下课", "is_correct": false, "explanation": "搭配：“下课”指学校结束上课，不用于飞机。"}, {"text": "睡醒", "is_correct": false, "explanation": "搭配：“睡醒”只用于人或动物，飞机不能睡醒。"}], "explanations": {"起飞": "正确：“起飞”指飞机离开地面，与“现在在天上”的状态相衔接。", "降落": "语义：“降落”是从空中落回地面，与“现在在天上”矛盾。", "下课": "搭配：“下课”指学校结束上课，不用于飞机。", "睡醒": "搭配：“睡醒”只用于人或动物，飞机不能睡醒。"}, "sentence_index": 0, "correct_answer": "起飞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机在空中起飞了两个小时。", "explanation": "这里应该用〈飞行〉。起飞指离开地面的那一刻，不能表示持续两个小时。"}, {"text": "妹妹明天早上起飞去西藏。", "explanation": "这里应该用〈启程〉。起飞只用于飞机、火箭等飞行器离开地面，人踏上旅途要说启程。"}, {"text": "发动机终于起飞了。", "explanation": "这里应该用〈启动〉。发动机是启动，起飞指飞行器离开地面，不能用于发动机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”指飞机离开地面，与“大雾散了以后”的时间顺序相符。"}, {"text": "迷路", "is_correct": false, "explanation": "搭配：“迷路”指人或动物找不到方向，飞机不说迷路。"}, {"text": "放学", "is_correct": false, "explanation": "搭配：“放学”指学生离开学校，不用于飞机。"}, {"text": "停飞", "is_correct": false, "explanation": "语义：“停飞”表示停止飞行，与“第一架飞机”在雾散后起飞的情形相反。"}], "explanations": {"起飞": "正确：“起飞”指飞机离开地面，与“大雾散了以后”的时间顺序相符。", "迷路": "搭配：“迷路”指人或动物找不到方向，飞机不说迷路。", "放学": "搭配：“放学”指学生离开学校，不用于飞机。", "停飞": "语义：“停飞”表示停止飞行，与“第一架飞机”在雾散后起飞的情形相反。"}, "sentence_index": 6, "correct_answer": "起飞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹妹每天七点就起飞。", "explanation": "这里应该用〈起床〉。起飞用于飞机、火箭等飞行器，人醒来起身要说起床。"}, {"text": "这艘渔船明天凌晨起飞，去海上捕鱼。", "explanation": "这里应该用〈启航〉。起飞指飞行器离开地面，船只离岸出海要说启航。"}, {"text": "电梯从一楼起飞到十楼。", "explanation": "这里应该用〈上升〉。电梯在楼层之间运行，不是飞行器离地，要说上升。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的班机向杭州起飞。", "corrected_sentence": "我们的班机从杭州起飞。", "error_description": "错误：“向杭州起飞”。“向”表示朝某个方向去，而“起飞”的出发地要用“从”引出；正确的说法是“从杭州起飞”，“从杭州”表示起点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雾一散，第一架飞机就把起飞了。", "corrected_sentence": "雾一散，第一架飞机就起飞了。", "error_description": "错误：多了“把”。“把”字句要求“把”后接受事宾语，“起飞”是不及物动词，不能带受事，应删去“把”，说“雾一散，第一架飞机就起飞了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
