INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "力让东西转动的力量大小。", "primary_collocate": null, "pronunciation": "lì jǔ", "ipa": "li⁵¹ tɕy²¹⁴", "syllable_count": 2, "sentences": [{"text": "推门的位置离门轴越远，力矩越大。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用长扳手拧螺丝，力矩比较大。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力矩越大，轮子越容易转起来。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩坐在跷跷板的远端，力矩更大。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我推门时，离门轴近的地方力矩很小。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师测量了发动机的力矩。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力矩的大小和力的大小有关。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力矩不够大，螺丝就拧不动。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用的力不大，但力臂很长，所以力矩不小。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的力矩大，上坡时就更有力。", "target_word": "力矩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "气动力矩", "label": "复合"}, {"form": "合力矩", "label": "复合"}], "register": "科技", "sense_fingerprint": "通俗说法：力让物体转动的力量有多大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '963f0013-655e-4f45-a7f7-7aacd94fb341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力矩", "is_correct": true, "explanation": "正确：力矩表示使物体转动的作用大小，随力臂增长而增大，与句意相合。"}, {"text": "声音", "is_correct": false, "explanation": "语义：推门位置离门轴远近不会使声音变大，句中说的是转动作用。"}, {"text": "温度", "is_correct": false, "explanation": "语义：门轴的远近与温度无关，句意说的是转动作用。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”不能随推门位置而“越大”，二者没有这样的关系。"}], "explanations": {"力矩": "正确：力矩表示使物体转动的作用大小，随力臂增长而增大，与句意相合。", "声音": "语义：推门位置离门轴远近不会使声音变大，句中说的是转动作用。", "温度": "语义：门轴的远近与温度无关，句意说的是转动作用。", "亮度": "搭配：“亮度”不能随推门位置而“越大”，二者没有这样的关系。"}, "sentence_index": 0, "correct_answer": "力矩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的力矩很温和。", "explanation": "这里应该用〈性格〉。力矩指使物体转动的作用，不能用来形容人的性格。"}, {"text": "他跑步的力矩很快。", "explanation": "这里应该用〈速度〉。力矩是使物体转动的作用，不能用来说跑步的快慢。"}, {"text": "这个月的力矩很高。", "explanation": "这里不能用力矩。它只描述使物体转动的作用，不能用来说数量或收入的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力矩", "is_correct": true, "explanation": "正确：力矩的大小由力和力臂决定，与“和力的大小有关”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”没有“大小”，不能说“颜色的大小”。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积的大小与力的大小无关，句中是力学关系。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积的大小与力的大小无关，句中是力学关系。"}], "explanations": {"力矩": "正确：力矩的大小由力和力臂决定，与“和力的大小有关”相合。", "颜色": "搭配：“颜色”没有“大小”，不能说“颜色的大小”。", "面积": "语义：面积的大小与力的大小无关，句中是力学关系。", "体积": "语义：体积的大小与力的大小无关，句中是力学关系。"}, "sentence_index": 6, "correct_answer": "力矩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水的力矩很大。", "explanation": "这里应该用〈压力〉。力矩指使物体转动的作用，不能用来说水对容器的压迫。"}, {"text": "这个电路的力矩很高。", "explanation": "这里应该用〈电压〉。力矩不能用来说电路的电压高低。"}, {"text": "今天的力矩很低。", "explanation": "这里应该用〈气温〉。力矩不能用来说天气的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "拧这颗螺丝需要一根足够大的力矩。", "corrected_sentence": "拧这颗螺丝需要一个足够大的力矩。", "error_description": "错误：量词用错。“力矩”应用量词“个”，“根”多用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆汽车能喝很大的力矩。", "corrected_sentence": "这辆汽车能产生很大的力矩。", "error_description": "错误：“喝”不能与“力矩”搭配。“力矩”应与“产生”搭配，应说“能产生很大的力矩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16db58d5-d28a-4c23-980d-14b2cddee96a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24330, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收拢", "is_correct": true, "explanation": "收拢：把展开的东西收回、合起来，与“展开”的意思相反。"}, {"text": "思考", "is_correct": false, "explanation": "思考：用脑子想问题，与“展开”没有相反关系。"}, {"text": "奔跑", "is_correct": false, "explanation": "奔跑：快速地跑动，与“展开”没有相反关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：用声音演唱曲调，与“展开”没有相反关系。"}], "correct_answer": "收拢", "explanations": {"收拢": "收拢：把展开的东西收回、合起来，与“展开”的意思相反。", "思考": "思考：用脑子想问题，与“展开”没有相反关系。", "奔跑": "奔跑：快速地跑动，与“展开”没有相反关系。", "唱歌": "唱歌：用声音演唱曲调，与“展开”没有相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24330, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合拢", "is_correct": true, "explanation": "合拢：两边靠拢、闭合，与“展开双臂”的动作相反。"}, {"text": "散步", "is_correct": false, "explanation": "散步：慢慢地走，与“展开”没有相反关系。"}, {"text": "阅读", "is_correct": false, "explanation": "阅读：看书报并理解其内容，与“展开”没有相反关系。"}, {"text": "计算", "is_correct": false, "explanation": "计算：按数学方法求得数量，与“展开”没有相反关系。"}], "correct_answer": "合拢", "explanations": {"合拢": "合拢：两边靠拢、闭合，与“展开双臂”的动作相反。", "散步": "散步：慢慢地走，与“展开”没有相反关系。", "阅读": "阅读：看书报并理解其内容，与“展开”没有相反关系。", "计算": "计算：按数学方法求得数量，与“展开”没有相反关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把手臂、手掌、手指等向外伸开。", "primary_collocate": null, "pronunciation": "zhǎn kāi", "ipa": "ʈʂan˨˩˦ kʰaɪ˥˥", "syllable_count": 2, "sentences": [{"text": "他展开双臂，抱住了我。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子展开小手，笑了。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她展开手掌，里面有一颗糖。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我展开手指。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人展开双手，迎接客人。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向我展开双臂。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把手展开，放在桌上。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩展开手臂，转起圈来。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他展开十个手指，数了数。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸展开双臂，让孩子跳进来。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "展开了", "label": "完成体"}, {"form": "展开着", "label": "持续体"}, {"form": "展开过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把手臂、手掌、手指等向外伸开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8803a-6dd5-492a-a974-71a190af6a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24330, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "展开", "is_correct": true, "explanation": "展开（zhǎn kāi）：把手臂、手掌等向外伸开。"}, {"text": "闪开", "is_correct": false, "explanation": "闪开（shǎn kāi）：躲开、让开。与 zhǎn 只差声母 sh／zh。"}, {"text": "长开", "is_correct": false, "explanation": "长开（zhǎng kāi）：容貌随年龄逐渐长成。与 zhǎn 只差韵尾 ng／n。"}, {"text": "站开", "is_correct": false, "explanation": "站 zhàn（第四声）与 zhǎn（第三声）声调不同，意思是站开。"}], "explanations": {"展开": "展开（zhǎn kāi）：把手臂、手掌等向外伸开。", "闪开": "闪开（shǎn kāi）：躲开、让开。与 zhǎn 只差声母 sh／zh。", "长开": "长开（zhǎng kāi）：容貌随年龄逐渐长成。与 zhǎn 只差韵尾 ng／n。", "站开": "站 zhàn（第四声）与 zhǎn（第三声）声调不同，意思是站开。"}, "sentence_index": null, "correct_answer": "展开"}, "level_3": {"options": [{"text": "展开", "is_correct": true, "explanation": "正确：展开双臂是把双臂伸开，与“抱住了我”的动作相合。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”是割开、分开，与拥抱的动作不符。"}, {"text": "掏出", "is_correct": false, "explanation": "搭配：“掏出”的对象是东西，不说“掏出双臂”。"}, {"text": "扩张", "is_correct": false, "explanation": "搭配：“扩张”多用于范围、势力，不说“扩张双臂”。"}], "explanations": {"展开": "正确：展开双臂是把双臂伸开，与“抱住了我”的动作相合。", "切割": "语义：“切割”是割开、分开，与拥抱的动作不符。", "掏出": "搭配：“掏出”的对象是东西，不说“掏出双臂”。", "扩张": "搭配：“扩张”多用于范围、势力，不说“扩张双臂”。"}, "sentence_index": 0, "correct_answer": "展开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他展开嘴，说了一句话。", "explanation": "这里应该用〈张开〉。展开多指把卷起或折叠的东西铺平，或伸直手臂、手指；嘴巴张开要用“张开”。"}, {"text": "他展开了窗户。", "explanation": "这里应该用〈推开〉。窗户要推开或拉开，“展开”指把卷起或折叠的东西铺平或伸直，窗户不能这样。"}, {"text": "他把杯子里的水展开了。", "explanation": "这里应该用〈倒〉。“展开”指把卷起或折叠的东西铺平或伸直，水不能展开，应该说“倒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展开", "is_correct": true, "explanation": "正确：把手伸开，才能平放在桌上。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”是把物体割成两半，与“放在桌上”的要求不符。"}, {"text": "摘下", "is_correct": false, "explanation": "搭配：“摘下”用于帽子、眼镜等可取下的东西，手不能摘下。"}, {"text": "脱掉", "is_correct": false, "explanation": "搭配：“脱掉”用于衣服、鞋袜，不用于手。"}], "explanations": {"展开": "正确：把手伸开，才能平放在桌上。", "切开": "语义：“切开”是把物体割成两半，与“放在桌上”的要求不符。", "摘下": "搭配：“摘下”用于帽子、眼镜等可取下的东西，手不能摘下。", "脱掉": "搭配：“脱掉”用于衣服、鞋袜，不用于手。"}, "sentence_index": 6, "correct_answer": "展开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他展开眼睛，看见了太阳。", "explanation": "这里应该用〈睁开〉。眼睛睁开要用“睁开”，“展开”不用于眼睛。"}, {"text": "他展开了鞋带。", "explanation": "这里应该用〈解开〉。松开的鞋带、绳结要用“解开”，“展开”指把卷起或折叠的东西铺平或伸直。"}, {"text": "他展开了馒头，分给大家。", "explanation": "这里应该用〈掰开〉。“展开”指把卷起或折叠的东西铺平或伸直，馒头要用手掰开，应说“掰开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在展开了双臂迎接朋友。", "corrected_sentence": "他正在展开双臂迎接朋友。", "error_description": "“正在”表示动作正在进行，与表示完成的“了”不能同用；应去掉“了”，说“正在展开双臂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把双手开展，抱住了我。", "corrected_sentence": "他把双手展开，抱住了我。", "error_description": "“开展”指进行、发展，不能用来表示伸开双手；此处应为“展开”，即“把双手展开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
