INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多个东西合在一起变成一个。", "primary_collocate": null, "pronunciation": "jí hé tǐ", "ipa": "tɕi˧˥ xɤ˧˥ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "这块大石头是很多小石头的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "云是很多小水珠的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具是几块木头的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一堆沙子是很多小沙粒的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班级是很多学生的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书是十个小故事的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一棵树是根、树干和叶子的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子是十几户人家的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片是很多小点的集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些小东西合在一起，成了一个集合体。", "target_word": "集合体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "集合體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多东西合在一起形成的一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4770717-0209-4e9c-bf03-9225dfd413b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集合体", "is_correct": true, "explanation": "正确答案：集合体。大石头由很多小石头组成，“很多小石头的集合体”符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性格特点，不能用来说明石头由哪些小石头组成。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄表示存在的时间长短，与“由很多小石头合成”的含义无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很多小石头的价格”搭配不通，价格不能表示由多个部分合成的整体。"}], "explanations": {"集合体": "正确答案：集合体。大石头由很多小石头组成，“很多小石头的集合体”符合句意。", "脾气": "语义：脾气是人的性格特点，不能用来说明石头由哪些小石头组成。", "年龄": "语义：年龄表示存在的时间长短，与“由很多小石头合成”的含义无关。", "价格": "搭配：“很多小石头的价格”搭配不通，价格不能表示由多个部分合成的整体。"}, "sentence_index": 0, "correct_answer": "集合体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每粒沙子都是独立的集合体，互不影响。", "explanation": "这里应该用〈个体〉。集合体指由多个事物合成的整体，单独一粒沙子是个体。"}, {"text": "一个原子是一个不能再分的集合体。", "explanation": "这里应该用〈单位〉。集合体由多个事物合成、可以再分；说不能再分的组成单位要用单位。"}, {"text": "体育课上，大家在操场上集合体。", "explanation": "这里应该用〈集合〉。“集合体”是名词，指由多个东西合成的整体；让大家聚到一起要用动词“集合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集合体", "is_correct": true, "explanation": "正确答案：集合体。树由根、树干和叶子组成，“根、树干和叶子的集合体”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不能说明树由哪些部分组成。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，与“由根、树干和叶子组成”的含义无关。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“是……的香味”不能表示由几个部分组合成的整体。"}], "explanations": {"集合体": "正确答案：集合体。树由根、树干和叶子组成，“根、树干和叶子的集合体”符合句意。", "颜色": "语义：颜色是事物的属性，不能说明树由哪些部分组成。", "名字": "语义：名字是称呼，与“由根、树干和叶子组成”的含义无关。", "香味": "搭配：“是……的香味”不能表示由几个部分组合成的整体。"}, "sentence_index": 6, "correct_answer": "集合体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玻璃是一个浑然一体的集合体。", "explanation": "这里应该用〈整体〉。集合体由可以分开的多个部分组成，“浑然一体”的整体要用整体。"}, {"text": "这把椅子是一整块木头雕成的集合体。", "explanation": "这里应该用〈实体〉。集合体由可以分开的多个部分组成；一整块雕成的物件要用“实体”。"}, {"text": "数学书上讲的是集合体的运算规则。", "explanation": "这里应该用〈集合〉。数学术语是“集合”，“集合体”不是数学概念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堆玩具是几十个小零件的一块集合体。", "corrected_sentence": "这堆玩具是几十个小零件的一个集合体。", "error_description": "“一块集合体”错，应为“一个集合体”。集合体不是块状物，量词用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子是几块木板拼成集合体。", "corrected_sentence": "这张桌子是几块木板拼成的集合体。", "error_description": "“拼成集合体”错，应为“拼成的集合体”。修饰语“拼成”与中心词“集合体”之间要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
