INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是非常明白地知道一件事的意思。", "primary_collocate": null, "pronunciation": "shēn kè lǐ jiě", "ipa": "ʂən⁵⁵ kʰɤ⁵¹ li²¹⁴ tɕjɛ²¹⁴", "syllable_count": 4, "sentences": [{"text": "我深刻理解你现在的心情。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望我们深刻理解这句话。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读完这本书，我深刻理解了爱的意思。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很难深刻理解这个故事。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有自己试过，才能深刻理解这件事。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈深刻理解孩子的难处。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要深刻理解老师的话。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这次旅行，我深刻理解了家的意思。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都深刻理解他为什么哭。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有深刻理解这个字的意思。", "target_word": "深刻理解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深刻理解了", "label": "体标"}, {"form": "深刻理解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "深刻理解：动词，非常透彻地明白一件事的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20be542-fd2b-4af9-92a3-e1943594c231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深刻理解", "is_correct": true, "explanation": "“深刻理解”指非常透彻地明白，符合“我___你现在的心情”的句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”针对食物或实物，不能用于心情。"}, {"text": "摘下", "is_correct": false, "explanation": "语义：“摘下”针对植物、果实等具体事物，不能用于心情。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能与“心情”搭配。"}], "explanations": {"深刻理解": "“深刻理解”指非常透彻地明白，符合“我___你现在的心情”的句意。", "吃掉": "语义：“吃掉”针对食物或实物，不能用于心情。", "摘下": "语义：“摘下”针对植物、果实等具体事物，不能用于心情。", "种植": "搭配：“种植”的对象是植物，不能与“心情”搭配。"}, "sentence_index": 0, "correct_answer": "深刻理解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他深刻理解了这张桌子。", "explanation": "这里应该用〈熟悉〉。深刻理解只用于意思、道理、心情等抽象内容，对物体的情况要说熟悉。"}, {"text": "他深刻理解了那辆自行车。", "explanation": "这里应该用〈了解〉。深刻理解只用于抽象内容，自行车的构造、用途等具体情况要说了解。"}, {"text": "他深刻理解了这扇窗户。", "explanation": "这里应该用〈看清〉。深刻理解指明白抽象的意思，窗户的样子要用看清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深刻理解", "is_correct": true, "explanation": "“深刻理解”指透彻地明白，符合“你要___老师的话”的句意。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”是身体动作，不能用于“话”。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”针对有形的物体，不能用于“话”。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是有形的物体，不能与“话”搭配。"}], "explanations": {"深刻理解": "“深刻理解”指透彻地明白，符合“你要___老师的话”的句意。", "拥抱": "语义：“拥抱”是身体动作，不能用于“话”。", "切开": "语义：“切开”针对有形的物体，不能用于“话”。", "搬运": "搭配：“搬运”的对象是有形的物体，不能与“话”搭配。"}, "sentence_index": 6, "correct_answer": "深刻理解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她深刻理解了那只茶杯。", "explanation": "这里应该用〈认得〉。深刻理解只用于抽象内容，茶杯的样子、外形要用认得。"}, {"text": "她深刻理解了这个书包。", "explanation": "这里应该用〈整理〉。深刻理解只用于抽象内容，书包里的东西要说整理。"}, {"text": "她深刻理解了那条河。", "explanation": "这里应该用〈勘察〉。深刻理解只用于抽象内容，河流的走向、水文要说勘察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我深刻理解的你的心情。", "corrected_sentence": "我深刻理解了你的心情。", "error_description": "“的”用错：完成标记应为“了”，动词“理解”后接“的”使句子不成立。正确写法是“深刻理解了你的心情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他深刻理解的很清楚。", "corrected_sentence": "他深刻理解得很清楚。", "error_description": "错误：“深刻理解的很清楚”，补语标记应为“得”而不是“的”。“得”引出程度补语，说明理解达到的程度。正确：“深刻理解得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
