INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然法则就是大自然里一直存在的规则，比如苹果会掉到地上。", "primary_collocate": null, "pronunciation": "zì rán fǎ zé", "ipa": "tsɿ˥˩ ʐan˧˥ fa˨˩˦ tsɤ˧˥", "syllable_count": 4, "sentences": [{"text": "苹果会掉到地上，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳每天从东边升起，是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天很冷，夏天很热，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼不能离开水，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教小朋友认识自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人人都要尊重自然法则。", "target_word": "自然法则", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "石头扔上去会掉下来，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里讲了很多有趣的自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水总是从高处流向低处，是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花开花落，都是自然法则。", "target_word": "自然法则", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "自然法則", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大自然里一直存在的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4770717-0209-4e9c-bf03-9225dfd413b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然法则", "is_correct": true, "explanation": "正确：“自然法则”指大自然里一直存在的规则，苹果落地正是这样的规则。"}, {"text": "习俗", "is_correct": false, "explanation": "语义：“习俗”是人们长期形成的生活习惯，不是苹果落地这样的客观规律。"}, {"text": "时尚", "is_correct": false, "explanation": "语义：“时尚”指一时流行的风气，与物体下落无关，填入后意思不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“这是……”后面接的应是规律或现象，“脾气”指人的性情，不能这样用。"}], "explanations": {"自然法则": "正确：“自然法则”指大自然里一直存在的规则，苹果落地正是这样的规则。", "习俗": "语义：“习俗”是人们长期形成的生活习惯，不是苹果落地这样的客观规律。", "时尚": "语义：“时尚”指一时流行的风气，与物体下落无关，填入后意思不通。", "脾气": "搭配：“这是……”后面接的应是规律或现象，“脾气”指人的性情，不能这样用。"}, "sentence_index": 0, "correct_answer": "自然法则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校有很多自然法则，大家都要遵守。", "explanation": "这里应该用〈规矩〉。“自然法则”指大自然的规律，学校的要求应说“规矩”。"}, {"text": "他从小就养成了早睡的自然法则。", "explanation": "这里应该用〈习惯〉。“养成”搭配“习惯”，自然法则是客观存在的规律，不能靠人养成。"}, {"text": "他按照一个自然法则写了一篇作文。", "explanation": "这里应该用〈提纲〉。“自然法则”指大自然的规律，写作文时的框架应说“提纲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然法则", "is_correct": true, "explanation": "正确：石头扔上去会掉下来，是大自然里一直存在的规则，“自然法则”符合句意。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”是人为设计的娱乐活动，石头下落是自然界的规律，二者不能等同。"}, {"text": "礼节", "is_correct": false, "explanation": "语义：“礼节”是人际交往中的规范，与石头下落这样的现象无关。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“节目”指表演或播出的内容，不能用“这是节目”来指称自然现象。"}], "explanations": {"自然法则": "正确：石头扔上去会掉下来，是大自然里一直存在的规则，“自然法则”符合句意。", "游戏": "语义：“游戏”是人为设计的娱乐活动，石头下落是自然界的规律，二者不能等同。", "礼节": "语义：“礼节”是人际交往中的规范，与石头下落这样的现象无关。", "节目": "搭配：“节目”指表演或播出的内容，不能用“这是节目”来指称自然现象。"}, "sentence_index": 6, "correct_answer": "自然法则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司有一套完善的自然法则。", "explanation": "这里应该用〈制度〉。“自然法则”指自然界的客观规律，公司的规定是人为制定的，应说“制度”。"}, {"text": "这种食品必须符合国家自然法则。", "explanation": "这里应该用〈标准〉。“符合标准”指符合人为规定的要求，“国家自然法则”不能用来指国家的规定。"}, {"text": "班里制定了一个自然法则。", "explanation": "这里应该用〈计划〉。“自然法则”是客观存在的，不能人为制定，“制定”应搭配“计划”或“规定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家总结出了一本自然法则。", "corrected_sentence": "科学家总结出了一条自然法则。", "error_description": "量词错误：“自然法则”应用量词“条”，应说“一条自然法则”。“本”用于书籍、册子，不能用来数“自然法则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们应该吃自然法则。", "corrected_sentence": "孩子们应该尊重自然法则。", "error_description": "动宾搭配错误：“吃”不能搭配“自然法则”，应改为“尊重”。只需替换这一个动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "正确：“动荡”指形势或经济不安定，与“平稳”构成反义，可用于“经济发展”。"}, {"text": "热烈", "is_correct": false, "explanation": "热烈形容气氛或情绪高涨，与“平稳”不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容明白、分明，与“平稳”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外貌或做事出色，与“平稳”不构成反义。"}], "correct_answer": "动荡", "explanations": {"动荡": "正确：“动荡”指形势或经济不安定，与“平稳”构成反义，可用于“经济发展”。", "热烈": "热烈形容气氛或情绪高涨，与“平稳”不构成反义。", "清楚": "清楚形容明白、分明，与“平稳”没有反义关系。", "漂亮": "漂亮形容外貌或做事出色，与“平稳”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情没有大的变化，安安定定的。", "primary_collocate": null, "pronunciation": "píng wěn", "ipa": "pʰiŋ˧˥ wən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的收入平稳，不用担心钱。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的利润一直平稳，没有大起大落。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷退休后，过着平稳安定的日子。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年经济发展平稳，大家都放心。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一份平稳的工作，不想总换。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇的生活平稳，很少发生大事。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩一直比较平稳，没有太大变化。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国关系平稳发展，对大家都有好处。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上学后，我们家的生活平稳多了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价这几个月比较平稳，没有涨也没有跌。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生活、工作、发展等没有大变化，安定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4770717-0209-4e9c-bf03-9225dfd413b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳”指收入没有大的波动，与“不用担心钱”相合。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“收入”可说稳定、丰厚，不说“收入清楚”。"}, {"text": "安静", "is_correct": false, "explanation": "语义：收入不会“安静”，“安静”形容环境或声音小，与句意无关。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”指距离很远，不能形容收入的状态。"}], "explanations": {"平稳": "正确：“平稳”指收入没有大的波动，与“不用担心钱”相合。", "清楚": "搭配：“收入”可说稳定、丰厚，不说“收入清楚”。", "安静": "语义：收入不会“安静”，“安静”形容环境或声音小，与句意无关。", "遥远": "语义：“遥远”指距离很远，不能形容收入的状态。"}, "sentence_index": 0, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条街很平稳，车来车往，吵得人睡不着。", "explanation": "这里应该用〈嘈杂〉。“平稳”说的是没有大的变化，街上声音大、人声杂应说“嘈杂”。"}, {"text": "这座山很平稳，爬起来很累。", "explanation": "这里应该用〈陡峭〉。“平稳”说的是没有大的变化，山的坡度大应说“陡峭”。"}, {"text": "最近大家都很平稳，没有时间休息。", "explanation": "这里应该用〈忙碌〉。“平稳”说的是没有大的变化，人们的劳累状态应说“忙碌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳”形容成绩没有大的起伏，与“没有太大变化”相合。"}, {"text": "辛苦", "is_correct": false, "explanation": "语义：“辛苦”形容劳累，不能用来形容成绩的状态。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能用来形容成绩。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”多形容声音，不能修饰“成绩”。"}], "explanations": {"平稳": "正确：“平稳”形容成绩没有大的起伏，与“没有太大变化”相合。", "辛苦": "语义：“辛苦”形容劳累，不能用来形容成绩的状态。", "柔软": "语义：“柔软”形容质地，不能用来形容成绩。", "嘹亮": "搭配：“嘹亮”多形容声音，不能修饰“成绩”。"}, "sentence_index": 6, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的商品很平稳，每个区都有很多选择。", "explanation": "这里应该用〈丰富〉。“平稳”说的是没有大的变化，商品种类多应说“丰富”。"}, {"text": "这次涨价很平稳，一下子涨了一倍。", "explanation": "这里应该用〈猛烈〉。“平稳”说的是没有大的变化；“一下子涨了一倍”应说“猛烈”。"}, {"text": "这家旅馆的房间很平稳，床单也很干净。", "explanation": "这里应该用〈整洁〉。“平稳”说的是没有大的变化，房间的整齐干净应说“整洁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，他的收入慢慢平稳出来了。", "corrected_sentence": "这几年，他的收入慢慢平稳下来了。", "error_description": "补语错误：表示变得平稳应用趋向补语「下来」，应说「慢慢平稳下来」，「平稳出来」不符合说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的生意一直的平稳。", "corrected_sentence": "这家店的生意一直很平稳。", "error_description": "结构助词错误：“平稳”作谓语时，前面用程度副词“很”，或直接说“一直平稳”；此处用结构助词“的”不通，应说「一直很平稳」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "缝翼是飞机机翼上可以活动的一块板子，用来帮助飞机飞得更稳。", "primary_collocate": null, "pronunciation": "fèng yì", "ipa": "fɤŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "缝翼是机翼上能活动的一块板子。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，缝翼会向前伸出。", "target_word": "缝翼", "complexity_tier": "T3", "furigana": "féng yì", "sentence_source": "generated"}, {"text": "缝翼可以帮助飞机飞得更稳。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看到了缝翼的照片。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼位于机翼的前缘。", "target_word": "缝翼", "complexity_tier": "T3", "furigana": "féng yì", "sentence_source": "generated"}, {"text": "飞机降落前，缝翼慢慢打开了。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着图上的缝翼问我们它有什么用。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架小飞机的缝翼是白色的。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼不能动，飞机就飞不稳。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸做了一个小飞机，还做了缝翼。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对缝翼", "label": "量词"}, {"form": "縫翼", "label": "繁体"}, {"form": "前缘缝翼", "label": "复合"}], "register": "中性", "sense_fingerprint": "机翼上可活动的板子，帮助飞机飞稳，通俗说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8803a-6dd5-492a-a974-71a190af6a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼（fèng yì）指机翼上能活动、帮助飞机飞稳的板子。"}, {"text": "风衣", "is_correct": false, "explanation": "两个音节声调都不同：fēng（第一声）与 fèng（第四声），yī（第一声）与 yì（第四声）。意思是风衣。"}, {"text": "缝衣", "is_correct": false, "explanation": "缝衣（féng yī）：缝制衣服。两个音节的声调都与 fèng yì 不同。"}, {"text": "缝隙", "is_correct": false, "explanation": "第二个音节声母不同：xì 与 yì。意思是缝隙。"}, {"text": "风力", "is_correct": false, "explanation": "第一个音节声调不同，第二个音节声母不同：lì 与 yì。意思是风的力量。"}, {"text": "风气", "is_correct": false, "explanation": "第一个音节声调不同，第二个音节声母不同：qì 与 yì。意思是风气。"}], "explanations": {"缝翼": "正确答案。缝翼（fèng yì）指机翼上能活动、帮助飞机飞稳的板子。", "风衣": "两个音节声调都不同：fēng（第一声）与 fèng（第四声），yī（第一声）与 yì（第四声）。意思是风衣。", "缝衣": "缝衣（féng yī）：缝制衣服。两个音节的声调都与 fèng yì 不同。", "缝隙": "第二个音节声母不同：xì 与 yì。意思是缝隙。", "风力": "第一个音节声调不同，第二个音节声母不同：lì 与 yì。意思是风的力量。", "风气": "第一个音节声调不同，第二个音节声母不同：qì 与 yì。意思是风气。"}, "sentence_index": null, "correct_answer": "缝翼"}, "level_3": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼是机翼上能活动的板子，与句中描述一致。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不装在机翼上，不是机翼上能活动的板子。"}, {"text": "螺丝钉", "is_correct": false, "explanation": "搭配：“螺丝钉”指小零件，不能说成“一块板子”。"}, {"text": "机舱", "is_correct": false, "explanation": "语义：机舱是载人的空间，不是能活动的板子。"}], "explanations": {"缝翼": "正确答案。缝翼是机翼上能活动的板子，与句中描述一致。", "窗帘": "语义：窗帘不装在机翼上，不是机翼上能活动的板子。", "螺丝钉": "搭配：“螺丝钉”指小零件，不能说成“一块板子”。", "机舱": "语义：机舱是载人的空间，不是能活动的板子。"}, "sentence_index": 0, "correct_answer": "缝翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "起飞时，缝翼会从机翼后缘放下来。", "explanation": "这里应该用〈襟翼〉。缝翼位于机翼前缘，襟翼才在后缘放下。"}, {"text": "飞机的翼尖装着缝翼，可以减少飞行阻力。", "explanation": "这里应该用〈翼梢小翼〉。翼梢小翼装在翼尖，减少阻力；缝翼位于机翼前缘，不装在翼尖。"}, {"text": "我用缝翼给衣服钉扣子。", "explanation": "缝翼是机翼上的可动板，不是针线用具，这句把它当成了缝纫工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼是图上可以指出来的实物，句子问的是它的用途。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情看不见，不能指着图上的某处。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音听得见却看不见，不能指着图上的某处。"}, {"text": "时光", "is_correct": false, "explanation": "搭配：“指着”指向看得见的东西，不能指“时光”。"}], "explanations": {"缝翼": "正确答案。缝翼是图上可以指出来的实物，句子问的是它的用途。", "心情": "语义：心情看不见，不能指着图上的某处。", "声音": "语义：声音听得见却看不见，不能指着图上的某处。", "时光": "搭配：“指着”指向看得见的东西，不能指“时光”。"}, "sentence_index": 6, "correct_answer": "缝翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机靠缝翼推动前进。", "explanation": "这里应该用〈螺旋桨〉。推动飞机前进的是螺旋桨，缝翼只是机翼上的可动板，不产生推力。"}, {"text": "小鸟靠缝翼飞行。", "explanation": "这里应该用〈翅膀〉。缝翼是飞机机翼上的部件，小鸟飞行靠的是翅膀。"}, {"text": "飞机向左倾斜时，靠缝翼来调整机身。", "explanation": "这里应该用〈副翼〉。副翼控制机身倾斜，缝翼只在起降时伸出、增加升力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机翼上装着两本缝翼。", "corrected_sentence": "机翼上装着两块缝翼。", "error_description": "量词错误：缝翼是板状部件，应用“块”；“本”只用于书籍、册子，不能用于机翼部件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "缝翼一直伸了着，飞机很稳。", "corrected_sentence": "缝翼一直伸着，飞机很稳。", "error_description": "体标错误：“着”表示持续，不能与“了”同时用在“伸”后，应删去“了”，说“伸着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
