INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24348, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表现就是做出来让别人看到的样子或事情。", "primary_collocate": null, "pronunciation": "biǎo xiàn", "ipa": "piɑʊ˨˩˦ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他想在老板面前好好表现。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用画表现心里的想法。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画表现了农民的喜悦。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想在比赛中表现一下自己。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕别人笑，不敢在大家面前表现。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影表现了朋友之间的爱。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在爷爷面前总是表现得很听话。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把心里的难过表现在脸上。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想在老师面前表现自己。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌表现了人们对家的想念。", "target_word": "表现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表现了", "label": "体标"}, {"form": "表现过", "label": "体标"}, {"form": "表現", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表现:动词:把想法、感情或本事做出来给别人看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：表现 biǎo xiàn，指把想法、感情或本事做出来给别人看。"}, {"text": "表面", "is_correct": false, "explanation": "表面 biǎomiàn 与 表现 biǎoxiàn 只有第二音节声母不同（m 与 x），意思是物体的外层。"}, {"text": "标线", "is_correct": false, "explanation": "标线 biāoxiàn 与 表现 biǎoxiàn 第一音节声调不同（第一声与第三声），意思是道路上的标记线。"}, {"text": "表象", "is_correct": false, "explanation": "表象 biǎoxiàng 与 表现 biǎoxiàn 只有第二音节韵母不同（ang 与 an），意思是事物表面的现象。"}], "explanations": {"表现": "正确：表现 biǎo xiàn，指把想法、感情或本事做出来给别人看。", "表面": "表面 biǎomiàn 与 表现 biǎoxiàn 只有第二音节声母不同（m 与 x），意思是物体的外层。", "标线": "标线 biāoxiàn 与 表现 biǎoxiàn 第一音节声调不同（第一声与第三声），意思是道路上的标记线。", "表象": "表象 biǎoxiàng 与 表现 biǎoxiàn 只有第二音节韵母不同（ang 与 an），意思是事物表面的现象。"}, "sentence_index": null, "correct_answer": "表现"}, "level_3": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：“想在老板面前好好表现”，指把自己的本事做出来给老板看，这里应填“表现”。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”不能用来把自己的本事展示给人看，与“在老板面前好好”的搭配不当。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭与“想在老板面前好好…”想给人留下好印象的意图相反，句意不通。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏是不让人看见，与“想在老板面前好好…”把自己展示出来的意图相反。"}], "explanations": {"表现": "正确：“想在老板面前好好表现”，指把自己的本事做出来给老板看，这里应填“表现”。", "睡觉": "搭配：“睡觉”不能用来把自己的本事展示给人看，与“在老板面前好好”的搭配不当。", "哭": "语义：哭与“想在老板面前好好…”想给人留下好印象的意图相反，句意不通。", "隐藏": "语义：隐藏是不让人看见，与“想在老板面前好好…”把自己展示出来的意图相反。"}, "sentence_index": 0, "correct_answer": "表现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "博物馆把古画表现在大厅里。", "explanation": "这里应该用〈展示〉。陈列物品要说“展示”，表现用于人把想法、感情或本事做出来给别人看，不用于陈列物品。"}, {"text": "老师向大家表现了新同学。", "explanation": "这里应该用〈介绍〉。把人引见给别人要说“介绍”，表现强调把自身的样子显示出来，不能用于引见他人。"}, {"text": "他把垃圾表现进了箱子里。", "explanation": "这里应该用〈扔〉。把东西丢进某处要说“扔”，表现不能表示投掷或放入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表现", "is_correct": true, "explanation": "正确：“他在爷爷面前总是表现得很听话”，表现指他在爷爷面前显示出的行为，这里应填“表现”。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“睡得很听话”说不通，“听话”是对行为的评价，不能用来形容睡觉。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭得很听话自相矛盾，“哭”与“听话”的意思相冲突。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑得很听话”不能用“听话”评价跑步这类动作，搭配不当。"}], "explanations": {"表现": "正确：“他在爷爷面前总是表现得很听话”，表现指他在爷爷面前显示出的行为，这里应填“表现”。", "睡": "搭配：“睡得很听话”说不通，“听话”是对行为的评价，不能用来形容睡觉。", "哭": "语义：哭得很听话自相矛盾，“哭”与“听话”的意思相冲突。", "跑": "搭配：“跑得很听话”不能用“听话”评价跑步这类动作，搭配不当。"}, "sentence_index": 6, "correct_answer": "表现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人们在广场上表现歌。", "explanation": "这里应该用〈唱〉。表示演唱要说“唱”，表现不能直接带“歌”作宾语。"}, {"text": "他每天表现碗。", "explanation": "这里应该用〈洗〉。表示做家务洗碗要说“洗”，表现不能与“碗”搭配。"}, {"text": "他用抹布表现了桌子。", "explanation": "这里应该用〈擦〉。擦拭桌面要说“擦”，表现不能表示擦拭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在台上都表现的很好。", "corrected_sentence": "孩子们在台上都表现得很好。", "error_description": "补语标记错误：“表现”后接描述状态的补语要用“得”，写成“的”是错误的。正确应为“表现得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把高兴的心情表现脸上。", "corrected_sentence": "她把高兴的心情表现在脸上。", "error_description": "介词缺失：表示某种表情或样子显露在某处，要说“表现在……上”，漏掉“在”是错误的。正确应为“表现在脸上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
