INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24350, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "飞机飞起来和落下来。", "primary_collocate": null, "pronunciation": "qǐ jiàng", "ipa": "t͡ɕʰi˨˩˦ t͡ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我家离机场很近，常听到飞机起降的声音。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一架小飞机正在跑道上起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在窗边，看飞机一架架起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，飞机起降要更加小心。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的灯光帮助飞机夜里起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的无人机能垂直起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机场很小，每天只有几次起降。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起降时，请把手机关机。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起降的飞机让机场的天空很热闹。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场工作，负责飞机起降的安全。", "target_word": "起降", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起降了", "label": "完成体"}], "register": "书面语", "sense_fingerprint": "飞机飞起来、落下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起降", "is_correct": true, "explanation": "正确：“飞机起降的声音”指飞机起飞和降落时发出的声音，与“常听到”相符。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：声音是用耳朵听的，不能说“观看的声音”，与“常听到”矛盾。"}, {"text": "检阅", "is_correct": false, "explanation": "语义：“检阅”指检查阅兵，与飞机发出的声音无关。"}, {"text": "挥手", "is_correct": false, "explanation": "搭配：飞机不会挥手，“飞机挥手的声音”不成立，与句意不符。"}], "explanations": {"起降": "正确：“飞机起降的声音”指飞机起飞和降落时发出的声音，与“常听到”相符。", "观看": "搭配：声音是用耳朵听的，不能说“观看的声音”，与“常听到”矛盾。", "检阅": "语义：“检阅”指检查阅兵，与飞机发出的声音无关。", "挥手": "搭配：飞机不会挥手，“飞机挥手的声音”不成立，与句意不符。"}, "sentence_index": 0, "correct_answer": "起降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的成绩起降很大。", "explanation": "这里误把“起降”当成〈波动〉的意思（成绩的高低波动）。“起降”专指飞机飞起来和落下来，不能用于成绩。"}, {"text": "气温起降很快，早晚差别大。", "explanation": "这里应该用〈升降〉。升降用于气温、水位等，起降专指飞机的起飞和降落。"}, {"text": "他把书包起降到了架子上。", "explanation": "这里误把“起降”当成〈搬运〉的意思（把书包搬上架子）。“起降”专指飞机飞起来和落下来，书包不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起降", "is_correct": true, "explanation": "正确：“每天只有几次起降”指机场每天飞机起飞和降落的次数少，与句意相符。"}, {"text": "扩建", "is_correct": false, "explanation": "语义：“扩建”是一项工程，不按“每天几次”计算，与句意矛盾。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”不用“每天几次”来计数，用于机场搭配不当。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：机场的运行不是争吵，“每天只有几次争吵”与句意无关。"}], "explanations": {"起降": "正确：“每天只有几次起降”指机场每天飞机起飞和降落的次数少，与句意相符。", "扩建": "语义：“扩建”是一项工程，不按“每天几次”计算，与句意矛盾。", "装修": "搭配：“装修”不用“每天几次”来计数，用于机场搭配不当。", "争吵": "语义：机场的运行不是争吵，“每天只有几次争吵”与句意无关。"}, "sentence_index": 6, "correct_answer": "起降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心情在这一天里起降了很多次。", "explanation": "“起降”只指飞机的起飞和降落，心情的起伏不能用“起降”。"}, {"text": "他负责股价的起降，每天都很忙。", "explanation": "这里误把“起降”当成〈涨跌〉的意思（股价的上下波动）。“起降”只指飞机飞起来和落下来，股价不能这样用。"}, {"text": "他在机场工作，负责把行李起降到飞机上。", "explanation": "这里误把“起降”当成〈装卸〉的意思（把行李搬上飞机）。“起降”只指飞机飞起来和落下来，行李不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里，这架飞机平稳地起降地。", "corrected_sentence": "夜里，这架飞机平稳地起降。", "error_description": "结构错误：句末多加了“地”。“平稳地”作状语修饰“起降”是对的，但“起降”已是谓语，句末的“地”没有可依附的成分，应删去，说“平稳地起降”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这架飞机把跑道上起降。", "corrected_sentence": "这架飞机在跑道上起降。", "error_description": "把字句错误：“起降”是不及物动词，不能用“把”引出处所“跑道上”，应用“在”引出，说“在跑道上起降”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24352, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "反义：「马虎」即不认真细致，正与「严谨」相反。"}, {"text": "清澈", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容水或天空干净透明。"}, {"text": "温柔", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容性情或动作柔和。"}, {"text": "宽阔", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容面积大。"}], "correct_answer": "马虎", "explanations": {"马虎": "反义：「马虎」即不认真细致，正与「严谨」相反。", "清澈": "与「严谨」没有反义关系，形容水或天空干净透明。", "温柔": "与「严谨」没有反义关系，形容性情或动作柔和。", "宽阔": "与「严谨」没有反义关系，形容面积大。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24352, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "草率", "is_correct": true, "explanation": "反义：「草率」指做事随便、不周密，与「严谨」相反。"}, {"text": "陡峭", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容坡度大。"}, {"text": "柔软", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容质地不硬。"}, {"text": "明亮", "is_correct": false, "explanation": "与「严谨」没有反义关系，形容光线强或颜色鲜亮。"}], "correct_answer": "草率", "explanations": {"草率": "反义：「草率」指做事随便、不周密，与「严谨」相反。", "陡峭": "与「严谨」没有反义关系，形容坡度大。", "柔软": "与「严谨」没有反义关系，形容质地不硬。", "明亮": "与「严谨」没有反义关系，形容光线强或颜色鲜亮。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24352, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情很认真，不马虎。", "primary_collocate": null, "pronunciation": "yán jǐn", "ipa": "jɛn˧˥ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "他做事很严谨，从来不马虎。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会计工作要很严谨，不能算错钱。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批改作业非常严谨。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写报告的时候特别严谨。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂检查产品很严谨。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做实验要严谨，每一步都要记下来。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个严谨的人，答应了就一定做到。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的同事工作严谨，大家都信任他。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写代码必须严谨，一个符号错了就会出问题。", "target_word": "严谨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师做菜很严谨，盐放多少都要称一称。", "target_word": "严谨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事认真仔细，不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4770717-0209-4e9c-bf03-9225dfd413b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严谨", "is_correct": true, "explanation": "严谨：形容做事认真周密，与「从来不马虎」的语境相符。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：懒散指松懈、不认真，与「从来不马虎」矛盾。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：粗心指疏忽、不细致，与「从来不马虎」矛盾。"}, {"text": "潦草", "is_correct": false, "explanation": "语义：“潦草”指字迹随便，也可指做事草率，与“从来不马虎”矛盾。"}], "explanations": {"严谨": "严谨：形容做事认真周密，与「从来不马虎」的语境相符。", "懒散": "语义：懒散指松懈、不认真，与「从来不马虎」矛盾。", "粗心": "语义：粗心指疏忽、不细致，与「从来不马虎」矛盾。", "潦草": "语义：“潦草”指字迹随便，也可指做事草率，与“从来不马虎”矛盾。"}, "sentence_index": 0, "correct_answer": "严谨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会场里的气氛很严谨，没人敢说话。", "explanation": "这里应该用〈严肃〉。严肃形容气氛、神情的庄重；严谨形容做事周密，不用于描述会场的气氛。"}, {"text": "他看学生的眼神很严谨。", "explanation": "这里应该用〈严厉〉。严厉形容目光、言语的苛刻；严谨形容做事认真周密，不用于描述眼神。"}, {"text": "他面对歹徒很严谨，一点也不害怕。", "explanation": "这里应该用〈勇敢〉。勇敢形容不怕危险的品质；严谨形容做事周密，不用于描述面对危险时的胆量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严谨", "is_correct": true, "explanation": "严谨：形容为人做事周密认真，与「答应了就一定做到」相符。"}, {"text": "健忘", "is_correct": false, "explanation": "语义：健忘指记性差，与「答应了就一定做到」矛盾。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”即不认真、不细致，与“严谨”相反，不能形容周密认真的人。"}, {"text": "散漫", "is_correct": false, "explanation": "语义：散漫指纪律松懈，与「一定做到」矛盾。"}], "explanations": {"严谨": "严谨：形容为人做事周密认真，与「答应了就一定做到」相符。", "健忘": "语义：健忘指记性差，与「答应了就一定做到」矛盾。", "马虎": "语义：“马虎”即不认真、不细致，与“严谨”相反，不能形容周密认真的人。", "散漫": "语义：散漫指纪律松懈，与「一定做到」矛盾。"}, "sentence_index": 6, "correct_answer": "严谨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他送的礼物很严谨。", "explanation": "这里应该用〈大方〉。大方形容不吝啬、出手爽快；严谨形容做事周密，不用于礼物或出手。"}, {"text": "那只小狗很严谨。", "explanation": "这里应该用〈活泼〉。活泼形容性格开朗好动；严谨形容做事周密，不描述动物的性情。"}, {"text": "她的笑容很严谨。", "explanation": "这里应该用〈甜美〉。甜美形容外貌、笑容的好看；严谨不用于形容面部表情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他整理文件地严谨，从不漏页。", "corrected_sentence": "他整理文件很严谨，从不漏页。", "error_description": "程度副词错误：「严谨」作谓语，修饰语应用「很」，「地」只用于动词前作状语，不能用在形容词谓语前，应说「整理文件很严谨」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位会计是个严谨地人，账目从没出过错。", "corrected_sentence": "这位会计是个严谨的人，账目从没出过错。", "error_description": "「严谨地人」应为「严谨的人」：「严谨」修饰名词「人」作定语，要用「的」，「地」只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6322e70-6f58-4111-8c4e-5d0440cb0b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
