INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24354, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某样东西变得非常明显，大家一眼就能看出来。", "primary_collocate": null, "pronunciation": "zhāng xiǎn", "ipa": "ʈ͡ʂɑŋ˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "黑色的西装彰显他的成熟。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法彰显了学校对学生的重视。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用鲜艳的口红彰显自己的个性。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大红的灯笼彰显节日的气氛。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场救援彰显了人与人之间的温暖。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开的新车彰显了他的身份。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金色的大门彰显了酒店的豪华。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想用这个广告彰显产品的特点。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高高的塔楼彰显着这座城的气派。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一件小事就能彰显一个人的修养。", "target_word": "彰显", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彰显了", "label": "完成体"}, {"form": "彰显着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "使某样东西变得很明显，一眼就能看出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彰显", "is_correct": true, "explanation": "正确：“彰显”表示让成熟明显地被一眼看出，与“黑色的西装”的语境相合。"}, {"text": "消磨", "is_correct": false, "explanation": "语义：“消磨”指逐渐耗尽，与西装能让成熟显现的语义不符。"}, {"text": "掩饰", "is_correct": false, "explanation": "搭配：“掩饰”多接情绪、错误、缺点，不说掩饰成熟。"}, {"text": "损害", "is_correct": false, "explanation": "语义：“损害”指伤害，西装不会损害成熟，与句意不合。"}], "explanations": {"彰显": "正确：“彰显”表示让成熟明显地被一眼看出，与“黑色的西装”的语境相合。", "消磨": "语义：“消磨”指逐渐耗尽，与西装能让成熟显现的语义不符。", "掩饰": "搭配：“掩饰”多接情绪、错误、缺点，不说掩饰成熟。", "损害": "语义：“损害”指伤害，西装不会损害成熟，与句意不合。"}, "sentence_index": 0, "correct_answer": "彰显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厚雾彰显了街道上的路标。", "explanation": "这里应该用〈掩盖〉。彰显表示让事物明显地呈现，雾遮住路标要用掩盖，两者意思相反。"}, {"text": "她把伤疤彰显在长袖下面。", "explanation": "这里应该用〈隐藏〉。彰显是让事物明显地被看见，伤疤藏在衣服下要用隐藏。"}, {"text": "他把钥匙彰显在口袋最深处，谁也找不到。", "explanation": "这里应该用〈隐没〉。彰显是让事物明显地呈现，钥匙藏在口袋最深处、谁也找不到，恰恰相反，应该用隐没。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彰显", "is_correct": true, "explanation": "正确：“彰显”表示使豪华的气派明显地呈现，与“金色的大门”的语境相合。"}, {"text": "流出", "is_correct": false, "explanation": "语义：“流出”指液体或物质从里往外流，与抽象的豪华气派不合。"}, {"text": "冒出", "is_correct": false, "explanation": "语义：“冒出”指突然出现，多用于烟、汗、念头，不宜描写大门的气派。"}, {"text": "推出", "is_correct": false, "explanation": "搭配：“推出”多接产品、服务、节目，不说“推出酒店的豪华”。"}], "explanations": {"彰显": "正确：“彰显”表示使豪华的气派明显地呈现，与“金色的大门”的语境相合。", "流出": "语义：“流出”指液体或物质从里往外流，与抽象的豪华气派不合。", "冒出": "语义：“冒出”指突然出现，多用于烟、汗、念头，不宜描写大门的气派。", "推出": "搭配：“推出”多接产品、服务、节目，不说“推出酒店的豪华”。"}, "sentence_index": 6, "correct_answer": "彰显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把内心的慌张彰显得严严实实，谁也看不出来。", "explanation": "这里应该用〈掩饰〉。彰显是让事物明显地呈现，“严严实实，谁也看不出来”恰恰相反，应该用掩饰。"}, {"text": "他彰显了自己的病情，没有告诉任何人。", "explanation": "这里应该用〈隐瞒〉。隐瞒指不让别人知道，彰显则是使事物明显，二者相反。"}, {"text": "乌云彰显了星星的踪影，把夜空遮得严严实实。", "explanation": "这里应该用〈遮蔽〉。彰显是让事物明显地呈现，乌云把夜空遮得严严实实，恰恰相反，应该用遮蔽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套深蓝色的西装很彰显了他的稳重。", "corrected_sentence": "这套深蓝色的西装彰显了他的稳重。", "error_description": "错误：副词“很”不能修饰动词“彰显”，应删去，写作“彰显了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动彰显了了品牌的特色。", "corrected_sentence": "这次活动彰显了品牌的特色。", "error_description": "错误：“了”重复。“彰显了”中只需一个“了”，应删去多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24356, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "平庸指没有突出之处，与“比很多人都好”的卓越意思相反。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥指缺少水分，与卓越没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地松软、不硬，与卓越没有反义关系。"}, {"text": "厚重", "is_correct": false, "explanation": "厚重形容分量大、有厚度，与卓越没有反义关系。"}], "correct_answer": "平庸", "explanations": {"平庸": "平庸指没有突出之处，与“比很多人都好”的卓越意思相反。", "干燥": "干燥指缺少水分，与卓越没有反义关系。", "柔软": "柔软形容质地松软、不硬，与卓越没有反义关系。", "厚重": "厚重形容分量大、有厚度，与卓越没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
