INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可控性是说一件事能不能被我们管住或控制住。", "primary_collocate": null, "pronunciation": "kě kòng xìng", "ipa": "kʰɤ˨˩ kʰʊŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这件事的可控性不高，我们只能慢慢看。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前先想想，哪些问题的可控性比较大。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气的可控性很小，所以我们要带伞。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的情绪有时候可控性不强，家长要耐心。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的可控性很好，新手也能开。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划时，要先看事情的可控性。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情的可控性越大，我们越不用担心。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该多做可控性高的事。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水灾的可控性很低，大家要提前准备。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习时间的可控性很重要。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "一件事能不能被我们管住、控制住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可控性", "is_correct": true, "explanation": "正确：“可控性”指事情能否被管住，与“这件事的……不高，我们只能慢慢看”的语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“高”用于程度、水平，颜色不说“不高”，应说颜色深浅。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”用大小描述，不说“体积不高”。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”指光的明暗，不能用来形容事情，“这件事的亮度不高”不成立。"}], "explanations": {"可控性": "正确：“可控性”指事情能否被管住，与“这件事的……不高，我们只能慢慢看”的语境相合。", "颜色": "搭配：“高”用于程度、水平，颜色不说“不高”，应说颜色深浅。", "体积": "搭配：“体积”用大小描述，不说“体积不高”。", "亮度": "搭配：“亮度”指光的明暗，不能用来形容事情，“这件事的亮度不高”不成立。"}, "sentence_index": 0, "correct_answer": "可控性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气的可控性很高，我们可以提前安排出行。", "explanation": "这里应该用〈可预测性〉。可控性指能否被人管住，天气管不住，提前安排依靠的是可预测性。"}, {"text": "这道菜的可控性很高，大家都说好吃。", "explanation": "这里应该用〈味道〉。可控性指能否被管住，说菜好吃要用味道，不能用可控性。"}, {"text": "这个消息的可控性很高，大家都很相信。", "explanation": "这里应该用〈可信度〉。可控性说的是能否被管住，消息值不值得相信要用可信度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可控性", "is_correct": true, "explanation": "正确：“事情的可控性越大，我们越不用担心”，“可控性”指事情能否被管住，语境相合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度越大往往令人更担心，与“越不用担心”的语义相反。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音越大越让人烦躁，与“越不用担心”的语义相反。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”形容空间大小，不修饰“事情”。"}], "explanations": {"可控性": "正确：“事情的可控性越大，我们越不用担心”，“可控性”指事情能否被管住，语境相合。", "温度": "语义：温度越大往往令人更担心，与“越不用担心”的语义相反。", "噪音": "语义：噪音越大越让人烦躁，与“越不用担心”的语义相反。", "面积": "搭配：“面积”形容空间大小，不修饰“事情”。"}, "sentence_index": 6, "correct_answer": "可控性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张沙发的可控性很高，坐一整天也不累。", "explanation": "这里应该用〈舒适度〉。可控性指能否被控制，坐着不累说的是舒适度。"}, {"text": "这段文字的可控性很高，每个字都看得清。", "explanation": "这里应该用〈清晰度〉。可控性不说明文字是否清楚，看得清要用清晰度。"}, {"text": "这座桥的可控性很高，大家都放心过。", "explanation": "这里应该用〈安全性〉。可控性指能否被管住，让人放心通过说的是安全性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次装修地可控性不高，我们只能等。", "corrected_sentence": "这次装修的可控性不高，我们只能等。", "error_description": "错误：“地”是状语标记，不能用来修饰名词“可控性”。修饰名词应用定语标记“的”，应说“这次装修的可控性不高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的很可控性越大，大家越放心。", "corrected_sentence": "这次活动的可控性越大，大家越放心。", "error_description": "错误：副词“很”修饰名词“可控性”，这样用不成立。“的”后应直接接“可控性”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
