INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上升起来的高高的部分，比如石头山或土山。", "primary_collocate": null, "pronunciation": "shān", "ipa": "ʂan˥", "syllable_count": 1, "sentences": [{"text": "这座山上没有树，只有很多大石头。", "target_word": "山", "complexity_tier": "T3", "furigana": "zhè zuò shān shàng méi yǒu shù, zhǐ yǒu hěn duō dà shítou.", "sentence_source": "generated"}, {"text": "村子旁边那座山上长满了草。", "target_word": "山", "complexity_tier": "T3", "furigana": "cūn zi páng biān nà zuò shān shàng zhǎng mǎn le cǎo.", "sentence_source": "generated"}, {"text": "山很陡，路也不好走。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在山下看风景。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山上有一座小庙。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山不高，半天就能爬到上面。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把车停在山前。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山那边是另一个村子。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候每天看着这座山。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，山更绿了。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "山路", "label": "复合"}], "register": "中性", "sense_fingerprint": "地面隆起的高处，如石头山、土山", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8123548a-3e19-4ed4-b9a2-7a790a83fd3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。shān（第一声），指地面隆起的高处，如石头山、土山。"}, {"text": "三", "is_correct": false, "explanation": "sān（第一声）与 shān（第一声）声母不同（s 与 sh），意思是“三”。"}, {"text": "伤", "is_correct": false, "explanation": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“伤”。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn（第三声）与 shān（第一声）声调不同，意思是“闪”。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“身体”。"}], "explanations": {"山": "正确。shān（第一声），指地面隆起的高处，如石头山、土山。", "三": "sān（第一声）与 shān（第一声）声母不同（s 与 sh），意思是“三”。", "伤": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“伤”。", "闪": "shǎn（第三声）与 shān（第一声）声调不同，意思是“闪”。", "身": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“身体”。"}, "sentence_index": null, "correct_answer": "山"}, "level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。“这座……上没有树”指的是地面隆起的高处，与“大石头”相符。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼是人造建筑，与“没有树、只有大石头”描写的自然地貌不符。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“上”多用于地表或山坡，“这座房子上”不能表示这一处所。"}, {"text": "宫殿", "is_correct": false, "explanation": "语义：宫殿是人造建筑，不是地面隆起的部分，与“大石头”的自然景象不符。"}], "explanations": {"山": "正确。“这座……上没有树”指的是地面隆起的高处，与“大石头”相符。", "大楼": "语义：大楼是人造建筑，与“没有树、只有大石头”描写的自然地貌不符。", "房子": "搭配：“上”多用于地表或山坡，“这座房子上”不能表示这一处所。", "宫殿": "语义：宫殿是人造建筑，不是地面隆起的部分，与“大石头”的自然景象不符。"}, "sentence_index": 0, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们把那座山种在院子里。", "explanation": "这里不能说“种”。“种”的对象应是植物，山是地形，不能被种。"}, {"text": "孩子们把那座山喝了下去。", "explanation": "这里不能说“喝”。“喝”的对象应是液体，山不能被喝下去。"}, {"text": "孩子们站在一只山下看风景。", "explanation": "这里应该用〈座〉。山的量词是“座”，“只”多用于动物，不能用于山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。shān（第一声），指地面隆起的高处。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 shān（第一声）声母不同（x 与 sh），意思是“先”。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“深”。"}, {"text": "扇", "is_correct": false, "explanation": "shàn（第四声）与 shān（第一声）声调不同，意思是“扇子”。"}], "explanations": {"山": "正确。shān（第一声），指地面隆起的高处。", "善": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。", "先": "xiān（第一声）与 shān（第一声）声母不同（x 与 sh），意思是“先”。", "深": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“深”。", "扇": "shàn（第四声）与 shān（第一声）声调不同，意思是“扇子”。"}, "sentence_index": null, "correct_answer": "山"}, "level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。“停在……前”指的是地面上的一处地点，山前可以停车。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是纸上的图，不是可以停车的地面处所，“停在地图前”不成立。"}, {"text": "云", "is_correct": false, "explanation": "语义：云在空中，不是可以停车的地面处所，与句子的语境不符。"}, {"text": "海", "is_correct": false, "explanation": "语义：海是广阔的水域，车不能停在海的前面。"}], "explanations": {"山": "正确。“停在……前”指的是地面上的一处地点，山前可以停车。", "地图": "语义：地图是纸上的图，不是可以停车的地面处所，“停在地图前”不成立。", "云": "语义：云在空中，不是可以停车的地面处所，与句子的语境不符。", "海": "语义：海是广阔的水域，车不能停在海的前面。"}, "sentence_index": 6, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那座山放进了书包。", "explanation": "这里不能说“放进书包”。山体积太大，不能装进书包，它不是可以随身携带的小东西。"}, {"text": "他用那座山写字。", "explanation": "这里不能说“用……写字”。山不是书写工具，“用”后应接笔、纸等工具。"}, {"text": "她煮了那座山，给大家吃。", "explanation": "这里不能说“煮”。“煮”的对象应是食物，山不能被煮，也不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们爬上了那只山。", "corrected_sentence": "孩子们爬上了那座山。", "error_description": "量词错误：“山”的量词应用“座”，不用“只”。“只”多用于小动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天去看了一只山。", "corrected_sentence": "我们昨天去看了一座山。", "error_description": "量词错误：“山”的量词应用“座”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
