INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪不大的大人。", "primary_collocate": null, "pronunciation": "nián qīng rén", "ipa": "njɛn˧˥ tɕʰiŋ˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "年轻人喜欢在网上买东西。", "target_word": "年轻人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有很多年轻人在跑步。", "target_word": "年轻人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个年轻人每天早上六点起床。", "target_word": "年轻人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在的年轻人大多会用手机付钱。", "target_word": "年轻人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人请那个年轻人帮忙拿东西。", "target_word": "年轻人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人应该多学习，多看世界。", "target_word": "年轻人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个年轻人正在路边等公交车。", "target_word": "年轻人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的年轻人都很努力。", "target_word": "年轻人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的客人大部分是年轻人。", "target_word": "年轻人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然是年轻人，但是工作很认真。", "target_word": "年轻人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个年轻人", "label": "量词"}, {"form": "一位年轻人", "label": "量词"}], "register": "中性", "sense_fingerprint": "年轻人：年纪不大的成年人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675cfc97-fbfc-4651-bf94-1c49f7b53f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有喜好，也不会上网买东西，不能作“喜欢”的主语。"}, {"text": "年轻人", "is_correct": true, "explanation": "年轻人指年纪不大的大人，能够“喜欢在网上买东西”，与句意相合。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不会上网购物，与“在网上买东西”的描述不合。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会上网购物，不能作“喜欢在网上买东西”的主语。"}], "explanations": {"石头": "语义：石头没有喜好，也不会上网买东西，不能作“喜欢”的主语。", "年轻人": "年轻人指年纪不大的大人，能够“喜欢在网上买东西”，与句意相合。", "植物": "语义：植物不会上网购物，与“在网上买东西”的描述不合。", "小狗": "语义：小狗不会上网购物，不能作“喜欢在网上买东西”的主语。"}, "sentence_index": 0, "correct_answer": "年轻人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个年轻人七岁，还在上小学。", "explanation": "这里应该用〈孩子〉。年轻人指年纪不大的大人，七岁的小学生不属于这一义，应说〈孩子〉。"}, {"text": "我奶奶今年八十岁，是个年轻人。", "explanation": "这里应该用〈老人〉。年轻人指年纪不大的大人，八十岁的奶奶应说〈老人〉。"}, {"text": "我爸爸是年轻人，已经五十岁了。", "explanation": "这里应该用〈中年人〉。年轻人指年纪不大的大人，五十岁的人不能说成年轻人，应说〈中年人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机不会等车，与“正在路边等公交车”的主语不合。"}, {"text": "年轻人", "is_correct": true, "explanation": "年轻人是能够在路边等车的人，与“一个……正在路边等公交车”相合。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果不会等车，与“正在路边等公交车”的主语不合。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵飘在天上，不能在路边等公交车。"}], "explanations": {"手机": "语义：手机不会等车，与“正在路边等公交车”的主语不合。", "年轻人": "年轻人是能够在路边等车的人，与“一个……正在路边等公交车”相合。", "苹果": "语义：苹果不会等车，与“正在路边等公交车”的主语不合。", "云朵": "语义：云朵飘在天上，不能在路边等公交车。"}, "sentence_index": 6, "correct_answer": "年轻人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的年轻人时代是在农村度过的。", "explanation": "这里应该用〈青年时代〉。〈年轻人〉作名词，不能直接修饰“时代”，回忆人生阶段要说〈青年时代〉。"}, {"text": "这座城市是个年轻人。", "explanation": "这里应该用〈年轻〉作形容词，说〈这座城市很年轻〉。年轻人指人，不能用来指城市。"}, {"text": "这只小猫是个年轻人，每天陪我玩。", "explanation": "年轻人指年纪不大的成年人，不能用来指小猫这样的动物。这里应换成〈小动物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只年轻人昨天去图书馆借了一本书。", "corrected_sentence": "那个年轻人昨天去图书馆借了一本书。", "error_description": "错误在目标词的量词：「只」用于动物或成对器物中的一件，不能用来数人。应改为「那个年轻人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个年轻人们在广场上唱歌。", "corrected_sentence": "一个年轻人在广场上唱歌。", "error_description": "「一个」表示单数，后面不能再加复数词尾「们」，应说「一个年轻人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
