INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书就是用来读的，有很多页。", "primary_collocate": null, "pronunciation": "shū běn", "ipa": "ʂu pən", "syllable_count": 2, "sentences": [{"text": "书本很厚，有三百多页。", "target_word": "书本", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书本是用来读的，不是用来放着的。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书本的第一页画着一只小猫。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢翻开书本，闻那股纸张的味道。", "target_word": "书本", "complexity_tier": "T3", "furigana": "shū běn", "sentence_source": "generated"}, {"text": "弟弟把书本翻到了第十页。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书本掉在地上，页都弄皱了。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上的书本旁边放着一支笔。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开书本，一页一页地看。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些书本太旧了，有的书页都掉了。", "target_word": "书本", "complexity_tier": "T3", "furigana": "shū běn", "sentence_source": "generated"}, {"text": "请大家拿出书本，看第五页。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "書本", "label": "繁体"}, {"form": "书本知识", "label": "复合"}], "register": "口语", "sense_fingerprint": "用来阅读、有很多页的具体的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15493912-f1ff-4f6e-a884-3ffcb8e6a4f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书本", "is_correct": true, "explanation": "正确：“书本”指有很多页的书，与“很厚，有三百多页”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有页，“石头很厚，有三百多页”不成立。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服没有页，“衣服很厚，有三百多页”不成立。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机没有页码，“手机有三百多页”不符合常识。"}], "explanations": {"书本": "正确：“书本”指有很多页的书，与“很厚，有三百多页”相符。", "石头": "语义：石头没有页，“石头很厚，有三百多页”不成立。", "衣服": "语义：衣服没有页，“衣服很厚，有三百多页”不成立。", "手机": "语义：手机没有页码，“手机有三百多页”不符合常识。"}, "sentence_index": 0, "correct_answer": "书本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一张书本。", "explanation": "这里不能用〈张〉。〈张〉用于纸、桌子等平面的东西，书本应该用〈本〉或〈套〉。"}, {"text": "这个书本的门打不开，里面放着衣服。", "explanation": "这里说的是衣柜，应该用〈衣柜〉。〈门〉是衣柜、书柜这类家具的部件，书本没有门。"}, {"text": "书桌上放着一台书本。", "explanation": "这里不能用〈台〉。〈台〉用于机器等，书本应该用〈本〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书本", "is_correct": true, "explanation": "正确：“书本”指可以放在桌上的书，与“桌上……旁边放着一支笔”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会放在桌上，“桌上的太阳”不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能放在桌上，与“桌上的”搭配不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“桌上”不能与天空搭配，“桌上的天空”说不通。"}], "explanations": {"书本": "正确：“书本”指可以放在桌上的书，与“桌上……旁边放着一支笔”相符。", "太阳": "语义：太阳不会放在桌上，“桌上的太阳”不成立。", "空气": "语义：空气不能放在桌上，与“桌上的”搭配不通。", "天空": "搭配：“桌上”不能与天空搭配，“桌上的天空”说不通。"}, "sentence_index": 6, "correct_answer": "书本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了一副书本。", "explanation": "这里不能用〈副〉。〈副〉用于眼镜、手套等成对的东西，书本应该用〈本〉或〈套〉。"}, {"text": "她每天都在书本上写日记。", "explanation": "这里应该用〈日记本〉。“书本”指印好、供阅读的书，写日记要用日记本。"}, {"text": "他的桌上摆着一颗书本。", "explanation": "这里不能用〈颗〉。〈颗〉用于粒状、圆形的小东西，书本应该用〈本〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟已经把书本看了完。", "corrected_sentence": "弟弟已经把书本看完了。", "error_description": "补语位置错误：结果补语“完”应紧跟动词，说“看完了”，不能说“看了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些书本们都太旧了，该换了。", "corrected_sentence": "这些书本都太旧了，该换了。", "error_description": "“们”只加在指人的名词后，不能加在“书本”这类无生命的事物后表示复数，应去掉“们”，说“这些书本都太旧了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体随着音乐动来动去。", "primary_collocate": null, "pronunciation": "tiào wǔ", "ipa": "tʰiɑʊ̯⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "音乐一响，宝宝就跟着跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗听见音乐，开心地跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听着音乐，高兴得跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着桌子跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边唱歌一边跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客厅里放着音乐，我们一起跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不会跳舞，只会站着听。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园的小朋友在教室里跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好听的歌，她忍不住跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在家里开着音乐跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跳了舞", "label": "体标"}, {"form": "跳着舞", "label": "体标"}, {"form": "跳过舞", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：听着音乐，身体跟着动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7846ece-b54f-4e87-9fd6-ee570f2cbede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "正确：“跳舞”指身体随音乐动，与“音乐一响”和“跟着”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：音乐一响，人不会跟着睡觉，“跟着”要求随音乐做动作。"}, {"text": "静坐", "is_correct": false, "explanation": "语义：静坐是安静不动，与“跟着”随音乐而动的意思相反。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“跟着”要求随音乐做动作，音乐一响，宝宝不会跟着哭。"}], "explanations": {"跳舞": "正确：“跳舞”指身体随音乐动，与“音乐一响”和“跟着”相符。", "睡觉": "语义：音乐一响，人不会跟着睡觉，“跟着”要求随音乐做动作。", "静坐": "语义：静坐是安静不动，与“跟着”随音乐而动的意思相反。", "哭": "语义：“跟着”要求随音乐做动作，音乐一响，宝宝不会跟着哭。"}, "sentence_index": 0, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气跳舞了三十下。", "explanation": "这里应该用〈跳绳〉。跳绳按次数计，说“跳了三十下”；“跳舞”只指身体随音乐动，不按下数计。"}, {"text": "小明在沙坑里跳舞，跳了六米。", "explanation": "这里应该用〈跳远〉。跳远是按距离计成绩的比赛项目；跳舞没有距离，不能说跳了几米。"}, {"text": "他的心跳舞得很快。", "explanation": "这里应该用〈跳动〉。心脏的起伏说“跳动”，“跳舞”只指随音乐动，不能形容心脏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "正确：“不会跳舞，只会站着听”中，“跳舞”与“站着听”形成对比。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“不会洗澡”与常识不符，句子说的是跳舞这项技能。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“不会吃饭”与常识不符，句子说的是跳舞这项技能。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“不会睡觉”与常识不符，句子说的是跳舞这项技能。"}], "explanations": {"跳舞": "正确：“不会跳舞，只会站着听”中，“跳舞”与“站着听”形成对比。", "洗澡": "语义：“不会洗澡”与常识不符，句子说的是跳舞这项技能。", "吃饭": "语义：“不会吃饭”与常识不符，句子说的是跳舞这项技能。", "睡觉": "语义：“不会睡觉”与常识不符，句子说的是跳舞这项技能。"}, "sentence_index": 6, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他第一次从飞机上跳舞，很害怕。", "explanation": "这里应该用〈跳伞〉。跳伞是从飞机上跳下；“跳舞”只指随音乐动。"}, {"text": "她从跳台上跳舞，动作很漂亮。", "explanation": "这里应该用〈跳水〉。跳水是从跳台跳入水中的动作，“跳舞”不能这样用。"}, {"text": "他去年跳舞去了别的公司。", "explanation": "这里应该用〈跳槽〉。跳槽指换工作，“跳舞”只指随音乐动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我周末和朋友一起去的跳舞。", "corrected_sentence": "我周末和朋友一起去跳舞。", "error_description": "错误：“跳舞”前多加了“的”，“去的跳舞”不成立；应去掉“的”，说“去跳舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一边唱一边跳舞着。", "corrected_sentence": "她一边唱一边跳着舞。", "error_description": "错误：“着”应放在“跳”后，即“跳着舞”，不能放在“舞”后面。“跳舞着”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
