INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做对了事情，就是没有做错。", "primary_collocate": null, "pronunciation": "zuò duì", "ipa": "tswo˥˩ twei˥˩", "syllable_count": 2, "sentences": [{"text": "他做对了这个练习，很高兴。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，我做对了八道题。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做对了，不用再改。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，做对事情的人不用怕。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，只有三个学生做对了。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做对了作业，老师说我很好。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次做蛋糕就做对了。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做对了，我请你吃饭。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友把这道题做对了，老师很开心。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做对事不容易，要多想一想。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做对了", "label": "体标"}, {"form": "做对过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做事没有做错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e176a57-3f09-4b1b-b4b5-6e20e7f24a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做对", "is_correct": true, "explanation": "正确答案。做对了这个练习，表示做得正确，所以很高兴。"}, {"text": "做错", "is_correct": false, "explanation": "语义：做错了练习，与后半句很高兴的心情不合。"}, {"text": "做梦", "is_correct": false, "explanation": "语义：练习是用来做的，不能说做梦了这个练习。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象一般是歌曲，不能说唱这个练习。"}], "explanations": {"做对": "正确答案。做对了这个练习，表示做得正确，所以很高兴。", "做错": "语义：做错了练习，与后半句很高兴的心情不合。", "做梦": "语义：练习是用来做的，不能说做梦了这个练习。", "唱": "搭配：唱的对象一般是歌曲，不能说唱这个练习。"}, "sentence_index": 0, "correct_answer": "做对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做对了事情的经过，大家都很佩服他。", "explanation": "这里应该用〈说对〉。事情的经过是叙述出来的，做对指做事没有做错，不能用于叙述正确与否。"}, {"text": "他在课上居然做对了一个哈欠。", "explanation": "这里应该用〈打〉。哈欠是打出来的，做对指做事没有做错，不能用于此。"}, {"text": "这场棋很难，他最后居然做对了一盘。", "explanation": "这里应该用〈赢〉。做对指做事没有做错，下棋赢了一盘要说赢，不能说做对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做对", "is_correct": true, "explanation": "正确答案。第一次做蛋糕就做对了，表示做得正确。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是修复器物，与做蛋糕的动作不合。"}, {"text": "写", "is_correct": false, "explanation": "搭配：写要求有可写的对象，就写了与做蛋糕之间搭配不完整。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是转换语言，不能用于做蛋糕。"}], "explanations": {"做对": "正确答案。第一次做蛋糕就做对了，表示做得正确。", "修理": "语义：修理是修复器物，与做蛋糕的动作不合。", "写": "搭配：写要求有可写的对象，就写了与做蛋糕之间搭配不完整。", "翻译": "语义：翻译是转换语言，不能用于做蛋糕。"}, "sentence_index": 6, "correct_answer": "做对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的胜负，他做对了。", "explanation": "这里应该用〈预测对〉。胜负是预测出来的，做对表示做事不出错，不用于预测。"}, {"text": "这个案子的真相，他做对了。", "explanation": "这里应该用〈推理对〉。真相是推理出来的，做对不能用于推理的结果。"}, {"text": "他把窗户做对了三次。", "explanation": "这里应该用〈擦〉。做对指做事没有做错，擦窗户要说擦，不能说做对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次作业，我做对着五道题。", "corrected_sentence": "这次作业，我做对了五道题。", "error_description": "做对表示一次完成的结果，不能与表示持续状态的着搭配，应把着改为了，说做对了五道题。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班上只有他做对了了这道题。", "corrected_sentence": "我们班上只有他做对了这道题。", "error_description": "了只能出现一次，应紧跟结果补语对之后，说做对了这道题，不能在做对了之后再加一个了，说做对了了这道题。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
