INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24392, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮助别人脱离危险或困难。", "primary_collocate": null, "pronunciation": "jiù rén", "ipa": "tɕiou˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他不会游泳，没办法下水救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子倒了，大家马上进去救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的救生员每天都要准备救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，学会急救就可以救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火太大了，他们没能进去救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电影讲的是一个警察救人的故事。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次看到有人遇到危险，都会立刻去救人。", "target_word": "救人", "complexity_tier": "T3", "furigana": "jiù rén", "sentence_source": "generated"}, {"text": "老师教我们怎么在水里救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是医生，每天的工作就是救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位司机停下车，马上跑去救人。", "target_word": "救人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "救了人", "label": "完成体"}, {"form": "救过人", "label": "经历体"}], "register": "中性", "sense_fingerprint": "帮助别人摆脱危险或困难处境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24392, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "救人", "is_correct": true, "explanation": "救人 jiù rén：正确答案，指帮助别人摆脱危险或困难。"}, {"text": "九人", "is_correct": false, "explanation": "九人 jiǔ rén：jiǔ（第三声）与 jiù（第四声）声调不同，意思是九个人。"}, {"text": "就任", "is_correct": false, "explanation": "就任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是正式担任职务。"}, {"text": "叫人", "is_correct": false, "explanation": "叫人 jiào rén：jiù 与 jiào 韵母不同，意思是呼唤别人。"}], "explanations": {"救人": "救人 jiù rén：正确答案，指帮助别人摆脱危险或困难。", "九人": "九人 jiǔ rén：jiǔ（第三声）与 jiù（第四声）声调不同，意思是九个人。", "就任": "就任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是正式担任职务。", "叫人": "叫人 jiào rén：jiù 与 jiào 韵母不同，意思是呼唤别人。"}, "sentence_index": null, "correct_answer": "救人"}, "level_3": {"options": [{"text": "救人", "is_correct": true, "explanation": "正确：“没办法下水救人”指无法下水去帮助别人。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”与“下水”的语境无关，不能表示救助行动。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”与“下水”的语境冲突，不符合“不会游泳”的情境。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：“唱歌”的动作对象与“下水”的动作不匹配，不能形成有意义的动作关系。"}], "explanations": {"救人": "正确：“没办法下水救人”指无法下水去帮助别人。", "写作业": "语义：“写作业”与“下水”的语境无关，不能表示救助行动。", "下棋": "语义：“下棋”与“下水”的语境冲突，不符合“不会游泳”的情境。", "唱歌": "配价：“唱歌”的动作对象与“下水”的动作不匹配，不能形成有意义的动作关系。"}, "sentence_index": 0, "correct_answer": "救人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只掉进井里的小猫还在叫，他跑过去救人。", "explanation": "这里应该用〈捞出〉。“救人”的对象只能是人，救小猫不能用它。"}, {"text": "书架上的书掉了一地，他跑过去救人。", "explanation": "这里应该用〈捡起〉。“救人”只指救助人，不能用于书籍。"}, {"text": "他的手机掉进水里了，他跑过去救人。", "explanation": "这里应该用〈捞起〉。“救人”只指救助人，不能用于手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24392, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "救人", "is_correct": true, "explanation": "救人 jiù rén：正确答案，指帮助别人摆脱危险或困难。"}, {"text": "旧任", "is_correct": false, "explanation": "旧任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是前任。"}, {"text": "教人", "is_correct": false, "explanation": "教人 jiāo rén：jiù（第四声）与 jiāo（第一声）声调不同，意思是教导别人。"}, {"text": "求人", "is_correct": false, "explanation": "求人 qiú rén：jiù 与 qiú 声母和声调都不同，意思是请别人帮忙。"}], "explanations": {"救人": "救人 jiù rén：正确答案，指帮助别人摆脱危险或困难。", "旧任": "旧任 jiù rèn：rén（第二声）与 rèn（第四声）声调不同，意思是前任。", "教人": "教人 jiāo rén：jiù（第四声）与 jiāo（第一声）声调不同，意思是教导别人。", "求人": "求人 qiú rén：jiù 与 qiú 声母和声调都不同，意思是请别人帮忙。"}, "sentence_index": null, "correct_answer": "救人"}, "level_3": {"options": [{"text": "救人", "is_correct": true, "explanation": "正确：“立刻去救人”表示看到危险就马上行动，与句意相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“看到有人遇到危险，立刻去”的语境完全矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”是无所事事的状态，与“立刻去”的行动冲突。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“立刻去洗澡”不能对应“看到有人遇到危险”的反应，动作与情境不搭配。"}], "explanations": {"救人": "正确：“立刻去救人”表示看到危险就马上行动，与句意相符。", "睡觉": "语义：“睡觉”与“看到有人遇到危险，立刻去”的语境完全矛盾。", "发呆": "语义：“发呆”是无所事事的状态，与“立刻去”的行动冲突。", "洗澡": "搭配：“立刻去洗澡”不能对应“看到有人遇到危险”的反应，动作与情境不搭配。"}, "sentence_index": 6, "correct_answer": "救人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的电脑死机了，他赶紧跑过去救人。", "explanation": "这里应该用〈修〉。“救人”只用于人，不能指修理电脑。"}, {"text": "他把那盆快枯萎的花搬到阳光下，这是在救人。", "explanation": "这里应该用〈养护〉。“救人”只用于人，不能用于花草。"}, {"text": "他一见到那只破旧的钟表，就想跑过去救人。", "explanation": "这里应该用〈修复〉。“救人”的对象是人，不能用于钟表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个救人得人很勇敢。", "corrected_sentence": "那个救人的人很勇敢。", "error_description": "错误形式：“救人得人”。正确形式：“救人的人”。修饰名词时，“救人”后应用结构助词“的”，不能用补语标记“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他前天救人过。", "corrected_sentence": "他前天救人了。", "error_description": "错误形式：“救人过”。正确形式：“救人了”。表示动作已经完成用“了”；“过”表示经历，应放在动词后、宾语前（如“救过人”），不能放在宾语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24394, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24394, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很勇敢、做了好事的人。", "primary_collocate": null, "pronunciation": "yīng xióng", "ipa": "iŋ˥ ɕiʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他救了很多人，是大家心中的英雄。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位英雄从小就很勇敢。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想做一个英雄。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说那位消防员是英雄。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的英雄打败了坏人。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英雄也会害怕，但他还是往前走。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都崇拜那个为救人牺牲的英雄。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是天生的英雄，只是敢帮助别人。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全城的人都来欢迎回家的英雄。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的英雄救下了小女孩。", "target_word": "英雄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位英雄", "label": "量词"}, {"form": "一个英雄", "label": "量词"}, {"form": "民族英雄", "label": "复合"}, {"form": "英雄主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "英雄：勇敢并做了好事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "英雄", "is_correct": true, "explanation": "正确。“英雄”指做了好事、值得敬佩的人，与“救了很多人”相符。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”与“救了很多人”的形象相反，不能是大家心中的人物。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“心中的”多修饰人或抽象的形象，“工具”不能这样用。"}, {"text": "恶棍", "is_correct": false, "explanation": "语义：“恶棍”指作恶的坏人，与“救了很多人”矛盾。"}], "explanations": {"英雄": "正确。“英雄”指做了好事、值得敬佩的人，与“救了很多人”相符。", "小偷": "语义：“小偷”与“救了很多人”的形象相反，不能是大家心中的人物。", "工具": "搭配：“心中的”多修饰人或抽象的形象，“工具”不能这样用。", "恶棍": "语义：“恶棍”指作恶的坏人，与“救了很多人”矛盾。"}, "sentence_index": 0, "correct_answer": "英雄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班新来了一只英雄。", "explanation": "这里应该用〈位〉。“只”多用于动物或成对的东西，指人的英雄要用“位”或“个”。"}, {"text": "他偷了别人的钱，还撞伤了路人，是一个英雄。", "explanation": "这里应该用〈坏人〉。“英雄”指做了好事、值得敬佩的人，不能用来称做坏事的人。"}, {"text": "我家门口停着一台英雄。", "explanation": "这里应该用〈位〉或〈个〉。“台”用于机器、电器等物品，不用于指人的英雄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "英雄", "is_correct": true, "explanation": "正确。“为救人牺牲的英雄”指勇敢做好事、值得崇拜的人，符合句意。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：谎言不能为救人牺牲，也不值得崇拜，与句意相反。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不会为救人牺牲，不能成为被崇拜的对象。"}, {"text": "恶魔", "is_correct": false, "explanation": "语义：恶魔与“为救人牺牲”的形象相反，不符合句意。"}], "explanations": {"英雄": "正确。“为救人牺牲的英雄”指勇敢做好事、值得崇拜的人，符合句意。", "谎言": "语义：谎言不能为救人牺牲，也不值得崇拜，与句意相反。", "闹钟": "语义：闹钟不会为救人牺牲，不能成为被崇拜的对象。", "恶魔": "语义：恶魔与“为救人牺牲”的形象相反，不符合句意。"}, "sentence_index": 6, "correct_answer": "英雄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "操场边上站着一颗英雄。", "explanation": "这里应该用〈位〉或〈个〉。“颗”用于圆形的小东西，不用于指人的英雄。"}, {"text": "我们班来了一本英雄。", "explanation": "这里应该用〈位〉或〈个〉。“本”用于书、本子等物品，不用于指人的英雄。"}, {"text": "这碗面条很英雄，我每天都想吃。", "explanation": "这里应该用〈美味〉。“英雄”形容人的勇敢，不能用来形容食物好不好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人是我们村的一只英雄。", "corrected_sentence": "这位老人是我们村的英雄。", "error_description": "“英雄”指人，不能用“只”计量，“只”多用于动物。误句中的“一只”是错误的，应去掉量词，或改用“一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场大火中，他成了一个英雄们。", "corrected_sentence": "那场大火中，他成了一个英雄。", "error_description": "“一个”表示单数，不能和表示复数的“们”一起用。应说“一个英雄”，或改为“英雄们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24396, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "假的", "is_correct": true, "explanation": "假的：与“真的”意思相反，指不真实。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明：形容人智力高，与“真实”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴：形容心情愉快，与“真”不构成反义。"}, {"text": "健康", "is_correct": false, "explanation": "健康：形容身体状况良好，与“真”不构成反义。"}], "correct_answer": "假的", "explanations": {"假的": "假的：与“真的”意思相反，指不真实。", "聪明": "聪明：形容人智力高，与“真实”没有反义关系。", "高兴": "高兴：形容心情愉快，与“真”不构成反义。", "健康": "健康：形容身体状况良好，与“真”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24396, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "假的", "is_correct": true, "explanation": "假的：与“真的”意思相反，指不真实。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢：形容人不怕困难或危险，与“真实”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情：形容态度殷切，与“真”不构成反义。"}, {"text": "认真", "is_correct": false, "explanation": "认真：形容态度专心严肃，与“真”不构成反义。"}], "correct_answer": "假的", "explanations": {"假的": "假的：与“真的”意思相反，指不真实。", "勇敢": "勇敢：形容人不怕困难或危险，与“真实”没有反义关系。", "热情": "热情：形容态度殷切，与“真”不构成反义。", "认真": "认真：形容态度专心严肃，与“真”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24396, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "真的意思是事情是真实的，不是假的。", "primary_collocate": null, "pronunciation": "zhēn de", "ipa": "ʈʂən˥ tɤ", "syllable_count": 2, "sentences": [{"text": "这个消息是真的，不是玩笑。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道他说的是真的还是假的。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块表是真的，不是假的。", "target_word": "真的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你听到的故事不一定都是真的。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说他中了奖，我觉得不是真的。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事是真的，我自己看到了。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我，这个故事是真的吗？", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张画是真的，不是别人画的假画。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里的事不是真的，别害怕。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她以为我在开玩笑，其实我说的是真的。", "target_word": "真的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "真的吗", "label": "疑问形式"}, {"form": "真假", "label": "复合词"}], "register": "中性", "sense_fingerprint": "作谓语，表示事情真实、不是假的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真的", "is_correct": true, "explanation": "正确：“真的”作谓语，表示事情真实，与“不是玩笑”相符。"}, {"text": "可爱的", "is_correct": false, "explanation": "语义：“可爱的”形容事物讨人喜欢，与“消息”的真假判断不合。"}, {"text": "漂亮的", "is_correct": false, "explanation": "搭配：“消息”不能用“漂亮”来形容，搭配不当。"}, {"text": "安静的", "is_correct": false, "explanation": "搭配：“安静”形容环境或状态，不能用来描述“消息”。"}], "explanations": {"真的": "正确：“真的”作谓语，表示事情真实，与“不是玩笑”相符。", "可爱的": "语义：“可爱的”形容事物讨人喜欢，与“消息”的真假判断不合。", "漂亮的": "搭配：“消息”不能用“漂亮”来形容，搭配不当。", "安静的": "搭配：“安静”形容环境或状态，不能用来描述“消息”。"}, "sentence_index": 0, "correct_answer": "真的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数学题的答案很真的，但老师说它是错的。", "explanation": "这里应该用〈正确〉。“真的”指事情属实，不用于评价答案对错。"}, {"text": "这个电话号码很真的，我拨了三次都没接通。", "explanation": "这里应该用〈有效〉。“真的”指事情属实，不用来形容号码能否接通。"}, {"text": "这个数字很真的，我得再核对一下。", "explanation": "这里应该用〈准确〉。“真的”不用来形容数字是否精确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真的", "is_correct": true, "explanation": "正确：“真的”作谓语，询问故事是否属实，符合句意。"}, {"text": "大方的", "is_correct": false, "explanation": "语义：“大方”形容人的举止，不能用来描述故事的真假。"}, {"text": "大米", "is_correct": false, "explanation": "语义：“大米”是食物，不能作“故事是……吗”的谓语，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能用来判断故事的真假，句意不通。"}], "explanations": {"真的": "正确：“真的”作谓语，询问故事是否属实，符合句意。", "大方的": "语义：“大方”形容人的举止，不能用来描述故事的真假。", "大米": "语义：“大米”是食物，不能作“故事是……吗”的谓语，句意不通。", "椅子": "语义：“椅子”是家具，不能用来判断故事的真假，句意不通。"}, "sentence_index": 6, "correct_answer": "真的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盘菜很真的，我吃了一大碗。", "explanation": "这里应该用〈好吃〉。“真的”指事情属实、不是假的，不用来形容菜的味道。"}, {"text": "这件衣服很真的，穿在身上很好看。", "explanation": "这里应该用〈合身〉。“真的”指事情属实，不用来形容衣服的尺寸。"}, {"text": "这个房间很真的，住起来很安静。", "explanation": "这里应该用〈舒适〉。“真的”指事情属实，不用来形容房间的舒适程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片真的，我可以证明。", "corrected_sentence": "这张照片是真的，我可以证明。", "error_description": "错误形式：“这张照片真的”。正确形式：“这张照片是真的”。作谓语时，“真的”前面需要“是”，省略“是”会显得不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那封信是真的的，我认得他的字。", "corrected_sentence": "那封信是真的，我认得他的字。", "error_description": "错误形式：“真的的”。正确形式：“真的”。“真的”后面不能再加“的”，多出的“的”使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
