INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人怎样对待别人和事情，比如要善良、有礼貌。", "primary_collocate": null, "pronunciation": "zuò rén", "ipa": "tsuo˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "做人要善良，要多帮助别人。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常教我，做人要懂礼貌。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做人很热心，总是帮邻居。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人不能自私，要想想别人。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，做人比考高分更重要。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做人很和气，没人和她吵架。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子，做人要守信用，说到做到。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家的孩子做人很好，见人就问好。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要对朋友好，别说假话。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小学会了怎么做人。", "target_word": "做人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做人处世", "label": "复合"}], "register": "中性", "sense_fingerprint": "待人接物时的善良与礼貌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做人", "is_correct": true, "explanation": "“做人”指待人接物的善良与礼貌，与“要善良，要多帮助别人”相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与待人接物的善良无关，“唱歌要善良”句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是运动技能，不涉及善良，句意不通。"}, {"text": "下棋", "is_correct": false, "explanation": "搭配：“要善良”针对待人的态度，“下棋”不能与之搭配。"}], "explanations": {"做人": "“做人”指待人接物的善良与礼貌，与“要善良，要多帮助别人”相符。", "唱歌": "语义：唱歌与待人接物的善良无关，“唱歌要善良”句意不通。", "游泳": "语义：游泳是运动技能，不涉及善良，句意不通。", "下棋": "搭配：“要善良”针对待人的态度，“下棋”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "做人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在厨房做人，做得很香。", "explanation": "这里应该用〈做饭〉。“做人”指待人接物的品德，不能指做饭。"}, {"text": "他每天早上在操场上做人。", "explanation": "这里应该用〈做操〉。“做人”不指体育活动，不能说在操场上做人。"}, {"text": "他每天都在店里做人，做了很多生意。", "explanation": "这里误把“做人”当成〈经营买卖〉义来用。“做人”指待人接物的品德，不能指经营买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做人", "is_correct": true, "explanation": "“做人”指待人接物的善良与礼貌，与“要守信用，说到做到”的教导相符。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：做饭与守信用无关，“做饭要守信用”句意不通。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋不涉及守信用的待人原则，句意不通。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“守信用”是对人际承诺的评价，不与“跑步”搭配。"}], "explanations": {"做人": "“做人”指待人接物的善良与礼貌，与“要守信用，说到做到”的教导相符。", "做饭": "语义：做饭与守信用无关，“做饭要守信用”句意不通。", "下棋": "语义：下棋不涉及守信用的待人原则，句意不通。", "跑步": "搭配：“守信用”是对人际承诺的评价，不与“跑步”搭配。"}, "sentence_index": 6, "correct_answer": "做人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小在车库做人，修好了自行车。", "explanation": "这里应该用〈修理〉。“做人”指待人接物的品德，不能指修理自行车。"}, {"text": "他从小在学校做人，考了好成绩。", "explanation": "这里应该用〈学习〉。“做人”不能指学习知识。"}, {"text": "他从小在工厂做人，做了很多零件。", "explanation": "这里误把“做人”当成〈制作〉义来用。“做人”指待人接物的品德，不能指制作零件等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲告诉我做人了要诚实。", "corrected_sentence": "父亲告诉我做人要诚实。", "error_description": "错误：“做人”后面多加了动态助词“了”，“做人了要诚实”不自然。正确：“做人要诚实”，“做人”是名词性的固定说法，后面不带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做人得很认真。", "corrected_sentence": "她做人做得很认真。", "error_description": "错误：“做人得”漏了重复的动词“做”。正确：“做人做得很认真”，用动词“做”带补语“得很认真”来说明做人的方式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
