INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24408, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火炉是冬天用来取暖的炉子。", "primary_collocate": null, "pronunciation": "huǒ lú", "ipa": "xwɔ˨˩˦ lu˧˥", "syllable_count": 2, "sentences": [{"text": "天太冷了，快来火炉边坐一会儿。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家客厅里有一个大火炉。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷把火炉里的火点着了。", "target_word": "火炉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火炉旁边的地方最暖和。", "target_word": "火炉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外面下雪，屋里的火炉很暖和。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们的手冷了，就跑到火炉前取暖。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个火炉用木柴，不用电。", "target_word": "火炉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在火炉前坐着看书。", "target_word": "火炉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火炉里的火快灭了，再加点儿木柴吧。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我家冬天只靠一个火炉取暖。", "target_word": "火炉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "火爐", "label": "繁体"}], "register": "中性", "sense_fingerprint": "冬天取暖用的炉子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火炉", "is_correct": true, "explanation": "正确：火炉是冬天取暖的炉子，快去火炉边坐一会儿符合句意。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块会让人更冷，与“天太冷了”需要取暖的语境相反。"}, {"text": "冰柜", "is_correct": false, "explanation": "语义：冰柜用来冷冻食物，不能靠近取暖。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”是抽象概念，不能说“快来天气边坐一会儿”。"}], "explanations": {"火炉": "正确：火炉是冬天取暖的炉子，快去火炉边坐一会儿符合句意。", "冰块": "语义：冰块会让人更冷，与“天太冷了”需要取暖的语境相反。", "冰柜": "语义：冰柜用来冷冻食物，不能靠近取暖。", "天气": "搭配：“天气”是抽象概念，不能说“快来天气边坐一会儿”。"}, "sentence_index": 0, "correct_answer": "火炉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天屋里开着火炉，很凉快。", "explanation": "这里应该用〈空调〉。火炉用来取暖，不能降温；夏天让屋里凉快要用空调。"}, {"text": "他渴了，就端起火炉喝了一口。", "explanation": "这里应该用〈水〉。火炉是取暖的炉子，不能用来喝；渴了要喝水。"}, {"text": "夏天，妈妈把西瓜放进火炉里冷藏。", "explanation": "这里应该用〈冰箱〉。火炉不能冷藏食物；冷藏要用冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火炉", "is_correct": true, "explanation": "正确：这个火炉烧木柴、不用电，符合句意。"}, {"text": "电暖器", "is_correct": false, "explanation": "语义：电暖器靠电发热，与“不用电”矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来冷藏食物，不烧木柴，也不取暖。"}, {"text": "电饭煲", "is_correct": false, "explanation": "搭配：“电饭煲”靠电煮饭，不能说“用木柴”。"}], "explanations": {"火炉": "正确：这个火炉烧木柴、不用电，符合句意。", "电暖器": "语义：电暖器靠电发热，与“不用电”矛盾。", "冰箱": "语义：冰箱用来冷藏食物，不烧木柴，也不取暖。", "电饭煲": "搭配：“电饭煲”靠电煮饭，不能说“用木柴”。"}, "sentence_index": 6, "correct_answer": "火炉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把脏衣服放进火炉里洗。", "explanation": "这里应该用〈洗衣机〉。火炉用来取暖、烧东西，不能洗衣服；洗衣服要用洗衣机。"}, {"text": "冬天，我把火炉放进了口袋里。", "explanation": "这里应该用〈暖宝宝〉。火炉体积大，不能放进口袋；口袋里放的是暖宝宝。"}, {"text": "睡觉前，妈妈给我灌了一个火炉。", "explanation": "这里应该用〈热水袋〉。“灌”用于水袋之类，火炉不能灌；睡前取暖要用热水袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人围着一只火炉喝茶。", "corrected_sentence": "老人围着一个火炉喝茶。", "error_description": "量词错误：“一只火炉”应为“一个火炉”。“只”多用于动物或成对器物中的单件，火炉用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把水壶放在火炉。", "corrected_sentence": "奶奶把水壶放在火炉上。", "error_description": "方位词遗漏：“放在火炉”应为“放在火炉上”。表示物体放在炉子表面时，要在名词后加方位词“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
