INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24410, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家人，比如爸爸、妈妈、孩子，他们住在一起互相照顾。", "primary_collocate": null, "pronunciation": "jiā zú", "ipa": "tɕja˥ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "家族成员之间要互相照顾，关系很亲近。", "target_word": "家族", "complexity_tier": "T3", "furigana": "jiā zú chéng yuán zhī jiān yào hù xiāng zhào gù, guān xì hěn qīn jìn.", "sentence_source": "generated"}, {"text": "家族里的每个人都住在一起，每天互相照顾。", "target_word": "家族", "complexity_tier": "T3", "furigana": "jiā zú lǐ de měi gè rén dōu zhù zài yì qǐ, měi tiān hù xiāng zhào gù.", "sentence_source": "generated"}, {"text": "他们家族每天一起吃晚饭，互相照顾。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家族一直住在一起，感情很好。", "target_word": "家族", "complexity_tier": "T3", "furigana": "wǒ de jiā zú yì zhí zhù zài yì qǐ, gǎn qíng hěn hǎo.", "sentence_source": "generated"}, {"text": "这个家族里的人都很体贴，经常互相帮助。", "target_word": "家族", "complexity_tier": "T3", "furigana": "zhè ge jiā zú lǐ de rén dōu hěn tǐ tiē, jīng cháng hù xiāng bāng zhù.", "sentence_source": "generated"}, {"text": "她的家族里，大家都会互相照顾。", "target_word": "家族", "complexity_tier": "T3", "furigana": "tā de jiā zú lǐ, dà jiā dōu huì hù xiāng zhào gù.", "sentence_source": "generated"}, {"text": "这个家族有爸爸、妈妈和两个孩子。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病时，整个家族都很着急。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家族的人住在一起，生活很温馨。", "target_word": "家族", "complexity_tier": "T3", "furigana": "jiā zú de rén zhù zài yì qǐ, shēng huó hěn wēn xīn.", "sentence_source": "generated"}, {"text": "他为了家族，每天工作到很晚。", "target_word": "家族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大家族", "label": "复合"}], "register": "中性", "sense_fingerprint": "住在一起互相照顾的家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正确。“家族成员之间要互相照顾”指住在一起互相照顾的家人，符合句意。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“词典”不是由成员组成、能够互相照顾的群体，句意不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”没有成员，也不能“互相照顾”，与句意冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“成员”不能指冰箱，“互相照顾”的对象也不能是冰箱。"}], "explanations": {"家族": "正确。“家族成员之间要互相照顾”指住在一起互相照顾的家人，符合句意。", "词典": "语义：“词典”不是由成员组成、能够互相照顾的群体，句意不通。", "河流": "语义：“河流”没有成员，也不能“互相照顾”，与句意冲突。", "冰箱": "搭配：“成员”不能指冰箱，“互相照顾”的对象也不能是冰箱。"}, "sentence_index": 0, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人的家族住在一起，感情很好。", "explanation": "这里不能用“家族”指一个人。“家族”指住在一起的多位家人，“我一个人的家族”自相矛盾。"}, {"text": "一座家族住在一起，感情很好。", "explanation": "这里应该用〈个〉。“座”用于山、楼等大型固定物，不能用于“家族”。"}, {"text": "我的家族今天一个人去上班了。", "explanation": "这里不能用“家族”指一个人。“家族”指住在一起、互相照顾的一群家人，“一个人去上班”与“家族”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正确。“这个家族有爸爸、妈妈和两个孩子”指住在一起的家人，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“学校”不能有爸爸、妈妈和孩子这样的家人，句意不通。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“公司”不是由爸爸、妈妈和孩子组成的家人群体，与句意冲突。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“有爸爸、妈妈和两个孩子”的主语需要是家人，“城市”不能与此搭配。"}], "explanations": {"家族": "正确。“这个家族有爸爸、妈妈和两个孩子”指住在一起的家人，符合句意。", "学校": "语义：“学校”不能有爸爸、妈妈和孩子这样的家人，句意不通。", "公司": "语义：“公司”不是由爸爸、妈妈和孩子组成的家人群体，与句意冲突。", "城市": "搭配：“有爸爸、妈妈和两个孩子”的主语需要是家人，“城市”不能与此搭配。"}, "sentence_index": 6, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了一颗家族，每天工作到很晚。", "explanation": "这里应该用〈个〉。“颗”用于小而圆的东西，不能用于“家族”。"}, {"text": "他的家族今天一个人去跑步了。", "explanation": "这里不能用“家族”指一个人。“家族”指住在一起的多位家人，“一个人去跑步”与“家族”的意思矛盾。"}, {"text": "他把家族放进书包，带去学校。", "explanation": "这里应该用〈课本〉。家族是一群人，不能放进书包；带去学校的应是书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条家族的人都住在北京。", "corrected_sentence": "这个家族的人都住在北京。", "error_description": "量词误用：“家族”前应用量词“个”，“这条家族”用了“条”，应改为“这个家族”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家族人都互相照顾。", "corrected_sentence": "我们家族的人都互相照顾。", "error_description": "助词遗漏：“我们家族”修饰“人”时需要用“的”，应写作“我们家族的人”，漏掉“的”是语法错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
