INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西的最外面部分。", "primary_collocate": null, "pronunciation": "biān", "ipa": "pjɛn˥", "syllable_count": 1, "sentences": [{"text": "请不要扶着椅子的边。", "target_word": "边", "complexity_tier": "T3", "furigana": "biān", "sentence_source": "generated"}, {"text": "这本书的边有点儿脏。", "target_word": "边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用手摸了摸桌子的边。", "target_word": "边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服的边缝着一圈红线。", "target_word": "边", "complexity_tier": "T3", "furigana": "biān", "sentence_source": "generated"}, {"text": "小心，玻璃的边很锋利。", "target_word": "边", "complexity_tier": "T3", "furigana": "biān", "sentence_source": "generated"}, {"text": "池塘的边长满了绿草。", "target_word": "边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把花盆往窗台的边挪了挪。", "target_word": "边", "complexity_tier": "T3", "furigana": "biān", "sentence_source": "generated"}, {"text": "盘子的边画着一朵小花。", "target_word": "边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的边很整齐。", "target_word": "边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "碗的边破了，不能用了。", "target_word": "边", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊", "label": "繁体"}, {"form": "边上", "label": "复合"}, {"form": "旁边", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西最外面的一圈或一条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24412, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "边", "is_correct": true, "explanation": "正确：边指东西的最外面部分。"}, {"text": "偏", "is_correct": false, "explanation": "piān（第一声）与 biān 声母不同（p 与 b），意思是偏向，不指东西的外部。"}, {"text": "变", "is_correct": false, "explanation": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}], "explanations": {"边": "正确：边指东西的最外面部分。", "偏": "piān（第一声）与 biān 声母不同（p 与 b），意思是偏向，不指东西的外部。", "变": "biàn（第四声）与 biān（第一声）声调不同，意思是改变。", "扁": "biǎn（第三声）与 biān（第一声）声调不同，意思是扁平。"}, "sentence_index": null, "correct_answer": "边"}, "level_3": {"options": [{"text": "边", "is_correct": true, "explanation": "正确：扶着椅子的边，指椅子最外面的部分，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“扶”的对象要是实体部位，不能说“扶着椅子的颜色”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是无形的，不能被手扶着，与句意不合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感觉，不能被手扶着，与句意不合。"}], "explanations": {"边": "正确：扶着椅子的边，指椅子最外面的部分，符合句意。", "颜色": "搭配：“扶”的对象要是实体部位，不能说“扶着椅子的颜色”。", "声音": "语义：声音是无形的，不能被手扶着，与句意不合。", "味道": "语义：味道是感觉，不能被手扶着，与句意不合。"}, "sentence_index": 0, "correct_answer": "边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷用边熬了一碗药。", "explanation": "这里应该用〈药罐〉。“边”指东西最外面的部分，不能用来熬药；熬药要用药罐。"}, {"text": "他饿了，就吃了一口边。", "explanation": "这里应该用〈饼干〉之类的食物。“边”指东西最外面的部分，不是食物，不能吃。"}, {"text": "这首歌的边很好听。", "explanation": "这里应该用〈旋律〉。“边”指东西最外面的部分，歌曲没有这样的部分；好听的是旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边", "is_correct": true, "explanation": "正确：把花盆往窗台的边挪，指窗台最外面的部分，符合句意。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味是无形的，不能被挪动，与句意不合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是抽象的称呼，不是可以挪动的部分，与句意不合。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能说“往…挪”，与“挪了挪”搭配不当。"}], "explanations": {"边": "正确：把花盆往窗台的边挪，指窗台最外面的部分，符合句意。", "气味": "语义：气味是无形的，不能被挪动，与句意不合。", "名字": "语义：名字是抽象的称呼，不是可以挪动的部分，与句意不合。", "心情": "搭配：“心情”不能说“往…挪”，与“挪了挪”搭配不当。"}, "sentence_index": 6, "correct_answer": "边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的边很高。", "explanation": "这里应该用〈山顶〉。“边”指东西最外面的部分，说山的高处要用山顶，不能说山的边。"}, {"text": "我买了三块边。", "explanation": "这里应该用〈布料〉。“边”指东西最外面的部分，买的是布料本身，不能只买它的边缘。"}, {"text": "他的边很热情。", "explanation": "这里应该用〈性格〉。“边”指东西最外面的部分，形容人的品质要说性格，不能说边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把桌布的一只边折起来了。", "corrected_sentence": "他把桌布的一条边折起来了。", "error_description": "量词错误：“一只边”应为“一条边”。“只”用于动物，边用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "碗的边摔了坏。", "corrected_sentence": "碗的边摔坏了。", "error_description": "语序错误：“摔了坏”应为“摔坏了”。结果补语“坏”要紧跟动词“摔”，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
