INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长辈是家里年纪大的人，比如爷爷奶奶。", "primary_collocate": null, "pronunciation": "zhǎng bèi", "ipa": "ʈʂɑŋ˨˩˦ pei˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷奶奶是我家的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和长辈住在一起。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长辈年纪大了，我们要照顾他们。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节我去看长辈，带了水果。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给长辈倒了一杯茶。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长辈坐在客厅里喝茶。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的长辈都很爱我。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向长辈学会了做饭。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多陪陪家里的长辈。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长辈生日那天，全家人一起吃饭。", "target_word": "长辈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "长辈们", "label": "复数"}], "register": "中性", "sense_fingerprint": "家里年纪大的人，如爷爷奶奶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b98e791d-83a1-47e0-a7fc-a2d89d85f752') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长辈", "is_correct": true, "explanation": "“长辈”指家里年纪大的人，与“爷爷奶奶是我家的”相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不是家里年纪大的人，“爷爷奶奶是我家的小狗”句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能指爷爷奶奶，句意不通。"}, {"text": "对手", "is_correct": false, "explanation": "搭配：“我家的对手”与家人身份不搭配，“对手”指竞争的一方。"}], "explanations": {"长辈": "“长辈”指家里年纪大的人，与“爷爷奶奶是我家的”相符。", "小狗": "语义：小狗不是家里年纪大的人，“爷爷奶奶是我家的小狗”句意不通。", "桌子": "语义：桌子是家具，不能指爷爷奶奶，句意不通。", "对手": "搭配：“我家的对手”与家人身份不搭配，“对手”指竞争的一方。"}, "sentence_index": 0, "correct_answer": "长辈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小孩是家里的长辈。", "explanation": "这里应该用〈宝贝〉。长辈指辈分高、年纪大的人，不能指年幼的小孩。"}, {"text": "我家的长辈是一张桌子。", "explanation": "这里误把“长辈”当成〈家具〉来用。长辈指人，不能指桌子。"}, {"text": "我把长辈放进了书包里。", "explanation": "这里误把“长辈”当成〈实物〉来用。长辈指人，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长辈", "is_correct": true, "explanation": "“长辈”指家里年纪大的人，与“都很爱我”的家人情境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不会爱人，“家里的厨房都很爱我”句意不通。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具没有感情，不能“很爱我”，句意不通。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“很爱我”的主语应是有感情的人，与“垃圾桶”不搭配。"}], "explanations": {"长辈": "“长辈”指家里年纪大的人，与“都很爱我”的家人情境相符。", "厨房": "语义：厨房是房间，不会爱人，“家里的厨房都很爱我”句意不通。", "家具": "语义：家具没有感情，不能“很爱我”，句意不通。", "垃圾桶": "搭配：“很爱我”的主语应是有感情的人，与“垃圾桶”不搭配。"}, "sentence_index": 6, "correct_answer": "长辈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口站着一条长辈，很热情。", "explanation": "这里应该用〈位〉。长辈指人，不能用“条”来计量。"}, {"text": "爷爷家住着一块长辈。", "explanation": "这里应该用〈位〉。长辈指人，不能用“块”来计量。"}, {"text": "客厅里坐着两把长辈。", "explanation": "这里应该用〈位〉。长辈指人，不能用“把”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有三只长辈住在乡下。", "corrected_sentence": "我家有三位长辈住在乡下。", "error_description": "错误：量词“只”用于动物，指人时用错了量词，“三只长辈”不对。正确：“三位长辈”，指人的量词用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候常陪一个位长辈散步。", "corrected_sentence": "我小时候常陪一位长辈散步。", "error_description": "错误：“位”本身已是量词，前面不能再加“个”，“一个位长辈”重复计量。正确：“一位长辈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e1c5fd-2988-4696-ac71-9e3e715a0353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
