INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "祖先就是很早很早以前的人，比如爷爷奶奶的爷爷奶奶。", "primary_collocate": null, "pronunciation": "zǔ xiān", "ipa": "tsu˨˩ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "我们的祖先很早就住在这里。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的祖先是从北方搬来的。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年春天，我们都去祭拜祖先。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祖先留下了很多好习惯。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位祖先的故事我听奶奶讲过。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子里挂着祖先的照片。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常说，不能忘记自己的祖先。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现，人类的祖先来自非洲。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人很重视祖先留下的传统。", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道你家的祖先是谁吗？", "target_word": "祖先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "祖先崇拜", "label": "复合"}], "register": "中性", "sense_fingerprint": "很早以前的人，指一家一族或人类的前辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fd5d6a-ee47-45b7-8109-ed74731efdc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祖先", "is_correct": true, "explanation": "正确：「我们的祖先很早就住在这里」指很久以前的前辈，与「很早」相符。"}, {"text": "子孙", "is_correct": false, "explanation": "语义：「子孙」指后代，与「很早就住在这里」的过去时间不合。"}, {"text": "后代", "is_correct": false, "explanation": "语义：「后代」指之后出生的人，与「很早」相矛盾。"}, {"text": "祖国", "is_correct": false, "explanation": "搭配：「住在」的主语须是人，「祖国」不能用于此搭配。"}], "explanations": {"祖先": "正确：「我们的祖先很早就住在这里」指很久以前的前辈，与「很早」相符。", "子孙": "语义：「子孙」指后代，与「很早就住在这里」的过去时间不合。", "后代": "语义：「后代」指之后出生的人，与「很早」相矛盾。", "祖国": "搭配：「住在」的主语须是人，「祖国」不能用于此搭配。"}, "sentence_index": 0, "correct_answer": "祖先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上的祖先在散步，很多人都在看。", "explanation": "这里应该用〈老人〉。祖先指已去世的前辈，不能指在街上散步的活人。"}, {"text": "我的祖先下个月就要结婚了。", "explanation": "这里的「祖先」被误用为「活着的家人」的意思。祖先指很早以前的人，指活着的亲人应该用〈家人〉。"}, {"text": "爷爷每天给祖先打电话，问他们吃饭了没有。", "explanation": "这里的「祖先」被误用为「能接电话的活人」的意思。祖先早已去世，无法接电话，指活着的亲人应该用〈亲人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祖先", "is_correct": true, "explanation": "正确：「不能忘记自己的祖先」指前辈，与句意相符。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：「建筑」不是人，不能用「忘记」来形容它与「自己的」的关系，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是可以被「自己的」拥有的对象，与句意不合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「自己的石头」的说法与「不能忘记」的语境不搭配，句意不通。"}], "explanations": {"祖先": "正确：「不能忘记自己的祖先」指前辈，与句意相符。", "建筑": "语义：「建筑」不是人，不能用「忘记」来形容它与「自己的」的关系，句意不通。", "天气": "语义：「天气」不是可以被「自己的」拥有的对象，与句意不合。", "石头": "搭配：「自己的石头」的说法与「不能忘记」的语境不搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "祖先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一只祖先在远方生活。", "explanation": "这里应该用〈位〉。指人的「祖先」要用「位」，不能用「只」。"}, {"text": "我的祖先坏了，明天要修。", "explanation": "这里的「祖先」被误用为「机器、物品」的意思。祖先只指已去世的前辈，不能指物品，这里应该用〈电脑〉。"}, {"text": "这是我的祖先，他今年五岁。", "explanation": "这里应该用〈后代〉。祖先指已去世的前辈，不能指现在的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就听爷爷讲一只祖先的故事。", "corrected_sentence": "他从小就听爷爷讲一位祖先的故事。", "error_description": "指人的「祖先」，量词应为「位」，不能用「只」。「一只祖先」错误，正确为「一位祖先」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多祖先们都很勇敢。", "corrected_sentence": "很多祖先都很勇敢。", "error_description": "「很多」与「们」不能同用，「很多祖先们」错误，正确为「很多祖先」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
