INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人住在一起，大家一起生活。", "primary_collocate": null, "pronunciation": "bù luò", "ipa": "pu⁵¹ lwɔ⁵¹", "syllable_count": 2, "sentences": [{"text": "他们住在一个小部落里。", "target_word": "部落", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个部落有一百多人。", "target_word": "部落", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "部落里的人一起打猎。", "target_word": "部落", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多年前，这里有一个大部落。", "target_word": "部落", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部落的老人给孩子讲故事。", "target_word": "部落", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在非洲的一个部落生活过。", "target_word": "部落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个部落的人成了好朋友。", "target_word": "部落", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个部落的人都爱唱歌。", "target_word": "部落", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "部落里没有电，晚上很安静。", "target_word": "部落", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们离开了原来的部落。", "target_word": "部落", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "许多人聚居、共同生活的群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e621cd-3813-46e8-abfa-9d13f45d7637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部落", "is_correct": true, "explanation": "部落：很多人聚居、共同生活的群体，与“住在一个小……里”搭配自然。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食品，不能用来住人。"}, {"text": "手指", "is_correct": false, "explanation": "语义：“手指”是身体部位，不是可以居住的地方。"}, {"text": "乐章", "is_correct": false, "explanation": "搭配：“乐章”是音乐的段落，不能作为住所。"}], "explanations": {"部落": "部落：很多人聚居、共同生活的群体，与“住在一个小……里”搭配自然。", "饼干": "语义：“饼干”是食品，不能用来住人。", "手指": "语义：“手指”是身体部位，不是可以居住的地方。", "乐章": "搭配：“乐章”是音乐的段落，不能作为住所。"}, "sentence_index": 0, "correct_answer": "部落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国有五十六个部落。", "explanation": "这里应该用〈民族〉。部落指规模较小、聚居的群体，不能指国内的各个民族。"}, {"text": "这个部落有五千万人。", "explanation": "这里应该用〈国家〉。部落规模较小，不能用来说有五千万人。"}, {"text": "他去部落买了一瓶水。", "explanation": "这里应该用〈商店〉。部落是聚居的群体，不能当作购物的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部落", "is_correct": true, "explanation": "部落：聚居的群体，“两个部落的人”指两个这样的群体。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”是天体，不能指人的群体。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”是饮品，不能指人的群体。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：“树叶”是植物的器官，不能指人的群体。"}], "explanations": {"部落": "部落：聚居的群体，“两个部落的人”指两个这样的群体。", "星星": "语义：“星星”是天体，不能指人的群体。", "咖啡": "语义：“咖啡”是饮品，不能指人的群体。", "树叶": "语义：“树叶”是植物的器官，不能指人的群体。"}, "sentence_index": 6, "correct_answer": "部落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天在部落里上班。", "explanation": "这里应该用〈公司〉。部落是聚居的群体，不是工作单位。"}, {"text": "这台手机有两个部落。", "explanation": "这里应该用〈部件〉。部落指聚居的人群，不能用来指手机的组成部分。"}, {"text": "那位老师是我的部落。", "explanation": "这里应该用〈朋友〉。部落指一个群体，不能用来指某一位老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们是这个地区的一座小部落。", "corrected_sentence": "他们是这个地区的一个小部落。", "error_description": "错误形式：“一座小部落”。正确形式：“一个小部落”。“部落”的量词应用“个”，不用“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只部落的人都很热情。", "corrected_sentence": "这个部落的人都很热情。", "error_description": "错误形式：“这只部落”；正确形式：“这个部落”。“只”是用于动物等的量词，“部落”应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
