INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24428, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是真的。", "primary_collocate": null, "pronunciation": "jiǎ", "ipa": "tɕja˨˩˦", "syllable_count": 1, "sentences": [{"text": "这块玉是假的，一点儿也不值钱。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说他有钱，那是假的。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的苹果是假的，不能吃。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个故事是真的，不是假的。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出的身份证是假的，警察一看就发现了。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件名牌衣服是假的，只卖五十块。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼泪是假的，大家都不相信。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你给我的地址是假的，我找不到这个地方。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的手机有很多假的。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画是真的还是假的，专家也看不出来。", "target_word": "假", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假话", "label": "复合"}, {"form": "假货", "label": "复合"}], "register": "中性", "sense_fingerprint": "不是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e176a57-3f09-4b1b-b4b5-6e20e7f24a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24428, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假", "is_correct": true, "explanation": "正确：假（jiǎ）表示不是真的。"}, {"text": "家", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。"}, {"text": "架", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。"}], "explanations": {"假": "正确：假（jiǎ）表示不是真的。", "家": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。", "价": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。", "架": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。"}, "sentence_index": null, "correct_answer": "假"}, "level_3": {"options": [{"text": "假", "is_correct": true, "explanation": "正确。假：不是真的，与“不值钱”相合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜指味道，玉没有甜不甜的问题，句意不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖是形体特征，不能用来形容玉，句意不通。"}, {"text": "烫", "is_correct": false, "explanation": "语义：烫指温度，玉不能是“烫的”，句意不通。"}], "explanations": {"假": "正确。假：不是真的，与“不值钱”相合。", "甜": "语义：甜指味道，玉没有甜不甜的问题，句意不通。", "胖": "体貌：胖是形体特征，不能用来形容玉，句意不通。", "烫": "语义：烫指温度，玉不能是“烫的”，句意不通。"}, "sentence_index": 0, "correct_answer": "假"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他明天要请假，不来上班了。", "explanation": "这里的“假”读 jià，指休假，与“不是真的”的义项不同。"}, {"text": "今天放假，我们去公园吧。", "explanation": "这里的“假”读 jià，指假期，与“不是真的”的义项不同。"}, {"text": "他请了三天假，回家看父母。", "explanation": "这里的“假”读 jià，指休假，与“不是真的”的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24428, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "假", "is_correct": true, "explanation": "正确：假（jiǎ）表示不是真的。"}, {"text": "加", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。"}, {"text": "嫁", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是出嫁。"}, {"text": "驾", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是驾驶。"}], "explanations": {"假": "正确：假（jiǎ）表示不是真的。", "加": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。", "嫁": "jià（第四声）与 jiǎ（第三声）声调不同，意思是出嫁。", "驾": "jià（第四声）与 jiǎ（第三声）声调不同，意思是驾驶。"}, "sentence_index": null, "correct_answer": "假"}, "level_3": {"options": [{"text": "假", "is_correct": true, "explanation": "正确。假：不是真的，眼泪是假的，大家才不相信。"}, {"text": "轻", "is_correct": false, "explanation": "语义：轻指重量小，不能用来形容眼泪是否真假，句意不通。"}, {"text": "方", "is_correct": false, "explanation": "体貌：方是形状特征，眼泪不能用来形容形状，句意不通。"}, {"text": "硬", "is_correct": false, "explanation": "语义：硬指质地坚硬，眼泪不能是“硬的”，句意不通。"}], "explanations": {"假": "正确。假：不是真的，眼泪是假的，大家才不相信。", "轻": "语义：轻指重量小，不能用来形容眼泪是否真假，句意不通。", "方": "体貌：方是形状特征，眼泪不能用来形容形状，句意不通。", "硬": "语义：硬指质地坚硬，眼泪不能是“硬的”，句意不通。"}, "sentence_index": 6, "correct_answer": "假"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他请假回家了，这周不来上课。", "explanation": "这里的“假”读 jià，指休假，与“不是真的”的义项不同。"}, {"text": "明天是星期天，我们都放假。", "explanation": "这里的“假”读 jià，指假期，与“不是真的”的义项不同。"}, {"text": "我想请两天假，去看看医生。", "explanation": "这里的“假”读 jià，指休假，与“不是真的”的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他演很假。", "corrected_sentence": "他演得很假。", "error_description": "补语错误：“演”后表示程度的补语要加“得”，应说“演得很假”，不能说“演很假”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服假很。", "corrected_sentence": "这件衣服很假。", "error_description": "词序错误：程度副词“很”应放在形容词“假”之前，应说“很假”，不能说“假很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
