INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个可以看动画片和新闻的方盒子。", "primary_collocate": null, "pronunciation": "diàn shì", "ipa": "tjɛn˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "晚上我们一家人在客厅看电视。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客厅里有一台新电视。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在看电视上的新闻。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢看电视里的动画片。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把电视的声音关小一点。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视坏了，今天不能看足球比赛。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天晚上都开着电视睡觉。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电视是去年买的。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少看电视，常常看书。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在说明天的天气。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "电视机", "label": "复合"}, {"form": "电视台", "label": "复合"}, {"form": "電視", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家里用来看节目、新闻和动画片的电器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b36993-6be1-4beb-8bc2-c6c37fd0d0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确答案：电视（diàn shì），指家里用来看节目、新闻和动画片的电器。"}, {"text": "面试", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 对 d），意思是求职或入学时的考核，不是电器。"}, {"text": "电石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是一种化工原料。"}, {"text": "但是", "is_correct": false, "explanation": "dàn 与 diàn 韵母不同（缺少 i），意思是连词“但是”。"}], "explanations": {"电视": "正确答案：电视（diàn shì），指家里用来看节目、新闻和动画片的电器。", "面试": "miàn 与 diàn 声母不同（m 对 d），意思是求职或入学时的考核，不是电器。", "电石": "shí（第二声）与 shì（第四声）声调不同，意思是一种化工原料。", "但是": "dàn 与 diàn 韵母不同（缺少 i），意思是连词“但是”。"}, "sentence_index": null, "correct_answer": "电视"}, "level_3": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确：电视是客厅里可以“看”的电器，与“看”和晚上一家人在客厅的场景相合。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的东西，客厅里没有，也不能用来看节目。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：句中是晚上，看不到太阳，客厅也不是看太阳的地方。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“看”一般不接“冰箱”，冰箱是用来存放食物的。"}], "explanations": {"电视": "正确：电视是客厅里可以“看”的电器，与“看”和晚上一家人在客厅的场景相合。", "黑板": "语义：黑板是教室里的东西，客厅里没有，也不能用来看节目。", "太阳": "语义：句中是晚上，看不到太阳，客厅也不是看太阳的地方。", "冰箱": "搭配：“看”一般不接“冰箱”，冰箱是用来存放食物的。"}, "sentence_index": 0, "correct_answer": "电视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在电影院看电视。", "explanation": "这里应该用〈电影〉。电视是家里的电器，在电影院看的是电影，不说“在电影院看电视”。"}, {"text": "妈妈用电视给我发信息。", "explanation": "这里应该用〈手机〉。电视不能用来发信息，发信息要用手机。"}, {"text": "我用电视热饭。", "explanation": "这里应该用〈微波炉〉。电视是看节目的电器，不能用来加热食物，热饭要用微波炉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确答案：电视（diàn shì），指家里用来看节目的电器。"}, {"text": "变式", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 对 d），意思是变化后的形式。"}, {"text": "面世", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 对 d），意思是作品等首次与公众见面。"}, {"text": "现世", "is_correct": false, "explanation": "xiàn 与 diàn 声母不同（x 对 d），意思是现在这个世界。"}], "explanations": {"电视": "正确答案：电视（diàn shì），指家里用来看节目的电器。", "变式": "biàn 与 diàn 声母不同（b 对 d），意思是变化后的形式。", "面世": "miàn 与 diàn 声母不同（m 对 d），意思是作品等首次与公众见面。", "现世": "xiàn 与 diàn 声母不同（x 对 d），意思是现在这个世界。"}, "sentence_index": null, "correct_answer": "电视"}, "level_3": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确：电视是可以“开着”的电器，与“开着……睡觉”相合。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不能“开着”用来睡觉，奶奶也不会在地铁里睡觉。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是家里能开着用的东西，不能“开着工厂睡觉”。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“开”一般不接“报纸”，报纸是用来看的，不说“开报纸”。"}], "explanations": {"电视": "正确：电视是可以“开着”的电器，与“开着……睡觉”相合。", "地铁": "语义：地铁是交通工具，不能“开着”用来睡觉，奶奶也不会在地铁里睡觉。", "工厂": "语义：工厂不是家里能开着用的东西，不能“开着工厂睡觉”。", "报纸": "搭配：“开”一般不接“报纸”，报纸是用来看的，不说“开报纸”。"}, "sentence_index": 6, "correct_answer": "电视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天把牛奶放进电视里。", "explanation": "这里应该用〈冰箱〉。电视是看节目的电器，不能用来放牛奶，放牛奶要用冰箱。"}, {"text": "我每天用电视洗衣服。", "explanation": "这里应该用〈洗衣机〉。电视不能用来洗衣服，洗衣服要用洗衣机。"}, {"text": "他在电视上写作业。", "explanation": "这里应该用〈电脑〉。电视不能用来写作业，写作业要用电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书房里有一只旧电视。", "corrected_sentence": "书房里有一台旧电视。", "error_description": "“电视”的量词应为“台”，不能说“一只电视”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把电视关。", "corrected_sentence": "我把电视关了。", "error_description": "“把”字句中动词后要有补语或“了”等成分表示完成，“关”后应加“了”，说“我把电视关了”，不能说“我把电视关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
