INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24434, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从开始到结束，一直不变。", "primary_collocate": null, "pronunciation": "shǐ zhōng", "ipa": "ʂʅ˨˩˦ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他始终相信自己能成功。", "target_word": "始终", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这几年她始终住在这个小城。", "target_word": "始终", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管天气怎么样，他始终坚持跑步。", "target_word": "始终", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束前，对手始终没有放弃。", "target_word": "始终", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话时，他始终看着黑板。", "target_word": "始终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然工作很忙，妈妈始终对我们很温和。", "target_word": "始终", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从小到大，他的态度始终没有变。", "target_word": "始终", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我找了一个下午，始终没找到那本书。", "target_word": "始终", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议开了三个小时，他始终一句话也没说。", "target_word": "始终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她始终记得老师对她说过的那句话。", "target_word": "始终", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：从头到尾一直不变（多与没、不、相信、坚持等搭配）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24434, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "始终", "is_correct": true, "explanation": "正确答案：shǐ zhōng，表示从开始到结束一直不变。"}, {"text": "时钟", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是时钟。"}, {"text": "示众", "is_correct": false, "explanation": "shì 与 shǐ 声调不同，zhòng 与 zhōng 声调也不同，意思是把人或物展示给众人看。"}, {"text": "试种", "is_correct": false, "explanation": "shì 与 shǐ 声调不同，zhǒng 与 zhōng 声调也不同，意思是小范围试验性地种植。"}], "explanations": {"始终": "正确答案：shǐ zhōng，表示从开始到结束一直不变。", "时钟": "shí（第二声）与 shǐ（第三声）声调不同，意思是时钟。", "示众": "shì 与 shǐ 声调不同，zhòng 与 zhōng 声调也不同，意思是把人或物展示给众人看。", "试种": "shì 与 shǐ 声调不同，zhǒng 与 zhōng 声调也不同，意思是小范围试验性地种植。"}, "sentence_index": null, "correct_answer": "始终"}, "level_3": {"options": [{"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”表示本人动手去做某事，不能修饰“相信”这类心理活动。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指间或发生，与“相信自己能成功”所表达的稳定态度相冲突。"}, {"text": "始终", "is_correct": true, "explanation": "正确：“始终”表示从开始到结束一直不变，与“相信”的稳定态度相合。"}, {"text": "顺便", "is_correct": false, "explanation": "搭配：“顺便”用于附带进行的动作，不能修饰“相信”。"}], "explanations": {"亲自": "搭配：“亲自”表示本人动手去做某事，不能修饰“相信”这类心理活动。", "偶尔": "语义：“偶尔”指间或发生，与“相信自己能成功”所表达的稳定态度相冲突。", "始终": "正确：“始终”表示从开始到结束一直不变，与“相信”的稳定态度相合。", "顺便": "搭配：“顺便”用于附带进行的动作，不能修饰“相信”。"}, "sentence_index": 0, "correct_answer": "始终"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们等了三个小时，始终见到了他。", "explanation": "这里应该用〈终于〉。“始终”强调从头到尾一直不变，不能修饰“见到”这种一次性的结果。"}, {"text": "屋里的灯始终亮了起来。", "explanation": "这里应该用〈突然〉。“始终”强调持续不变，不能描述某个状态忽然开始。"}, {"text": "火车始终要开了。", "explanation": "这里应该用〈马上〉。“始终”表示持续，不能用来说明一件即将发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久前，与“从小到大”的长时段相冲突。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：“亲手”要求本人动手去做，不能用来修饰“没有变”这种状态。"}, {"text": "始终", "is_correct": true, "explanation": "正确：“始终”表示从小到大一直不变，与“从小到大”相合。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指当时当地，与“从小到大”的长时段相冲突。"}], "explanations": {"刚刚": "语义：“刚刚”指不久前，与“从小到大”的长时段相冲突。", "亲手": "搭配：“亲手”要求本人动手去做，不能用来修饰“没有变”这种状态。", "始终": "正确：“始终”表示从小到大一直不变，与“从小到大”相合。", "当场": "语义：“当场”指当时当地，与“从小到大”的长时段相冲突。"}, "sentence_index": 6, "correct_answer": "始终"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天始终吃了一碗面。", "explanation": "这里“始终”表示从头到尾持续不变，误用成了一次性动作的修饰（“昨天吃了一碗面”是一次完成的事）。应去掉“始终”，说“我昨天吃了一碗面”。"}, {"text": "他始终去过日本。", "explanation": "这里应该用〈曾经〉。“始终”强调持续不变，不用于说明过去有过的经历。"}, {"text": "他一下子明白了这个道理，始终明白了它。", "explanation": "这里“始终”强调持续不变，却与“一下子明白”的瞬间发生相冲突。应去掉“始终”，说“他一下子明白了这个道理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他始终了很努力。", "corrected_sentence": "他始终很努力。", "error_description": "错误：“始终”后面不能直接加“了”。应说“他始终很努力。”，“了”表示完成，不能与“始终”连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年她始终了很忙。", "corrected_sentence": "这些年她始终很忙。", "error_description": "错误：“了”插在“始终”和“很”之间。“始终”后应直接接“很”，句中不需要“了”，应说“这些年她始终很忙。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
