INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手做的动作，用来告诉别人事情。", "primary_collocate": null, "pronunciation": "shǒu shì", "ipa": "ʂou˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他做了一个手势，意思是“请安静”。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这个手势是什么意思。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用手势告诉我，别出声。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向我做了一个手势，让我过去。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在很吵的地方，我们用手势说话。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的手势很清楚，大家都看懂了。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手势是说“好”。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学着爸爸的手势，笑了。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会说中文，只好用手势。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看到那个手势，马上停了车。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手勢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手的动作把事情告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c071687f-a94f-4252-83c9-21d4428df7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确答案。手势（shǒushì）指手做的动作，用来告诉别人事情。"}, {"text": "收视", "is_correct": false, "explanation": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。"}, {"text": "首饰", "is_correct": false, "explanation": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。"}, {"text": "收拾", "is_correct": false, "explanation": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。"}, {"text": "收市", "is_correct": false, "explanation": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}], "explanations": {"手势": "正确答案。手势（shǒushì）指手做的动作，用来告诉别人事情。", "收视": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。", "首饰": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。", "收拾": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。", "收市": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}, "sentence_index": null, "correct_answer": "手势"}, "level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势是动作，“做了一个手势”说得通，能表达“请安静”的意思。"}, {"text": "汤", "is_correct": false, "explanation": "语义：“汤”不能表示“请安静”的意思，“做了一个汤”与句义不合。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“做”不能与“名字”搭配，应说“取名字”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，不能表示“请安静”的意思。"}], "explanations": {"手势": "正确：手势是动作，“做了一个手势”说得通，能表达“请安静”的意思。", "汤": "语义：“汤”不能表示“请安静”的意思，“做了一个汤”与句义不合。", "名字": "搭配：“做”不能与“名字”搭配，应说“取名字”。", "蛋糕": "语义：“蛋糕”是食物，不能表示“请安静”的意思。"}, "sentence_index": 0, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他脸上挂着一个手势，很开心。", "explanation": "这里应该用〈笑容〉。笑容可以挂在脸上，“手势”是用手做的动作，不能挂在脸上。"}, {"text": "他推开手势，让我进去。", "explanation": "这里应该用〈门〉。“推开”的对象是门、窗等，手势不能被推开。"}, {"text": "他吹了个手势，叫我过去。", "explanation": "这里应该用〈口哨〉。“吹”的对象是口哨，手势是用手做的动作，不能被吹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势可以表达“好”的意思，“这个手势是说……”说得通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不能表示“好”，句子说不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是视力工具，不能表达意思，“是说‘好’”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不能“说”某个意思。"}], "explanations": {"手势": "正确：手势可以表达“好”的意思，“这个手势是说……”说得通。", "电脑": "语义：“电脑”不能表示“好”，句子说不通。", "眼镜": "语义：“眼镜”是视力工具，不能表达意思，“是说‘好’”不成立。", "身高": "体貌：“身高”指身体的高矮，不能“说”某个意思。"}, "sentence_index": 6, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机按了手势，马上停了车。", "explanation": "这里应该用〈喇叭〉。“按”搭配喇叭、按钮，手势不能被“按”。"}, {"text": "司机转动手势，马上停了车。", "explanation": "这里应该用〈方向盘〉。“转动”的对象是方向盘，手势不能被转动。"}, {"text": "司机看到那个手势亮了，马上停了车。", "explanation": "这里应该用〈灯〉。“亮”的对象是灯，手势是用手做的动作，不能亮起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机做了一根手势，让我们下车。", "corrected_sentence": "司机做了一个手势，让我们下车。", "error_description": "错误：“一根”；正确：“一个”。“根”用于细长的东西，手势用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板的手势把我马上坐下。", "corrected_sentence": "老板的手势让我马上坐下。", "error_description": "句式错误：“把”应为“让”。“坐下”是不及物动词，没有可以被“把”字句处置的对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cf3ab86-253f-4de8-9066-b47ea1169b94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24442, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24442, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同年龄的人之间。", "primary_collocate": null, "pronunciation": "dài jì", "ipa": "taɪ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "代际差异让爷爷不懂年轻人的音乐。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人之间的代际沟通很重要。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动让大家有了更多代际交流。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代际关系好的家庭，大家都很开心。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了代际读书会，老人和孩子一起读书。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代际矛盾常常来自生活习惯的不同。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻里之间的代际互助越来越少了。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代际理解需要老人和年轻人一起努力。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究主题是代际冲突。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区组织了代际活动，让老人教孩子下棋。", "target_word": "代际", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代際", "label": "繁体"}], "register": "书面", "sense_fingerprint": "代际：不同年龄的人之间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699a7efa-2ffe-43e6-84c2-b247b5d73d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代际", "is_correct": true, "explanation": "正确答案：代际（dài jì），指不同年龄的人之间。"}, {"text": "待机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是待机，指设备处于待命状态。"}, {"text": "代价", "is_correct": false, "explanation": "jià 与 jì 韵母不同（多一个 a），意思是代价，指付出的成本。"}, {"text": "淡季", "is_correct": false, "explanation": "dàn 与 dài 韵母不同（-n 与 -i），意思是淡季，指生意清淡的时期。"}, {"text": "带劲", "is_correct": false, "explanation": "jìn 与 jì 韵母不同（多一个 n），意思是带劲，指有劲头、有意思。"}], "explanations": {"代际": "正确答案：代际（dài jì），指不同年龄的人之间。", "待机": "jī（第一声）与 jì（第四声）声调不同，意思是待机，指设备处于待命状态。", "代价": "jià 与 jì 韵母不同（多一个 a），意思是代价，指付出的成本。", "淡季": "dàn 与 dài 韵母不同（-n 与 -i），意思是淡季，指生意清淡的时期。", "带劲": "jìn 与 jì 韵母不同（多一个 n），意思是带劲，指有劲头、有意思。"}, "sentence_index": null, "correct_answer": "代际"}, "level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格差异”说的是价钱，与听不听得懂音乐无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重差异”说的是人的重量，不会让人听不懂音乐。"}, {"text": "代际", "is_correct": true, "explanation": "正确答案：代际，指不同年龄的人之间的差异，这里指爷爷与年轻人的差异。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积差异”多用于物体或空间，不能用来说明人之间的理解差异。"}], "explanations": {"价格": "语义：“价格差异”说的是价钱，与听不听得懂音乐无关。", "体重": "语义：“体重差异”说的是人的重量，不会让人听不懂音乐。", "代际": "正确答案：代际，指不同年龄的人之间的差异，这里指爷爷与年轻人的差异。", "体积": "搭配：“体积差异”多用于物体或空间，不能用来说明人之间的理解差异。"}, "sentence_index": 0, "correct_answer": "代际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷和孙子之间有代际，所以常常说不到一块儿。", "explanation": "这里应该用〈代沟〉。代沟是口语说法，指两代人之间的隔阂，可以说“有代沟”；代际是书面词，指年龄之间的关系，不说“有代际”。"}, {"text": "他和代际的朋友玩得很好。", "explanation": "这里应该用〈同龄〉。同龄指年龄相同，可以修饰“朋友”；代际指年龄之间的关系，不能用来修饰人。"}, {"text": "他们之间没有代际。", "explanation": "这里应该用〈隔阂〉。隔阂指彼此之间的障碍，可以说“没有隔阂”；代际不指障碍，这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血缘", "is_correct": false, "explanation": "语义：邻里之间不是血缘关系，“血缘互助”与句意不合。"}, {"text": "代际", "is_correct": true, "explanation": "正确答案：代际，指不同年龄的人之间，这里指邻里中老人与年轻人之间的互助。"}, {"text": "国际", "is_correct": false, "explanation": "语义：“国际”指不同国家之间，与邻里的范围不合。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“互助”的对象是人或事物，不说“距离互助”。"}], "explanations": {"血缘": "语义：邻里之间不是血缘关系，“血缘互助”与句意不合。", "代际": "正确答案：代际，指不同年龄的人之间，这里指邻里中老人与年轻人之间的互助。", "国际": "语义：“国际”指不同国家之间，与邻里的范围不合。", "距离": "搭配：“互助”的对象是人或事物，不说“距离互助”。"}, "sentence_index": 6, "correct_answer": "代际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在村里，代际高的人受人尊敬。", "explanation": "这里应该用〈辈分〉。辈分指家族中的世代次序，可以说“辈分高”；代际指世代之间的关系，不指人的辈分高低。"}, {"text": "我和堂姐是代际，小时候常一起玩。", "explanation": "这里应该用〈同辈〉。同辈指同一世代的人，可以说“是同辈”；代际指两代之间的关系，不能用来称呼同一代的人。"}, {"text": "他是我们班的代际。", "explanation": "这里应该用〈代表〉。代表指代替集体或他人行事的人，可以说“班级代表”；代际指世代之间的关系，不指人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两代人的代际很大。", "corrected_sentence": "两代人的代际差异很大。", "error_description": "错误在“代际”：说“差距大”时要用“代际差异”，不能单用“代际”，应补上“差异”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人的经验要靠代际地传承下去。", "corrected_sentence": "老人的经验要靠代际传承下去。", "error_description": "错误在“代际”后的“地”：“代际”是名词，不能直接加“地”作状语，应说“代际传承”，不能说“代际地传承”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
