INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人心就是人们心里的想法和感觉。", "primary_collocate": null, "pronunciation": "rén xīn", "ipa": "ʐən˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "人心不同，想法也不一样。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道人心是怎么变化的。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间长了，才能看清人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人心很复杂，不容易看懂。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家常写人心的变化。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，读书可以安定人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱买不到人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间会改变人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，这个人很会了解人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的故事能打动人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人心惶惶", "label": "复合"}, {"form": "人心所向", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们心里的想法和感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae1b019-e3ac-4d0f-b5df-a846d13cad7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人心", "is_correct": true, "explanation": "“人心”指人们心里的想法，与“不同”“想法也不一样”搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨没有想法，“想法也不一样”的主语只能是人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有想法，与句中“想法也不一样”的比较对象不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：眼睛属于外形特征，与“想法”无关，不能作为比较的对象。"}], "explanations": {"人心": "“人心”指人们心里的想法，与“不同”“想法也不一样”搭配。", "雨": "语义：雨没有想法，“想法也不一样”的主语只能是人。", "石头": "语义：石头没有想法，与句中“想法也不一样”的比较对象不符。", "眼睛": "体貌：眼睛属于外形特征，与“想法”无关，不能作为比较的对象。"}, "sentence_index": 0, "correct_answer": "人心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "广场上的人心很多，非常热闹。", "explanation": "这里应该用〈人群〉。人心指人们心里的想法，是抽象的，不能说“多”；聚集的人要用人群。"}, {"text": "他对小狗的人心很深。", "explanation": "这里应该用〈感情〉。人心指人们普遍的想法和感觉，不用于说对小狗的感情。"}, {"text": "我们要处理好人心关系。", "explanation": "这里应该用〈人际〉。人际指人与人之间的交往，人心指想法和感觉，不说“人心关系”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人心", "is_correct": true, "explanation": "“人心”是人们的想法和感觉，不能用钱买。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米可以用钱买，与“钱买不到”矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑可以用钱买，与“钱买不到”矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车可以用钱买，与“钱买不到”矛盾。"}], "explanations": {"人心": "“人心”是人们的想法和感觉，不能用钱买。", "大米": "语义：大米可以用钱买，与“钱买不到”矛盾。", "电脑": "语义：电脑可以用钱买，与“钱买不到”矛盾。", "汽车": "语义：汽车可以用钱买，与“钱买不到”矛盾。"}, "sentence_index": 6, "correct_answer": "人心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天喝人心。", "explanation": "这里应该用〈咖啡〉。〈喝〉搭配饮料，人心不能喝。"}, {"text": "他出门前戴上了人心。", "explanation": "这里应该用〈帽子〉。〈戴〉搭配帽子、眼镜等，人心不能戴。"}, {"text": "他在花园里摘人心。", "explanation": "这里应该用〈花〉。〈摘〉搭配花、果实等，人心不能摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事之后，一个人心变得很复杂。", "corrected_sentence": "这件事之后，人心变得很复杂。", "error_description": "量词错误：“人心”是抽象概念，不能用个体量词“个”计数，应直接说“人心变得很复杂”，去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事让人心们沮丧起来了。", "corrected_sentence": "这件事让人心沮丧起来了。", "error_description": "“人心”是抽象的集合概念，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
