INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24450, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用笔在纸上写字。", "primary_collocate": null, "pronunciation": "shū xiě", "ipa": "ʂu⁵⁵ ɕjɛ²¹⁴", "syllable_count": 2, "sentences": [{"text": "小明坐在桌前，认真书写日记。", "target_word": "书写", "complexity_tier": "T3", "furigana": "xiǎo míng zuò zài zhuō qián, rènzhēn shūxiě rìjì。", "sentence_source": "generated"}, {"text": "她书写得很慢，但是很认真。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在白纸上书写。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔书写很流畅。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷戴着眼镜书写信件。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，请用蓝笔书写答案。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们正在练习书写汉字。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左手书写对他来说有点难。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他握着笔，慢慢书写自己的名字。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子太矮，不方便书写。", "target_word": "书写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "书写了", "label": "体标（了）"}, {"form": "书写过", "label": "体标（过）"}, {"form": "书写工具", "label": "复合"}, {"form": "書寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用笔在纸上写字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76ee065-26df-4d6a-b94a-ac532d78a03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书写", "is_correct": true, "explanation": "书写指用笔写字，小明坐在桌前写日记，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“日记”搭配，不能说吃日记。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、场地，不能与“日记”搭配。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚攻击，与“坐在桌前”的动作不合。"}], "explanations": {"书写": "书写指用笔写字，小明坐在桌前写日记，与句意相符。", "吃": "搭配：“吃”不能与“日记”搭配，不能说吃日记。", "打扫": "搭配：“打扫”用于房间、场地，不能与“日记”搭配。", "踢": "语义：“踢”是用脚攻击，与“坐在桌前”的动作不合。"}, "sentence_index": 0, "correct_answer": "书写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用锅子书写了一锅汤。", "explanation": "这里应该用〈煮〉。书写是用笔写字，做汤要用“煮”，不能用“书写”。"}, {"text": "孩子用蜡笔书写了一只小猫。", "explanation": "这里应该用〈画〉。书写是用笔写字，画小猫要用“画”。"}, {"text": "妈妈用针线书写了一朵花。", "explanation": "这里应该用〈绣〉。书写是用笔写字，用针线做花要用“绣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书写", "is_correct": true, "explanation": "书写指用笔写字，同学们练习的是写汉字，与句意相符。"}, {"text": "演", "is_correct": false, "explanation": "语义：“演”指表演，不是练习汉字的动作，与“练习”的内容不符。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”用于物体，不能用来指汉字。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是使物体掉落，与“练习汉字”的意思不符。"}], "explanations": {"书写": "书写指用笔写字，同学们练习的是写汉字，与句意相符。", "演": "语义：“演”指表演，不是练习汉字的动作，与“练习”的内容不符。", "清洗": "搭配：“清洗”用于物体，不能用来指汉字。", "摔": "语义：“摔”是使物体掉落，与“练习汉字”的意思不符。"}, "sentence_index": 6, "correct_answer": "书写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用抹布书写了黑板。", "explanation": "这里应该用〈擦〉。书写是用笔写字，擦黑板要用“擦”。"}, {"text": "妈妈用水书写了一件衣服。", "explanation": "这里应该用〈洗〉。书写是用笔写字，洗衣服要用“洗”。"}, {"text": "工人用油漆书写了一面墙。", "explanation": "这里应该用〈刷〉。书写是用笔写字，用油漆涂墙要用“刷”，不能用“书写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钢笔书写信件。", "corrected_sentence": "他用钢笔书写信件。", "error_description": "介词错误：表示工具的“用钢笔”应使用介词“用”，不能用“把”。应说“他用钢笔书写信件”，不能说“他把钢笔书写信件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我书写地很快。", "corrected_sentence": "我书写得很快。", "error_description": "补语标记错误：说明“书写”的程度要用“得”，不能用“地”。应说“书写得很快”，不能说“书写地很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
