INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24458, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话时声音的高低变化，就像唱歌一样。", "primary_collocate": null, "pronunciation": "yǔ diào", "ipa": "y²¹⁴ tjɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "她说话的语调高高低低，像唱歌一样。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩说话的语调像唱歌一样好听。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的语调一会儿高，一会儿低。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说中文时，语调要有高有低。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广东朋友说普通话，语调有点不一样。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈讲故事的语调很好听。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了一种语调，又说了一遍。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读这句话时，语调起伏很明显。", "target_word": "语调", "complexity_tier": "T3", "furigana": "tā dú zhè jù huà shí, yǔdiào qǐfú hěn míngxiǎn.", "sentence_source": "generated"}, {"text": "他念这首诗时，语调有高有低，很有节奏。", "target_word": "语调", "complexity_tier": "T3", "furigana": "tā niàn zhè shǒu shī shí, yǔdiào yǒu gāo yǒu dī, hěn yǒu jiézòu.", "sentence_source": "generated"}, {"text": "这位歌手说话的语调也像在唱歌。", "target_word": "语调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語調", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说话时声音的高低变化，像唱歌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语调", "is_correct": true, "explanation": "正确。“高高低低”描写的是说话时声音的高低变化，即语调。"}, {"text": "语速", "is_correct": false, "explanation": "搭配：语速指说话的快慢，“高高低低”描写的是音高，不能用于语速。"}, {"text": "口音", "is_correct": false, "explanation": "语义：口音指地方发音的特点，与声音的高低起伏无关。"}, {"text": "音色", "is_correct": false, "explanation": "语义：音色指声音的质地，不是高低起伏的变化。"}], "explanations": {"语调": "正确。“高高低低”描写的是说话时声音的高低变化，即语调。", "语速": "搭配：语速指说话的快慢，“高高低低”描写的是音高，不能用于语速。", "口音": "语义：口音指地方发音的特点，与声音的高低起伏无关。", "音色": "语义：音色指声音的质地，不是高低起伏的变化。"}, "sentence_index": 0, "correct_answer": "语调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天背诵很多语调，背得很快。", "explanation": "这里应该用〈词语〉。语调指说话时声音的高低变化，不是可以背诵的词。"}, {"text": "这辆自行车的语调很高。", "explanation": "这里误把〈语调〉当成了〈响亮〉。语调只指说话时声音的高低变化，自行车不会说话，形容车声应说〈响亮〉。"}, {"text": "他做饭的语调很温柔。", "explanation": "这里误把〈语调〉当成了〈手法〉。语调只指说话时声音的变化，做饭应说〈手法〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语调", "is_correct": true, "explanation": "正确。“换了一种语调，又说了一遍”指换一种声音的高低变化再说一次。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是书写的形式，说话时没有字体，不能用“说”来搭配。"}, {"text": "服装", "is_correct": false, "explanation": "语义：服装是穿着，与“又说了一遍”的言语行为无关。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高指人的高矮，不能“换了一种”，与句意不合。"}], "explanations": {"语调": "正确。“换了一种语调，又说了一遍”指换一种声音的高低变化再说一次。", "字体": "语义：字体是书写的形式，说话时没有字体，不能用“说”来搭配。", "服装": "语义：服装是穿着，与“又说了一遍”的言语行为无关。", "身高": "搭配：身高指人的高矮，不能“换了一种”，与句意不合。"}, "sentence_index": 6, "correct_answer": "语调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手有一朵好语调，唱歌很有感情。", "explanation": "这里应该用〈一种〉。语调用“种”计量，“朵”只用于花等物，不能修饰语调。"}, {"text": "他一句话也没说，语调却很高。", "explanation": "这里误把〈语调〉当成了〈神情〉。语调只指说话时声音的高低变化，没有说话就无从谈起。"}, {"text": "这个包的语调很漂亮。", "explanation": "语调只用于说话时的声音，包没有语调，这里应说〈款式〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈讲故事时用温柔地语调，孩子们都爱听。", "corrected_sentence": "妈妈讲故事时用温柔的语调，孩子们都爱听。", "error_description": "“地”用错。形容词“温柔”修饰名词“语调”时应用“的”，“地”只用于修饰动词，应说“温柔的语调”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说话时一把语调很高，像在唱歌。", "corrected_sentence": "他说话时的语调很高，像在唱歌。", "error_description": "量词错误。“把”用于有柄的物体，不能修饰语调，应说“他说话时的语调”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24460, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24460, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指年纪比较大、经历比较多的人。", "primary_collocate": null, "pronunciation": "zhǎng zhě", "ipa": "ʈʂɑŋ˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位长者年轻时去过很多国家。", "target_word": "长者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长者慢慢走进了茶馆。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有一位长者走过来，问我要去哪里。", "target_word": "长者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经历很多事，是一位让人放心的长者。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长者看着孩子们玩，脸上带着笑。", "target_word": "长者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位长者给我们讲了以前的生活。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区为长者办了一个免费的体检活动。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我扶着长者过马路。", "target_word": "长者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位长者在树下下棋。", "target_word": "长者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位长者的话让我想了很久。", "target_word": "长者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位长者", "label": "量词"}], "register": "书面", "sense_fingerprint": "指年纪较大、经历较多的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0954f54d-1810-47dd-bdb8-2c3f2e9c6892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长者", "is_correct": true, "explanation": "「长者」指年纪大、经历多的人，与“年轻时去过很多国家”的经历相合。"}, {"text": "石头", "is_correct": false, "explanation": "配价：「去过」要求有生命的主语，石头不能去过国家。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不可能“年轻时去过很多国家”。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩尚未成长，与“年轻时去过很多国家”的经历相矛盾。"}], "explanations": {"长者": "「长者」指年纪大、经历多的人，与“年轻时去过很多国家”的经历相合。", "石头": "配价：「去过」要求有生命的主语，石头不能去过国家。", "桌子": "语义：桌子不是人，不可能“年轻时去过很多国家”。", "小孩": "语义：小孩尚未成长，与“年轻时去过很多国家”的经历相矛盾。"}, "sentence_index": 0, "correct_answer": "长者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚毕业，却已经是一位让人放心的长者。", "explanation": "这里应该用〈年轻人〉。长者指年纪大、经历多的人，不能指刚毕业的人。"}, {"text": "这位刚出生的婴儿，是一位让人放心的长者。", "explanation": "这里应该用〈年幼的孩子〉。长者指年纪大、经历多的人，不能指刚出生的婴儿。"}, {"text": "我们班的同学都是长者，年龄差不多。", "explanation": "这里误用〈长者〉。长者指年纪大、经历多的人，与“年龄差不多”的同龄人情况不符，应说「同龄人」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长者", "is_correct": true, "explanation": "「长者」指年长、有经验的人，与“为长者办体检活动”的对象相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有身体，不能接受“体检”，“为石头办体检活动”句意不通。"}, {"text": "废纸", "is_correct": false, "explanation": "语义：废纸不能接受“体检”，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能接受“体检”，句意不通。"}], "explanations": {"长者": "「长者」指年长、有经验的人，与“为长者办体检活动”的对象相合。", "石头": "语义：石头没有身体，不能接受“体检”，“为石头办体检活动”句意不通。", "废纸": "语义：废纸不能接受“体检”，句意不通。", "垃圾": "语义：垃圾不能接受“体检”，句意不通。"}, "sentence_index": 6, "correct_answer": "长者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本旧书是一位长者，记录了很多往事。", "explanation": "这里应该用〈典籍〉，量词也要改为「部」。长者只指人，不能用于书籍。"}, {"text": "我们公司的新员工都是长者。", "explanation": "这里误用〈长者〉。长者指年纪大、经历多的人，与“新员工”经历少的情况矛盾，应说「资历较浅的人」。"}, {"text": "他今年只有十岁，却已是我们村的长者。", "explanation": "这里应该用〈小孩子〉。长者指年纪大、经历多的人，与“十岁”的年龄不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位长者们在河边钓鱼，很有耐心。", "corrected_sentence": "一位长者在河边钓鱼，很有耐心。", "error_description": "〈一位〉已表示数量，不能再加〈们〉，应说「一位长者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位长者话让我感动了很久。", "corrected_sentence": "那位长者的话让我感动了很久。", "error_description": "〈长者〉修饰“话”时要用「的」连接，应说「那位长者的话」，不能省略「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
