INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24462, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说话或读书时，声音有高有低，有停有接，很好听。", "primary_collocate": null, "pronunciation": "yì yáng dùn cuò", "ipa": "i⁵¹ jaŋ³⁵ tuən⁵¹ tsʰuo⁵¹", "syllable_count": 4, "sentences": [{"text": "她读课文读得抑扬顿挫，很好听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的发言抑扬顿挫，大家都爱听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明背古诗背得抑扬顿挫。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，读诗要抑扬顿挫。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话抑扬顿挫，像在唱歌。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里的声音抑扬顿挫，真好听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我读故事，声音抑扬顿挫。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老先生念诗抑扬顿挫，我很喜欢听。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这段话读得抑扬顿挫，同学们都鼓掌了。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台主持人说话抑扬顿挫，听着很舒服。", "target_word": "抑扬顿挫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话读书时声音有高低停接而好听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑扬顿挫", "is_correct": true, "explanation": "正确。读课文时声音有高低、有停接，与“很好听”的评价相合。"}, {"text": "单调", "is_correct": false, "explanation": "语义：单调指没有变化，与“很好听”的评价矛盾。"}, {"text": "刺耳", "is_correct": false, "explanation": "搭配：刺耳修饰尖利的噪音，用来评价朗读搭配偏弱，且与“很好听”相反。"}, {"text": "含糊", "is_correct": false, "explanation": "语义：含糊指发音不清，与“很好听”的评价矛盾。"}], "explanations": {"抑扬顿挫": "正确。读课文时声音有高低、有停接，与“很好听”的评价相合。", "单调": "语义：单调指没有变化，与“很好听”的评价矛盾。", "刺耳": "搭配：刺耳修饰尖利的噪音，用来评价朗读搭配偏弱，且与“很好听”相反。", "含糊": "语义：含糊指发音不清，与“很好听”的评价矛盾。"}, "sentence_index": 0, "correct_answer": "抑扬顿挫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的颜色抑扬顿挫，层次很分明。", "explanation": "这里误把〈抑扬顿挫〉当成了〈浓淡〉。该词只形容声音的高低起伏，不能用来形容颜色。"}, {"text": "他看书时一言不发，却读得抑扬顿挫。", "explanation": "这里前后矛盾：“看书时一言不发”指无声阅读，而抑扬顿挫只指有声朗读时的声音起伏。"}, {"text": "他的心情抑扬顿挫，一会儿高一会儿低。", "explanation": "这里应该用〈起伏不定〉。抑扬顿挫指声音，不能用来形容心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑扬顿挫", "is_correct": true, "explanation": "正确。奶奶读故事时声音有起伏，与温和的讲故事语境相合。"}, {"text": "冷冰冰", "is_correct": false, "explanation": "语义：冷冰冰形容冷淡、没有温度，与“奶奶给我读故事”的温暖语境不合。"}, {"text": "生硬", "is_correct": false, "explanation": "搭配：生硬多形容言语或动作，修饰读故事的声音搭配偏弱，且与温和的语境不合。"}, {"text": "尖厉", "is_correct": false, "explanation": "搭配：尖厉多修饰叫声或哨声，用来形容讲故事的声音搭配不当。"}], "explanations": {"抑扬顿挫": "正确。奶奶读故事时声音有起伏，与温和的讲故事语境相合。", "冷冰冰": "语义：冷冰冰形容冷淡、没有温度，与“奶奶给我读故事”的温暖语境不合。", "生硬": "搭配：生硬多形容言语或动作，修饰读故事的声音搭配偏弱，且与温和的语境不合。", "尖厉": "搭配：尖厉多修饰叫声或哨声，用来形容讲故事的声音搭配不当。"}, "sentence_index": 6, "correct_answer": "抑扬顿挫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话声音太小，几乎听不见，却说得抑扬顿挫。", "explanation": "这里前后矛盾：声音太小、几乎听不见，就谈不上声音的高低起伏和停接。"}, {"text": "这道菜的味道抑扬顿挫，咸淡很合适。", "explanation": "抑扬顿挫只形容声音，不能形容味道，应说〈适中〉。"}, {"text": "他咬字含糊，话却说得抑扬顿挫。", "explanation": "这里前后矛盾：咬字含糊时字音不清，就谈不上声音的高低起伏和停接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师用抑扬顿挫地语气讲解，学生们都爱听。", "corrected_sentence": "老师用抑扬顿挫的语气讲解，学生们都爱听。", "error_description": "“地”应改为“的”。抑扬顿挫修饰名词“语气”，定语后用“的”；“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他读抑扬顿挫，很好听。", "corrected_sentence": "他读得抑扬顿挫，很好听。", "error_description": "补语标记“得”缺失。应为“读得抑扬顿挫”，“得”引出补语，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24464, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散与凝聚（聚成一团）意思相反，二者互为反义词。"}, {"text": "研究", "is_correct": false, "explanation": "研究是深入探讨，与凝聚没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察是仔细看、察看，与凝聚没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是把东西从一处运到另一处，与凝聚没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散与凝聚（聚成一团）意思相反，二者互为反义词。", "研究": "研究是深入探讨，与凝聚没有反义关系。", "观察": "观察是仔细看、察看，与凝聚没有反义关系。", "搬运": "搬运是把东西从一处运到另一处，与凝聚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24464, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散与凝聚（聚成一团）意思相反，是《反义词词典》中所列的反义词。"}, {"text": "解释", "is_correct": false, "explanation": "解释是说明道理或含义，与凝聚没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理是使损坏的东西恢复原状，与凝聚没有反义关系。"}, {"text": "安排", "is_correct": false, "explanation": "安排是处理、布置事情，与凝聚没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散与凝聚（聚成一团）意思相反，是《反义词词典》中所列的反义词。", "解释": "解释是说明道理或含义，与凝聚没有反义关系。", "修理": "修理是使损坏的东西恢复原状，与凝聚没有反义关系。", "安排": "安排是处理、布置事情，与凝聚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24464, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西聚在一起变成一团。", "primary_collocate": null, "pronunciation": "níng jù", "ipa": "niŋ˧˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "水银滴落在地上，会凝聚成许多小珠子。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "煮好的汤冷了以后，油脂会慢慢凝聚成块。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "细小的尘埃在空中慢慢凝聚成团。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "胶体溶液放置一段时间后，微粒会凝聚成大块。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "沙子被雨水打湿后，会凝聚成一块一块的。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "熔化的蜡油滴落后，很快就凝聚成一粒粒小蜡珠。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "油漆里的颜料颗粒会凝聚成块，所以要充分搅拌。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "散落的铁屑被磁铁吸引后，会凝聚在一起。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "杯底的沉淀物时间一长，就会凝聚成一层硬块。", "target_word": "凝聚", "complexity_tier": "T3", "furigana": "níng jù", "sentence_source": "generated"}, {"text": "这些小冰晶凝聚在一起，变成了雪花。", "target_word": "凝聚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝聚了", "label": "体标"}, {"form": "凝聚着", "label": "体标"}, {"form": "凝聚成", "label": "复合"}], "register": "中性", "sense_fingerprint": "水汽、气体等具体的东西聚集成团或成滴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24464, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凝聚", "is_correct": true, "explanation": "凝聚（níng jù）是本题目标词，指东西聚在一起变成一团。"}, {"text": "名句", "is_correct": false, "explanation": "名句（míng jù）与凝聚（níng jù）的声母不同：m 与 n，意思是有名的句子。"}, {"text": "凝住", "is_correct": false, "explanation": "凝住（níng zhù）与凝聚（níng jù）后一音节声母不同：zh 与 j，意思是停住不动、凝视。"}, {"text": "凭据", "is_correct": false, "explanation": "凭据（píng jù）与凝聚（níng jù）的声母不同：p 与 n，意思是作为依据的证据。"}], "explanations": {"凝聚": "凝聚（níng jù）是本题目标词，指东西聚在一起变成一团。", "名句": "名句（míng jù）与凝聚（níng jù）的声母不同：m 与 n，意思是有名的句子。", "凝住": "凝住（níng zhù）与凝聚（níng jù）后一音节声母不同：zh 与 j，意思是停住不动、凝视。", "凭据": "凭据（píng jù）与凝聚（níng jù）的声母不同：p 与 n，意思是作为依据的证据。"}, "sentence_index": null, "correct_answer": "凝聚"}, "level_3": {"options": [{"text": "凝聚", "is_correct": true, "explanation": "凝聚指水银等物质聚成团，与「会凝聚成许多小珠子」的语境吻合，是本句的正确答案。"}, {"text": "扩散", "is_correct": false, "explanation": "语义：扩散指向四周散开，与「聚成小珠子」的结果相反。"}, {"text": "蒸发", "is_correct": false, "explanation": "语义：蒸发指液体变为气体，不会形成「小珠子」。"}, {"text": "溶解", "is_correct": false, "explanation": "语义：溶解指物质在液体中化开、消失，与「聚成许多小珠子」的结果相反。"}], "explanations": {"凝聚": "凝聚指水银等物质聚成团，与「会凝聚成许多小珠子」的语境吻合，是本句的正确答案。", "扩散": "语义：扩散指向四周散开，与「聚成小珠子」的结果相反。", "蒸发": "语义：蒸发指液体变为气体，不会形成「小珠子」。", "溶解": "语义：溶解指物质在液体中化开、消失，与「聚成许多小珠子」的结果相反。"}, "sentence_index": 0, "correct_answer": "凝聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "灰尘在桌上凝聚了一层。", "explanation": "这里应该用〈堆积〉。灰尘是逐渐落下来堆在一起，凝聚指微粒因凝结而聚成一团，不用于灰尘落在桌上。"}, {"text": "他把木板凝聚成了一个箱子。", "explanation": "这里应该用〈拼〉。拼是把木板组装成器物，凝聚指东西聚在一起变成一团，不能用来组成箱子。"}, {"text": "两条河在这里凝聚。", "explanation": "这里应该用〈汇合〉。河流是汇合，不是凝聚；凝聚指物质凝结成团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凝聚", "is_correct": true, "explanation": "凝聚指颜料颗粒聚成块，与「油漆里的颜料颗粒会……成块」的语境吻合，是本句的正确答案。"}, {"text": "挥发", "is_correct": false, "explanation": "语义：挥发指液体变成气体散发掉，与「成块」的结果相反。"}, {"text": "消融", "is_correct": false, "explanation": "语义：消融指逐渐融化或消失，不会形成「成块」的结果。"}, {"text": "粉碎", "is_correct": false, "explanation": "配价：粉碎是把东西弄成碎片，「粉碎成块」的结构与其用法不符。"}], "explanations": {"凝聚": "凝聚指颜料颗粒聚成块，与「油漆里的颜料颗粒会……成块」的语境吻合，是本句的正确答案。", "挥发": "语义：挥发指液体变成气体散发掉，与「成块」的结果相反。", "消融": "语义：消融指逐渐融化或消失，不会形成「成块」的结果。", "粉碎": "配价：粉碎是把东西弄成碎片，「粉碎成块」的结构与其用法不符。"}, "sentence_index": 6, "correct_answer": "凝聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰块在阳光下慢慢凝聚成水。", "explanation": "这里应该用〈融化〉。融化指固体变成液体，凝聚指微粒聚成团，与此语境的结果相反。"}, {"text": "花瓣在风中四处凝聚。", "explanation": "这里应该用〈飘散〉。飘散是随风向四处散开，凝聚指东西聚在一起变成一团，两者方向相反，不能用于花瓣四散。"}, {"text": "墨水在水里慢慢凝聚开来。", "explanation": "这里应该用〈散开〉。墨水是向四周散开，凝聚指聚成团，不能用于墨水扩散的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "露水在叶子上慢慢凝聚了成一颗颗水珠。", "corrected_sentence": "露水在叶子上慢慢凝聚成了一颗颗水珠。", "error_description": "「了」位置错误：「了」应紧跟「凝聚成」，说「凝聚成了一颗颗水珠」，不能说「凝聚了成」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "细小的雨滴在半空中凝聚成一起。", "corrected_sentence": "细小的雨滴在半空中凝聚在一起。", "error_description": "补语错误：「凝聚」后接「在一起」，「成」要接名词或结果（如「凝聚成一团」），不能说「凝聚成一起」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
