INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24466, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事说给别人听。", "primary_collocate": null, "pronunciation": "jiǎng shù", "ipa": "tɕjɑŋ²¹⁴ ʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "他开始向大家讲述自己的旅行。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷坐在床边，向孩子讲述他小时候的事。", "target_word": "讲述", "complexity_tier": "T3", "furigana": "yé ye zuò zài chuáng biān, xiàng hái zi jiǎng shù tā xiǎo shí hou de shì.", "sentence_source": "generated"}, {"text": "她讲述得很清楚，大家都听明白了。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把今天的事讲述一遍。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们听他讲述在国外的生活。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢地讲述着过去的事。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲述自己的梦想时，眼睛很亮。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子认真地向妈妈讲述学校里的事。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听你讲述那次考试的经过。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用简单的话讲述了这个故事。", "target_word": "讲述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "講述", "label": "繁体"}, {"form": "讲述了", "label": "体标"}, {"form": "讲述着", "label": "体标"}, {"form": "讲述过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把一件事说给别人听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲述", "is_correct": true, "explanation": "讲述：把自己的旅行说给大家听，与句中“向大家”相合。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”是整理，不表示把旅行说出来。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于旅行。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等，不能说洗自己的旅行。"}], "explanations": {"讲述": "讲述：把自己的旅行说给大家听，与句中“向大家”相合。", "收拾": "语义：“收拾”是整理，不表示把旅行说出来。", "煮": "搭配：“煮”的对象是食物，不能用于旅行。", "洗": "搭配：“洗”的对象是衣物等，不能说洗自己的旅行。"}, "sentence_index": 0, "correct_answer": "讲述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈认真地讲述了这碗汤。", "explanation": "这里应该用〈煮〉。讲述是用语言说出来，做汤要用煮。"}, {"text": "她在台上讲述了一支舞。", "explanation": "这里应该用〈跳〉。讲述是用语言说出来，表演舞蹈要用跳。"}, {"text": "我讲述了一下总价。", "explanation": "这里应该用〈说〉。讲述是把事情的经过或道理完整说出来，报出总价只是说一下数字，要用说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲述", "is_correct": true, "explanation": "讲述：说出自己的梦想，与“眼睛很亮”的积极状态相合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“眼睛很亮”的情态不合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、器物，不能修理梦想。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能说吃自己的梦想。"}], "explanations": {"讲述": "讲述：说出自己的梦想，与“眼睛很亮”的积极状态相合。", "扔": "语义：“扔”表示丢弃，与“眼睛很亮”的情态不合。", "修理": "搭配：“修理”用于机器、器物，不能修理梦想。", "吃": "搭配：“吃”用于食物，不能说吃自己的梦想。"}, "sentence_index": 6, "correct_answer": "讲述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他讲述了这块木头。", "explanation": "这里应该用〈雕〉。讲述是用语言说出事情，雕刻木头要用雕。"}, {"text": "他讲述好了那台收音机。", "explanation": "这里应该用〈修〉。讲述不能用于修理机器。"}, {"text": "妈妈讲述了客厅。", "explanation": "这里应该用〈装饰〉。讲述只用于说出事情或道理，不能用于布置房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在讲述了自己的经历。", "corrected_sentence": "他正在讲述自己的经历。", "error_description": "“正在”表示动作进行，不能与“了”同用。应去掉“了”，说“正在讲述自己的经历”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把这件事讲述得一遍。", "corrected_sentence": "请你把这件事讲述一遍。", "error_description": "“得”要接状态补语，不能直接接在动词后再接“一遍”。动量词组“一遍”应直接放在动词后，应说“请你把这件事讲述一遍”，去掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
