INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西不会随便改变的样子。", "primary_collocate": null, "pronunciation": "gù dìng xìng", "ipa": "ku˥˩ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这个规定有固定性，不能随便改。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢诗的固定性，每句字数一样。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的菜单没有固定性，每天都不同。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的作息缺少固定性，所以总是很累。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "词语的搭配有一定的固定性。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作没有固定性，常常换地方。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的规则很有固定性，大家都记住了。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人喜欢生活有固定性，不爱常常改变。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成语的固定性很强，不能随便换字。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习时间要有固定性，才容易养成习惯。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "东西不随便改变、有固定样子的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0954f54d-1810-47dd-bdb8-2c3f2e9c6892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固定性", "is_correct": true, "explanation": "正确：“固定性”指东西不随便改变，与“不能随便改”一致。"}, {"text": "灵活性", "is_correct": false, "explanation": "语义：“灵活性”指可以变通，与“不能随便改”相矛盾。"}, {"text": "可变性", "is_correct": false, "explanation": "语义：“可变性”指容易改变，与“不能随便改”相矛盾。"}, {"text": "节奏性", "is_correct": false, "explanation": "搭配：“节奏性”多用于音乐、动作，规定一般不说“有节奏性”。"}], "explanations": {"固定性": "正确：“固定性”指东西不随便改变，与“不能随便改”一致。", "灵活性": "语义：“灵活性”指可以变通，与“不能随便改”相矛盾。", "可变性": "语义：“可变性”指容易改变，与“不能随便改”相矛盾。", "节奏性": "搭配：“节奏性”多用于音乐、动作，规定一般不说“有节奏性”。"}, "sentence_index": 0, "correct_answer": "固定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同的固定性很强，双方随时都可以修改条款。", "explanation": "这里应该用〈灵活性〉。“固定性”指东西不随便改变，与“随时都可以修改条款”相矛盾。"}, {"text": "这条裤子的固定性很好，穿起来很舒服。", "explanation": "这里应该用〈弹性〉。“固定性”指不随便变化，不用来说衣物的伸缩；“穿起来舒服”要用“弹性”。"}, {"text": "他的情绪固定性很强，一会儿高兴一会儿生气。", "explanation": "这里误用〈固定性〉。情绪的“稳定”应说「稳定性」，且“固定性”指东西不随便改变，与“一会儿高兴一会儿生气”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固定性", "is_correct": true, "explanation": "正确：规则不变，大家才能记住，与“固定性”的意思相符。"}, {"text": "模糊性", "is_correct": false, "explanation": "语义：规则一旦“模糊”就难以记住，与“大家都记住了”矛盾。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：规则“随机”就无法被记住，与后半句矛盾。"}, {"text": "文学性", "is_correct": false, "explanation": "搭配：“文学性”指文学作品的特点，游戏规则一般不说“有文学性”。"}], "explanations": {"固定性": "正确：规则不变，大家才能记住，与“固定性”的意思相符。", "模糊性": "语义：规则一旦“模糊”就难以记住，与“大家都记住了”矛盾。", "随机性": "语义：规则“随机”就无法被记住，与后半句矛盾。", "文学性": "搭配：“文学性”指文学作品的特点，游戏规则一般不说“有文学性”。"}, "sentence_index": 6, "correct_answer": "固定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种材料的固定性很好，用几天就变了形。", "explanation": "这里误用〈固定性〉。“固定性”指东西不随便改变，与“用几天就变了形”相矛盾；说材料经久耐用应用「耐久性」。"}, {"text": "这把尺子的固定性很高，每次量出来的长度都不一样。", "explanation": "这里误用〈固定性〉。“固定性”指东西不随便改变，与“每次量出来的长度都不一样”相矛盾；测量的准确应说「精确性」。"}, {"text": "这篇文章的固定性很强，读起来很顺。", "explanation": "这里应该用〈可读性〉。“固定性”指东西不随便改变，说文章好读要用“可读性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划地固定性很强，很难临时改动。", "corrected_sentence": "这个计划的固定性很强，很难临时改动。", "error_description": "错误形式：“地”；正确形式：“的”。〈固定性〉前的定语“这个计划”要用〈的〉连接，〈地〉用于修饰动词或形容词，应说「这个计划的固定性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套规则有一块很强的固定性，大家都记住了。", "corrected_sentence": "这套规则有一种很强的固定性，大家都记住了。", "error_description": "量词错误：“固定性”是抽象名词，量词应用“种”，“块”用于成块的东西。正确形式是“一种很强的固定性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3c7aff5-7054-4b0f-8776-0e760e9f6440') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明显", "is_correct": true, "explanation": "反义：“明显”指容易看出，与“微妙”的细小不易察觉相对。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：形容质地，与差别的大小无关。"}, {"text": "漫长", "is_correct": false, "explanation": "无关：形容时间长，与此义无关。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：形容场面喧闹，与此义无关。"}], "correct_answer": "明显", "explanations": {"明显": "反义：“明显”指容易看出，与“微妙”的细小不易察觉相对。", "柔软": "无关：形容质地，与差别的大小无关。", "漫长": "无关：形容时间长，与此义无关。", "热闹": "无关：形容场面喧闹，与此义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "显眼", "is_correct": true, "explanation": "反义：“显眼”指容易被看见，与“微妙”的不易察觉相对。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：形容温度低，与此义无关。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：形容地势，与此义无关。"}, {"text": "年轻", "is_correct": false, "explanation": "无关：形容年龄小，与变化的细小程度无关。"}], "correct_answer": "显眼", "explanations": {"显眼": "反义：“显眼”指容易被看见，与“微妙”的不易察觉相对。", "寒冷": "无关：形容温度低，与此义无关。", "陡峭": "无关：形容地势，与此义无关。", "年轻": "无关：形容年龄小，与变化的细小程度无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很小很小，不容易看出来。", "primary_collocate": null, "pronunciation": "wēi miào", "ipa": "weɪ˥ miɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这两种颜色只有微妙的差别。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两首歌的节奏有微妙的区别。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张照片的差别很微妙，我看不出来。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气有了微妙的变化。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的意思差别很微妙。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音里有微妙的不同。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光变化得很微妙，没人注意到。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个差别太微妙了，大家都没发现。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，空气里有一种微妙的变化。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路的样子有些微妙的变化，只有妈妈看出来了。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微妙地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "差别、变化极小而不易察觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "正确：“微妙”指差别很小、不易察觉，符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "语义：热情形容人的态度，不能修饰颜色的差别。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆多形容声音，不说颜色有清脆的差别。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：辽阔形容空间范围，不能修饰差别。"}], "explanations": {"微妙": "正确：“微妙”指差别很小、不易察觉，符合句意。", "热情": "语义：热情形容人的态度，不能修饰颜色的差别。", "清脆": "搭配：清脆多形容声音，不说颜色有清脆的差别。", "辽阔": "搭配：辽阔形容空间范围，不能修饰差别。"}, "sentence_index": 0, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只受了微妙的伤，很快就好了。", "explanation": "这里应该用〈轻微〉。微妙指差别或变化细小、不易察觉，不用来说伤势。"}, {"text": "这座山很微妙，又高又大。", "explanation": "这里应该用〈巨大〉。微妙指很小、不易察觉，不用来形容山的大小。"}, {"text": "这次的变化很微妙，大家都看得出来。", "explanation": "这里应该用〈明显〉。微妙指变化细小、不易察觉，与“大家都看得出来”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "正确：“微妙”指变化细小，与“没人注意到”相符。"}, {"text": "显著", "is_correct": false, "explanation": "语义：显著指很明显，与“没人注意到”矛盾。"}, {"text": "剧烈", "is_correct": false, "explanation": "语义：剧烈指变化很猛烈，与“没人注意到”矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：明亮形容光线，不用来描述变化的程度。"}], "explanations": {"微妙": "正确：“微妙”指变化细小，与“没人注意到”相符。", "显著": "语义：显著指很明显，与“没人注意到”矛盾。", "剧烈": "语义：剧烈指变化很猛烈，与“没人注意到”矛盾。", "明亮": "搭配：明亮形容光线，不用来描述变化的程度。"}, "sentence_index": 6, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗沙子很微妙，吹一吹就走了。", "explanation": "这里应该用〈细小〉。微妙用于差别和变化，不用来形容沙子的大小。"}, {"text": "这台机器的做工很微妙，零件都很整齐。", "explanation": "这里应该用〈精细〉。微妙用于差别和变化，不用来形容做工。"}, {"text": "他的鞋很微妙，穿了三年都没破。", "explanation": "这里应该用〈结实〉。微妙用于差别、变化，不用来形容鞋子的质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种布料的差别很微妙地，我分不清。", "corrected_sentence": "这两种布料的差别很微妙，我分不清。", "error_description": "多加了“地”：“微妙”在此作谓语，后面不加“地”，应为“很微妙”，不说“很微妙地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两块石头的颜色有一点微妙地差别。", "corrected_sentence": "两块石头的颜色有一点微妙的差别。", "error_description": "的地混用：“微妙”修饰名词“差别”，应用“的”，不能用“地”。正确为“一点微妙的差别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大人告诉小孩不能做错事的话。", "primary_collocate": null, "pronunciation": "xùn jiè", "ipa": "ɕyn˥˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈的训诫，我一直记在心里。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不听爷爷的训诫，又去河边玩了。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对弟弟说了一段严厉的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把家长的训诫当成了耳边风。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，奶奶常常给我们讲做人的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完爸爸的训诫，女儿哭着认了错。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的训诫让孩子明白了要诚实。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟低着头，听妈妈的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候常挨父亲的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些训诫，我小时候不太懂。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "家长或长辈对孩子说的、教他们不要做错事的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76ee065-26df-4d6a-b94a-ac532d78a03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "训诫", "is_correct": true, "explanation": "训诫：长辈对孩子讲的不许做错事的话，与“妈妈的”和“记在心里”相合。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是记录费用的单子，不是教导的话，不能“记在心里”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是家长说的话，“妈妈的天气”与“记在心里”都不相合。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是导电的线材，不是可以“记在心里”的话，与“妈妈的”搭配也不通。"}], "explanations": {"训诫": "训诫：长辈对孩子讲的不许做错事的话，与“妈妈的”和“记在心里”相合。", "账单": "语义：账单是记录费用的单子，不是教导的话，不能“记在心里”。", "天气": "语义：天气是自然现象，不是家长说的话，“妈妈的天气”与“记在心里”都不相合。", "电线": "语义：电线是导电的线材，不是可以“记在心里”的话，与“妈妈的”搭配也不通。"}, "sentence_index": 0, "correct_answer": "训诫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗经过训诫，已经会坐下了。", "explanation": "这里应该用〈训练〉。训诫指长辈对晚辈的告诫，不用于训练动物；训练动物要说“训练”。"}, {"text": "这所大学的训诫专业非常热门。", "explanation": "这里的“训诫”不是学科名称，它指长辈对晚辈的告诫；学科应说“教育学”之类的专业名称。"}, {"text": "他给了我一把训诫。", "explanation": "这里误把“训诫”当成有柄器具一类可以计数的东西。训诫是一番话语，应说“一番训诫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "训诫", "is_correct": true, "explanation": "训诫：长辈的告诫，与“老人”和“让孩子明白了要诚实”相合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，不能让孩子明白做人的道理。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的方法，与讲道理、让孩子明白诚实无关。"}, {"text": "鞭炮", "is_correct": false, "explanation": "语义：鞭炮是燃放的爆竹，与讲道理、让孩子明白诚实无关。"}], "explanations": {"训诫": "训诫：长辈的告诫，与“老人”和“让孩子明白了要诚实”相合。", "身高": "体貌：身高是外形特征，不能让孩子明白做人的道理。", "食谱": "语义：食谱是做菜的方法，与讲道理、让孩子明白诚实无关。", "鞭炮": "语义：鞭炮是燃放的爆竹，与讲道理、让孩子明白诚实无关。"}, "sentence_index": 6, "correct_answer": "训诫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在台上训诫了一段相声。", "explanation": "这里的“训诫”指长辈告诫晚辈，不能用于表演；表演相声应说“演”。"}, {"text": "双方签订了一份训诫。", "explanation": "这里应该用〈合同〉。训诫是长辈对晚辈的告诫，不是双方签订的文件。"}, {"text": "他给我讲了一块训诫。", "explanation": "这里误把训诫当成成块的东西来计量。训诫是一番话语，应说“一番训诫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶给我讲了一只训诫。", "corrected_sentence": "奶奶给我讲了一番训诫。", "error_description": "错误：量词“只”用于动物或个体物件，不能修饰训诫。正确应用量词“番”，说“一番训诫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听了父亲一件训诫。", "corrected_sentence": "他听了父亲一段训诫。", "error_description": "错误：量词“件”用于物件或事情，不能修饰训诫。正确应用量词“段”，说“一段训诫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
