INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24474, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得和原来不一样了。", "primary_collocate": null, "pronunciation": "biàn yì", "ipa": "pjɛn˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这种病毒很快就变异了。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片玉米变异了，种子变成了紫色。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "流感病毒每年都会变异，所以要打新疫苗。", "target_word": "变异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这株花变异以后，花瓣多了一倍。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水稻在高温下变异，长得和原来不一样。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说这种细菌已经变异过好几次了。", "target_word": "变异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想知道这种草为什么会变异。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的小鼠变异了，毛变成白色的。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病毒一变异，旧药就没用了。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生物慢慢变异，才有了今天的样子。", "target_word": "变异", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "变异了", "label": "体标"}, {"form": "变异过", "label": "体标"}, {"form": "變異", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：生物或病毒等变得和原来不一样，如病毒变异了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24474, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变异", "is_correct": true, "explanation": "变异 biàn yì：指生物或病毒等变得和原来不一样，与听到的读音相合。"}, {"text": "贬义", "is_correct": false, "explanation": "贬义 biǎn yì 与 biàn yì 第一个音节声调不同（第三声），意思是贬低的含义。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜 biànyi 第二个音节为轻声，与 biàn yì 声调不同，意思是价钱低。"}, {"text": "编译", "is_correct": false, "explanation": "编译 biān yì 第一个音节为第一声，与 biàn 声调不同，意思是编写与翻译。"}], "explanations": {"变异": "变异 biàn yì：指生物或病毒等变得和原来不一样，与听到的读音相合。", "贬义": "贬义 biǎn yì 与 biàn yì 第一个音节声调不同（第三声），意思是贬低的含义。", "便宜": "便宜 biànyi 第二个音节为轻声，与 biàn yì 声调不同，意思是价钱低。", "编译": "编译 biān yì 第一个音节为第一声，与 biàn 声调不同，意思是编写与翻译。"}, "sentence_index": null, "correct_answer": "变异"}, "level_3": {"options": [{"text": "变异", "is_correct": true, "explanation": "变异：病毒发生改变，与“很快就……了”的语境相合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”需要有被赞美的对象，病毒不能被赞美。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋，不能用于病毒。"}, {"text": "讲述", "is_correct": false, "explanation": "搭配：“讲述”的对象是故事或经过，不能用于病毒。"}], "explanations": {"变异": "变异：病毒发生改变，与“很快就……了”的语境相合。", "赞美": "语义：“赞美”需要有被赞美的对象，病毒不能被赞美。", "装修": "搭配：“装修”用于房屋，不能用于病毒。", "讲述": "搭配：“讲述”的对象是故事或经过，不能用于病毒。"}, "sentence_index": 0, "correct_answer": "变异"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "修好以后，机器又变异回了原来的样子。", "explanation": "这里应该用〈变回〉。变异指变得和原来不一样，恢复原样要用变回。"}, {"text": "他把这首歌变异得和原来一模一样。", "explanation": "这里应该用〈模仿〉。变异指变得和原来不一样，照原样做出要用模仿。"}, {"text": "这批货的价格突然变异了五块钱。", "explanation": "这里应该用〈涨〉。变异指变得和原来不一样，价格上涨要用涨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变异", "is_correct": true, "explanation": "变异：草的性状发生改变，与“科学家想知道……为什么”的语境相合。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：草没有体温，不会发烧。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于场地，不能用于草的变化。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”指人或动物在水中活动，草不能游泳。"}], "explanations": {"变异": "变异：草的性状发生改变，与“科学家想知道……为什么”的语境相合。", "发烧": "语义：草没有体温，不会发烧。", "打扫": "搭配：“打扫”用于场地，不能用于草的变化。", "游泳": "搭配：“游泳”指人或动物在水中活动，草不能游泳。"}, "sentence_index": 6, "correct_answer": "变异"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把这次考试的时间变异了。", "explanation": "这里应该用〈改〉。变异指事物自然地变得不同，人为更改时间要用改。"}, {"text": "他的身高一年变异了二十厘米。", "explanation": "这里应该用〈增长〉。变异指变得和原来不一样，身高的增加要用增长。"}, {"text": "这块饼干放了一周，变异得不能吃了。", "explanation": "这里应该用〈变质〉。变异指变得不一样，食物腐坏要用变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种细菌正在变异了。", "corrected_sentence": "这种细菌正在变异。", "error_description": "“正在”表示动作进行，不能与“了”同用。应去掉“了”，说“正在变异”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种细菌很快变异得。", "corrected_sentence": "这种细菌很快变异了。", "error_description": "“得”不能直接接在动词后作结尾，缺少补语，句子未完。表示变化已完成要用“了”，应说“这种细菌很快变异了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
