INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说明一件事的意思。", "primary_collocate": null, "pronunciation": "quán shì", "ipa": "tɕʰyɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师诠释了这个成语的意思。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你诠释一下这个句子。", "target_word": "诠释", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典诠释得很清楚。", "target_word": "诠释", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用图片诠释了这个词。", "target_word": "诠释", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我来诠释一下这条规定。", "target_word": "诠释", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里诠释了每个词的意思。", "target_word": "诠释", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话很难，谁能诠释一下？", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师诠释完，大家都明白了。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用简单的话诠释这件事的含义。", "target_word": "诠释", "complexity_tier": "T3", "furigana": "tā xiǎng yòng jiǎn dān de huà quán shì zhè jiàn shì de hán yì", "sentence_source": "generated"}, {"text": "他认真地诠释了每一条规则。", "target_word": "诠释", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诠释了", "label": "体标"}, {"form": "诠释着", "label": "体标"}, {"form": "詮釋", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把词语、句子、规定等的意思说清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24480, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释（quán shì）：说明一件事的意思，即本题目标词。"}, {"text": "拳师", "is_correct": false, "explanation": "拳师（quán shī）与诠释的第二个音节声调不同：shī 为第一声，shì 为第四声，意思是拳击或武术教练。"}, {"text": "前世", "is_correct": false, "explanation": "前世（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是前生。"}, {"text": "前事", "is_correct": false, "explanation": "前事（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是过去的事情。"}, {"text": "泉水", "is_correct": false, "explanation": "泉水（quán shuǐ）第二个音节的韵母与声调都不同：shuǐ 为第三声，shì 为第四声，意思是从地下涌出的水。"}], "explanations": {"诠释": "诠释（quán shì）：说明一件事的意思，即本题目标词。", "拳师": "拳师（quán shī）与诠释的第二个音节声调不同：shī 为第一声，shì 为第四声，意思是拳击或武术教练。", "前世": "前世（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是前生。", "前事": "前事（qián shì）与诠释的第一个音节不同：qián 没有介音 u，意思是过去的事情。", "泉水": "泉水（quán shuǐ）第二个音节的韵母与声调都不同：shuǐ 为第三声，shì 为第四声，意思是从地下涌出的水。"}, "sentence_index": null, "correct_answer": "诠释"}, "level_3": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释：说明成语的含义，与“成语的意思”的语境一致。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的宾语是商品，不能接“成语的意思”。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”接的是生活或待遇，不能接“成语的意思”这类含义。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指毁坏，老师讲解成语不会毁坏它的意思，语义相反。"}], "explanations": {"诠释": "诠释：说明成语的含义，与“成语的意思”的语境一致。", "购买": "搭配：“购买”的宾语是商品，不能接“成语的意思”。", "享受": "搭配：“享受”接的是生活或待遇，不能接“成语的意思”这类含义。", "破坏": "语义：“破坏”指毁坏，老师讲解成语不会毁坏它的意思，语义相反。"}, "sentence_index": 0, "correct_answer": "诠释"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挥手诠释了再见。", "explanation": "这里应该用〈表示〉。诠释用于说明词句或作品的含义，挥手表示再见是动作，不能说诠释。"}, {"text": "妈妈诠释了这盘红烧肉。", "explanation": "诠释的对象是需要说明含义的内容，红烧肉是食物，这里应该用〈烹饪〉。"}, {"text": "我把那辆车诠释了一遍。", "explanation": "诠释的对象是需要说明含义的内容，车是实物，不能诠释；这里应该用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24480, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释（quán shì）：说明一件事的意思，即本题目标词。"}, {"text": "宣誓", "is_correct": false, "explanation": "宣誓（xuān shì）与诠释的第一个音节声母不同：xuān 声母为 x，quán 声母为 q，意思是公开表示誓言。"}, {"text": "全书", "is_correct": false, "explanation": "全书（quán shū）第二个音节的声调不同：shū 为第一声，shì 为第四声，意思是整部书。"}, {"text": "全速", "is_correct": false, "explanation": "全速（quán sù）第二个音节的声母不同：s 与 sh，声调相同，意思是最高的速度。"}], "explanations": {"诠释": "诠释（quán shì）：说明一件事的意思，即本题目标词。", "宣誓": "宣誓（xuān shì）与诠释的第一个音节声母不同：xuān 声母为 x，quán 声母为 q，意思是公开表示誓言。", "全书": "全书（quán shū）第二个音节的声调不同：shū 为第一声，shì 为第四声，意思是整部书。", "全速": "全速（quán sù）第二个音节的声母不同：s 与 sh，声调相同，意思是最高的速度。"}, "sentence_index": null, "correct_answer": "诠释"}, "level_3": {"options": [{"text": "诠释", "is_correct": true, "explanation": "诠释：把这句话的意思讲清楚，符合“谁能……一下”的请求。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流推动，句中“这句话很难”需要的是讲解，不能“吹一下”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是用水加热食物，与讲解句子的含义无关。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”的对象是可以选择的物品，不能用来“挑选”一句话的含义。"}], "explanations": {"诠释": "诠释：把这句话的意思讲清楚，符合“谁能……一下”的请求。", "吹": "语义：“吹”指用气流推动，句中“这句话很难”需要的是讲解，不能“吹一下”。", "煮": "语义：煮是用水加热食物，与讲解句子的含义无关。", "挑选": "搭配：“挑选”的对象是可以选择的物品，不能用来“挑选”一句话的含义。"}, "sentence_index": 6, "correct_answer": "诠释"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人诠释了墙壁。", "explanation": "这里应该用〈粉刷〉。诠释针对需要说明含义的内容，墙壁是建筑物，应该说粉刷墙壁。"}, {"text": "我昨天诠释了一碗面条。", "explanation": "这里应该用〈吃〉。诠释的对象是需要说明含义的内容，面条是食物，应该说吃面条。"}, {"text": "医生诠释了病人的心脏。", "explanation": "诠释的对象是需要说明含义的内容，心脏是器官，这里应该用〈检查〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师会耐心地对诠释这个难懂的词。", "corrected_sentence": "这位老师会耐心地诠释这个难懂的词。", "error_description": "“诠释”直接带宾语，前面不能加介词“对”。应说“耐心地诠释这个难懂的词”，不说“对诠释”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题很难，请你诠释一下了它的含义。", "corrected_sentence": "这个问题很难，请你诠释一下它的含义。", "error_description": "“一下”后面不能再加“了”。请求句的动作还没有发生，应说“诠释一下它的含义”，不说“诠释一下了它的含义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
