INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24482, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "活着的身体。", "primary_collocate": null, "pronunciation": "huó tǐ", "ipa": "xuo̯˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "尸体没有呼吸，活体才有心跳。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生分不清那是尸体还是活体。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活体会呼吸，也会出汗。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活体还在动，不是标本。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家想画活体，不想画石膏像。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生先看尸体的结构，再研究活体的生理变化。", "target_word": "活体", "complexity_tier": "T3", "furigana": "huó tǐ", "sentence_source": "generated"}, {"text": "把手放上去，能感到活体的温度。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活体有体温，尸体却是冰冷的。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想看看活体是怎么动的。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条蛇是活体，不是玩具。", "target_word": "活体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "活體", "label": "繁体"}, {"form": "活体组织", "label": "复合"}, {"form": "活体检测", "label": "复合"}], "register": "书面", "sense_fingerprint": "活着的身体，与尸体相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c129f6d-1946-456e-a53b-85dab20cb751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活体", "is_correct": true, "explanation": "正确：与前句「没有呼吸」形成对比，只有活着的身体才有心跳。"}, {"text": "标本", "is_correct": false, "explanation": "语义：标本已经没有生命，不可能有心跳，与「才有心跳」矛盾。"}, {"text": "石膏", "is_correct": false, "explanation": "搭配：石膏是无生命的材料，「有心跳」不能用于石膏。"}, {"text": "玩偶", "is_correct": false, "explanation": "语义：玩偶没有生命，不会有心跳，与「尸体没有呼吸」的对比不合理。"}], "explanations": {"活体": "正确：与前句「没有呼吸」形成对比，只有活着的身体才有心跳。", "标本": "语义：标本已经没有生命，不可能有心跳，与「才有心跳」矛盾。", "石膏": "搭配：石膏是无生命的材料，「有心跳」不能用于石膏。", "玩偶": "语义：玩偶没有生命，不会有心跳，与「尸体没有呼吸」的对比不合理。"}, "sentence_index": 0, "correct_answer": "活体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生确认活体已经没有呼吸。", "explanation": "这里应该用〈尸体〉。「活体」指活着的身体，不能说它已经没有呼吸。"}, {"text": "果篮里放着几个活体。", "explanation": "这里应该用〈水果〉。果篮里放的是水果，「活体」指活着的身体，不能用来指水果。"}, {"text": "这场手术关系到病人的活体安全。", "explanation": "这里应该用〈生命〉。关系到安全的是生命，「活体」指身体，不能指生命本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活体", "is_correct": true, "explanation": "正确：「能感到……的温度」的对象是有温度的身体，与「把手放上去」相符。"}, {"text": "文字", "is_correct": false, "explanation": "语义：文字没有温度，与「把手放上去」的触感语境不合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「感到……的温度」的对象应是有温度的实体，「声音」不能与之搭配。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水的温度与「把手放上去」的感受无关，句意不通。"}], "explanations": {"活体": "正确：「能感到……的温度」的对象是有温度的身体，与「把手放上去」相符。", "文字": "语义：文字没有温度，与「把手放上去」的触感语境不合。", "声音": "搭配：「感到……的温度」的对象应是有温度的实体，「声音」不能与之搭配。", "墨水": "语义：墨水的温度与「把手放上去」的感受无关，句意不通。"}, "sentence_index": 6, "correct_answer": "活体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从口袋里掏出一个活体。", "explanation": "这里应该用〈钱包〉。「活体」指活着的身体，不能用来指钱包之类的物品。"}, {"text": "他在花园里摘了一个活体。", "explanation": "这里应该用〈西瓜〉。「活体」指活着的身体，不能用来指瓜果。"}, {"text": "他把活体告诉了老师。", "explanation": "这里应该用〈事情〉。「活体」指身体，不能用来指事情或消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张活体需要定时测量体温。", "corrected_sentence": "这个活体需要定时测量体温。", "error_description": "量词错误：「活体」指活着的身体，应用量词「个」。「张」只用于纸、画等平面的东西，应说「这个活体」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看到了一个的活体。", "corrected_sentence": "他看到了一个活体。", "error_description": "结构助词错误：数量短语与名词之间不用「的」，应说「一个活体」，「一个的活体」多加了「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
