INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指最早住在一个地方的人。", "primary_collocate": null, "pronunciation": "yuán zhù mín", "ipa": "ɥɛn˧˥ ʈʂu˥˩ min˧˥", "syllable_count": 3, "sentences": [{"text": "他是这片草原上的原住民。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原住民早就住在这座山里了。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的原住民都认识他。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "移民来了以后，原住民给了他们很多帮助。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在旅行时认识了一位原住民朋友。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原住民带我们走过了森林。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上的原住民不多了。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原住民一直住在海边。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了原住民的照片。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原住民用自己的话讲故事。", "target_word": "原住民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原住民族", "label": "复合"}], "register": "中性", "sense_fingerprint": "最早住在一个地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c129f6d-1946-456e-a53b-85dab20cb751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原住民", "is_correct": true, "explanation": "正确：「他是这片草原上的」后接指最早居住者的身份，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「他」是人，「他是石头」不合逻辑。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：「他是草原上的海洋」与草原的地点不合，句意不通。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：「是……的」后面的名词应指人，「工厂」不能指人。"}], "explanations": {"原住民": "正确：「他是这片草原上的」后接指最早居住者的身份，符合语境。", "石头": "语义：「他」是人，「他是石头」不合逻辑。", "海洋": "语义：「他是草原上的海洋」与草原的地点不合，句意不通。", "工厂": "搭配：「是……的」后面的名词应指人，「工厂」不能指人。"}, "sentence_index": 0, "correct_answer": "原住民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原住民以为这里没有人居住。", "explanation": "这里应该用〈外来者〉。原住民就是本地居民，不会以为这里没有人住。"}, {"text": "原住民在这里生活了几十年，才慢慢融入了当地的生活。", "explanation": "这里应该用〈移居者〉。原住民最早就住在这里，不会是几十年后才融入当地生活的人。"}, {"text": "这些原住民刚到这里，还不熟悉当地的气候。", "explanation": "这里应该用〈移民〉。原住民最早住在这里，不会是刚到这里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原住民", "is_correct": true, "explanation": "正确：句子说的是人口减少，「这个岛上的原住民不多了」符合语境。"}, {"text": "恒星", "is_correct": false, "explanation": "语义：整句讲的是人口减少，恒星与之无关，句意不通。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：「不多了」只能修饰可数的人或物，「大海」不可数，不能说「不多了」。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪与「人口减少」的语境无关，句意不通。"}], "explanations": {"原住民": "正确：句子说的是人口减少，「这个岛上的原住民不多了」符合语境。", "恒星": "语义：整句讲的是人口减少，恒星与之无关，句意不通。", "大海": "搭配：「不多了」只能修饰可数的人或物，「大海」不可数，不能说「不多了」。", "海浪": "语义：海浪与「人口减少」的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "原住民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "原住民在两百年前才登上这座岛。", "explanation": "这里应该用〈殖民者〉。原住民最早就住在这座岛上，不会是两百年前才登岛的人。"}, {"text": "原住民对这里的地形很陌生。", "explanation": "这里应该用〈后来的人〉。原住民最早就住在这里，不会对这里的地形感到陌生。"}, {"text": "原住民第一次走进这片森林，就迷了路。", "explanation": "这里应该用〈探险家〉。原住民一直住在这片森林附近，不会第一次走进来就迷路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们向一条原住民请教了草药的用法。", "corrected_sentence": "我们向一位原住民请教了草药的用法。", "error_description": "量词错误：「原住民」指人，应用量词「位」，「条」多用于长条之物，不能用于人，应说「一位原住民」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有一只原住民学会了汉语。", "corrected_sentence": "有一位原住民学会了汉语。", "error_description": "量词错误：「原住民」指人，应用量词「位」，「只」多用于动物，不能说「一只原住民」，应说「一位原住民」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c837b05-8f17-440e-b944-e36f26bf4d0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
