INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "双方彼此互相担任对方的某种角色或身份。", "primary_collocate": null, "pronunciation": "hù wéi", "ipa": "xu˥˩ wei˧˥", "syllable_count": 2, "sentences": [{"text": "小明和小红互为对方的好朋友。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩互为对方的依靠。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个互为对方的中文老师。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们互为对手，每次比赛都很认真。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子互为玩伴，每天一起玩。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌互为对方的老师，一起检查作业。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和室友互为对方的闹钟，早上互相叫醒。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们互为知己，什么话都能说。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王和老李住在一起，互为对方的家人。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队互为对手，也互为朋友。", "target_word": "互为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "两人互相给对方担任同样的角色（互为对方的……）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包括", "is_correct": false, "explanation": "语义：“包括”表示包含，小明和小红之间并不是包含关系。"}, {"text": "抢走", "is_correct": false, "explanation": "语义：“抢走”表示夺取，与两人互为好朋友的意思相反。"}, {"text": "互为", "is_correct": true, "explanation": "互为：表示两人彼此担任对方的好朋友，符合句意。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：“比较”后接可以比较的对象，不说“比较对方的好朋友”。"}], "explanations": {"包括": "语义：“包括”表示包含，小明和小红之间并不是包含关系。", "抢走": "语义：“抢走”表示夺取，与两人互为好朋友的意思相反。", "互为": "互为：表示两人彼此担任对方的好朋友，符合句意。", "比较": "搭配：“比较”后接可以比较的对象，不说“比较对方的好朋友”。"}, "sentence_index": 0, "correct_answer": "互为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和爸爸互为孩子，他每天都带我去公园。", "explanation": "这里应该用〈是〉。“互为”的双方须担任同样的角色，爸爸和我的身份不同，不能说“互为孩子”。"}, {"text": "老师互为我的学生，教我中文。", "explanation": "这里应该用〈是〉。“互为”强调双方彼此担任同样的角色，这里只是老师教我，应说“是我的老师”。"}, {"text": "我互为朋友，每天一起玩。", "explanation": "这里应该用〈是〉。“互为”需要双方，句中只有“我”一方，应说“是朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“早上互相叫醒”的合作语境矛盾。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”后接食物，不能用于闹钟。"}, {"text": "互为", "is_correct": true, "explanation": "互为：双方彼此担任对方的闹钟，符合“互相叫醒”的语境。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”后接食物，不说“品尝对方的闹钟”。"}], "explanations": {"偷": "语义：“偷”是窃取，与“早上互相叫醒”的合作语境矛盾。", "吃掉": "搭配：“吃掉”后接食物，不能用于闹钟。", "互为": "互为：双方彼此担任对方的闹钟，符合“互相叫醒”的语境。", "品尝": "搭配：“品尝”后接食物，不说“品尝对方的闹钟”。"}, "sentence_index": 6, "correct_answer": "互为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和小狗互为对方的主人，每天一起散步。", "explanation": "这里应该用〈是〉。“互为”的双方须担任同样的角色，人和小狗的身份不同，不能说“互为主人”。"}, {"text": "我一个人互为两个人的老师，教得很好。", "explanation": "这里应该用〈是〉。“互为”需要双方，句中只有“我”一方，应说“是两个人的老师”。"}, {"text": "父母互为孩子的老师，教他们读书。", "explanation": "这里应该用〈是〉。“互为”强调双方彼此担任同样的角色，这里是父母单方面教孩子，应说“是孩子的老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩互为对方帮忙。", "corrected_sentence": "他们俩互为对方的帮手。", "error_description": "“互为”后面接的是所担任的角色（名词），不能接动词“帮忙”。应改为“互为对方的帮手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两位同事互为了对方的帮手。", "corrected_sentence": "这两位同事互为对方的帮手。", "error_description": "“了”误加在“互为”之后。“互为”后不需要“了”，句中是陈述，正确为“互为对方的帮手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
