INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地貌就是地球表面的样子，有高山、平地等。", "primary_collocate": null, "pronunciation": "dì mào", "ipa": "ti˥˩ mau˥˩", "syllable_count": 2, "sentences": [{"text": "我们学校附近的地貌很平，没有山。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的地貌有高山，也有平地。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢拍照，也爱看不同的地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方多雨，所以那里的地貌和北方不一样。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的颜色能告诉我们地貌是高还是低。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪山和湖让这里的地貌特别美。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去看看西藏的高原地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车走了一天，窗外的地貌一直在变。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画出这里的地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山很高的地方，地貌和海边完全不同。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "地貌学", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球表面的样子（高山、平地等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是大气的状况，不是地面的形状，不能说“很平”。"}, {"text": "地貌", "is_correct": true, "explanation": "地貌：地表的样子，可以说“很平”，与“没有山”的描述相符。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”指八卦图或流言，不能用来形容地面的样子，说“很平”不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书籍，不是地表的样子，不能说“很平”。"}], "explanations": {"天气": "语义：天气是大气的状况，不是地面的形状，不能说“很平”。", "地貌": "地貌：地表的样子，可以说“很平”，与“没有山”的描述相符。", "八卦": "语义：“八卦”指八卦图或流言，不能用来形容地面的样子，说“很平”不通。", "课本": "语义：课本是书籍，不是地表的样子，不能说“很平”。"}, "sentence_index": 0, "correct_answer": "地貌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里地貌很热，夏天经常下雨。", "explanation": "这里应该用〈天气〉。地貌指地表的样子，不能用“热”来形容；说冷热要用〈天气〉。"}, {"text": "南方的地貌很湿润，雨水很多。", "explanation": "这里应该用〈气候〉。“湿润”形容的是气候，地貌不能潮湿；说干湿要用〈气候〉。"}, {"text": "他把地貌写在信封上。", "explanation": "这里应该用〈地址〉。地址可以写在信封上；地貌是地表形态的类型，不是用来寄送的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是可以去看的景物，“去看看西藏的高原作业”不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不是地表的景物，不能用来“去看看”高原。"}, {"text": "地貌", "is_correct": true, "explanation": "地貌：地表的样子，可以去看，与西藏高原的语境相符。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法不是可以去看的实体，与“去看看西藏的高原”矛盾。"}], "explanations": {"作业": "语义：作业是学习任务，不是可以去看的景物，“去看看西藏的高原作业”不通。", "电脑": "语义：电脑是机器，不是地表的景物，不能用来“去看看”高原。", "地貌": "地貌：地表的样子，可以去看，与西藏高原的语境相符。", "语法": "语义：语法不是可以去看的实体，与“去看看西藏的高原”矛盾。"}, "sentence_index": 6, "correct_answer": "地貌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里地貌很湿，下雨后很滑。", "explanation": "这里应该用〈地面〉。地面可以湿、可以滑；地貌是地表形态的类型，不说潮湿。"}, {"text": "这家店位于市中心的黄金地貌。", "explanation": "这里应该用〈地段〉。地段指位置，可以说“黄金地段”；地貌不指商业位置。"}, {"text": "这位老人的地貌很慈祥。", "explanation": "这里应该用〈面貌〉。地貌指地表形态，不指人的样子；形容人的神态要用〈面貌〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只地貌在南方很少见。", "corrected_sentence": "那种地貌在南方很少见。", "error_description": "“地貌”前的量词错误：“只”用于动物等个体，应改为“种”，即“那种地貌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带的地貌们很平坦。", "corrected_sentence": "这一带的地貌很平坦。", "error_description": "“地貌”后多加了“们”：“们”只用于指人的复数，地貌是事物，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
