INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "神话是古代人编的故事，里面有神仙和英雄。", "primary_collocate": null, "pronunciation": "shén huà", "ipa": "ʂən˧˥ xua˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶晚上给我讲了一个神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里有神仙，也有英雄。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个神话是古代人编的故事。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢嫦娥奔月这个神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话不是真的，但是很好听。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆借了一本讲神话的书。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个中国神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里的神仙都有特别的本事。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我很爱看神话，常常看到很晚。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，神话能让我们了解古代人的想法。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "则", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "神话故事", "label": "复合"}, {"form": "神話", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古代人编的、有神仙和英雄的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确答案，shén huà，指古代人编的、有神仙和英雄的故事。"}, {"text": "深化", "is_correct": false, "explanation": "shēn（第一声）与 shén（第二声）声调不同，意思是“深化”。"}, {"text": "文化", "is_correct": false, "explanation": "wén（第二声）与 shén（第二声）声母不同（w／sh），声调相同，意思是“文化”。"}, {"text": "真话", "is_correct": false, "explanation": "zhēn（第一声）与 shén（第二声）声母不同（zh／sh），声调也不同，意思是“真话”。"}, {"text": "生化", "is_correct": false, "explanation": "shēng（第一声）与 shén（第二声）韵母不同（eng／en），声调也不同，意思是“生化”。"}], "explanations": {"神话": "正确答案，shén huà，指古代人编的、有神仙和英雄的故事。", "深化": "shēn（第一声）与 shén（第二声）声调不同，意思是“深化”。", "文化": "wén（第二声）与 shén（第二声）声母不同（w／sh），声调相同，意思是“文化”。", "真话": "zhēn（第一声）与 shén（第二声）声母不同（zh／sh），声调也不同，意思是“真话”。", "生化": "shēng（第一声）与 shén（第二声）韵母不同（eng／en），声调也不同，意思是“生化”。"}, "sentence_index": null, "correct_answer": "神话"}, "level_3": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确。“讲了一个”后接的是故事，神话是神仙、英雄的故事，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“讲”的宾语是故事、话语，冰箱不能被讲述。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是记账凭证，不是可以讲述的故事，与“晚上讲给我听”的语境不符。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“讲”不能以电脑作宾语，电脑不能被讲述。"}], "explanations": {"神话": "正确。“讲了一个”后接的是故事，神话是神仙、英雄的故事，符合语境。", "冰箱": "搭配：“讲”的宾语是故事、话语，冰箱不能被讲述。", "账单": "语义：账单是记账凭证，不是可以讲述的故事，与“晚上讲给我听”的语境不符。", "电脑": "搭配：“讲”不能以电脑作宾语，电脑不能被讲述。"}, "sentence_index": 0, "correct_answer": "神话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段神话记录了北宋时期的一场战争。", "explanation": "这里应该用〈历史〉。神话是神仙、英雄的虚构故事，不用来记录真实发生的战争。"}, {"text": "我最喜欢读居里夫人的神话。", "explanation": "这里应该用〈传记〉。神话写的是神仙、英雄的虚构故事，不写真实人物的生平。"}, {"text": "这个神话讲的是一个守井的老人。", "explanation": "这里应该用〈传说〉。神话要有神仙或神化的英雄，写守井老人这类普通人的事应说传说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确。电影讲的是一个中国神话，指中国的神仙、英雄故事，符合语境。"}, {"text": "美食", "is_correct": false, "explanation": "语义：美食不是能被电影讲述的故事情节，与“中国神话”的语境不合。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不是电影讲述的故事题材，与“中国”的神话语境不符。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“讲的是”后接的是故事、事件等内容，沙发不能作为电影讲述的对象。"}], "explanations": {"神话": "正确。电影讲的是一个中国神话，指中国的神仙、英雄故事，符合语境。", "美食": "语义：美食不是能被电影讲述的故事情节，与“中国神话”的语境不合。", "数学": "语义：数学不是电影讲述的故事题材，与“中国”的神话语境不符。", "沙发": "搭配：“讲的是”后接的是故事、事件等内容，沙发不能作为电影讲述的对象。"}, "sentence_index": 6, "correct_answer": "神话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本神话的主人公是一个爱吃糖的小女孩。", "explanation": "这里应该用〈童话〉。神话写神仙、英雄的故事，写小女孩爱吃糖这类日常童趣的应说童话。"}, {"text": "这则神话里，狐狸骗走了乌鸦嘴里的肉。", "explanation": "这里应该用〈寓言〉。神话写神仙、英雄的事；借动物讲道理的故事是寓言，不能称作“这则神话”。"}, {"text": "这部神话讲的是一位侠客远走江湖的故事。", "explanation": "这里应该用〈传奇〉。神话以神仙和神化英雄为主，写侠客闯荡江湖的故事应说传奇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候常听爸爸讲一座神话。", "corrected_sentence": "我小时候常听爸爸讲一个神话。", "error_description": "“座”是用于山、楼房等大型固定物的量词，不能修饰神话；应改为“一个神话”，“个”是通用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些神话们都很有名。", "corrected_sentence": "这些神话都很有名。", "error_description": "“们”只能加在指人的名词后面，神话不能说“神话们”；应去掉“们”，直接说“这些神话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
