INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发生的那一下。", "primary_collocate": null, "pronunciation": "shì jiàn", "ipa": "ʂɻ̩⁵¹ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "事件发生时，我正在家里睡觉。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事件发生的那一下，我听见了一声巨响。", "target_word": "事件", "complexity_tier": "T3", "furigana": "shì jiàn fā shēng de nà yí xià, wǒ tīng jiàn le yì shēng jù xiǎng。", "sentence_source": "generated"}, {"text": "事件发生后，警察马上就到了。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眨了一下眼，正好错过了事件发生的那一刻。", "target_word": "事件", "complexity_tier": "T3", "furigana": "tā zhǎ le yí xià yǎn, zhèng hǎo cuò guò le shì jiàn fā shēng de nà yí kè。", "sentence_source": "generated"}, {"text": "事件发生得很突然，大家都没想到。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事件发生的那一下，我连眼睛都没来得及眨。", "target_word": "事件", "complexity_tier": "T3", "furigana": "shì jiàn fā shēng de nà yí xià, wǒ lián yǎn jing dōu méi lái de jí zhǎ。", "sentence_source": "generated"}, {"text": "事件发生的时候，街上没有人。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把事件发生的时间写了下来。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事件发生前，天气一直很好。", "target_word": "事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你还记得事件发生的那一刻吗？", "target_word": "事件", "complexity_tier": "T3", "furigana": "nǐ hái jì de shì jiàn fā shēng de nà yí kè ma？", "sentence_source": "generated"}], "morphological_forms": [{"form": "起", "label": "量词"}, {"form": "突发事件", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情发生的那一刻或过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24498, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事件", "is_correct": true, "explanation": "正确答案，shì jiàn，指事情发生的那一刻或过程。"}, {"text": "世界", "is_correct": false, "explanation": "jiè（第四声）与 jiàn（第四声）韵母不同（ie／ian），声调相同，意思是“世界”。"}, {"text": "时间", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，意思是“时间”。"}, {"text": "实践", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，jiàn 相同，意思是“实践”。"}, {"text": "世间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，shì 相同，意思是“世间”。"}], "explanations": {"事件": "正确答案，shì jiàn，指事情发生的那一刻或过程。", "世界": "jiè（第四声）与 jiàn（第四声）韵母不同（ie／ian），声调相同，意思是“世界”。", "时间": "shí（第二声）与 shì（第四声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，意思是“时间”。", "实践": "shí（第二声）与 shì（第四声）声调不同，jiàn 相同，意思是“实践”。", "世间": "jiān（第一声）与 jiàn（第四声）声调不同，shì 相同，意思是“世间”。"}, "sentence_index": null, "correct_answer": "事件"}, "level_3": {"options": [{"text": "事件", "is_correct": true, "explanation": "正确。“事件发生时”作主语，符合“事情发生的那一刻”的语境。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“发生”的主语多为事件、事故，“面包”不能与“发生”搭配。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法不会在某一刻“发生”，与“我正在家里睡觉”的语境不合。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“发生”的主语多为事件、事故，“雨伞”不能与“发生”搭配。"}], "explanations": {"事件": "正确。“事件发生时”作主语，符合“事情发生的那一刻”的语境。", "面包": "搭配：“发生”的主语多为事件、事故，“面包”不能与“发生”搭配。", "语法": "语义：语法不会在某一刻“发生”，与“我正在家里睡觉”的语境不合。", "雨伞": "搭配：“发生”的主语多为事件、事故，“雨伞”不能与“发生”搭配。"}, "sentence_index": 0, "correct_answer": "事件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在那个事件按下了快门。", "explanation": "这里应该用〈瞬间〉。“事件”指事情发生的那一下，这里要指按快门的时刻，应说“那个瞬间”。"}, {"text": "学校组织了一场事件，大家都很开心。", "explanation": "这里应该用〈活动〉。组织的是活动，“事件”指已经发生的事情，不能用来组织。"}, {"text": "他把事件放进了口袋。", "explanation": "这里应该用〈钥匙〉。事件是发生的事，不能被装进口袋；放进口袋的应是具体的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事件", "is_correct": true, "explanation": "正确。“事件发生的时候”指事情发生的那一刻，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会在某一刻“发生”，与“街上没有人”的语境不合。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“发生”的主语多为事件、事故，“早饭”不能与“发生”搭配。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "搭配：“发生”的主语多为事件、事故，“冰淇淋”不能与“发生”搭配。"}], "explanations": {"事件": "正确。“事件发生的时候”指事情发生的那一刻，符合语境。", "作业": "语义：作业不会在某一刻“发生”，与“街上没有人”的语境不合。", "早饭": "搭配：“发生”的主语多为事件、事故，“早饭”不能与“发生”搭配。", "冰淇淋": "搭配：“发生”的主语多为事件、事故，“冰淇淋”不能与“发生”搭配。"}, "sentence_index": 6, "correct_answer": "事件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的事件很快，大家都看呆了。", "explanation": "这里应该用〈动作〉。事件指事情发生的那一下或有影响的事，不能用来形容人的动作快慢。"}, {"text": "跑步已经成了他的事件，他每天都坚持。", "explanation": "这里应该用〈习惯〉。“事件”指发生过的事情，不能指每天重复的习惯。"}, {"text": "我们制定了一个事件，准备明天开始执行。", "explanation": "这里应该用〈计划〉。事件指事情发生的那一下或发生过的事，不能被制定，制定的应是〈计划〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那件事件发生后，我马上打了电话。", "corrected_sentence": "那起事件发生后，我马上打了电话。", "error_description": "“件”多用于事情、物品，事件的量词是“起”；应改为“那起事件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些事件们都发生在晚上。", "corrected_sentence": "这些事件都发生在晚上。", "error_description": "“们”只能加在指人的名词后面，事件不能说“事件们”；应去掉“们”，直接说“这些事件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
