INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24500, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让机器关掉再打开。", "primary_collocate": null, "pronunciation": "chóng qǐ", "ipa": "ʈʂʰʊŋ³⁵ tɕʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "路由器没有网络时，请先重启。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把电脑关了又重启了一次。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重启手机以后，声音就恢复了。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按这个键可以重启机器。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重启电脑要等一两分钟。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心重启了我的电脑。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打印机坏了，试试重启它。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先保存文件，再重启电脑。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器重启后，一切都正常了。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视卡住了，只能重启。", "target_word": "重启", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重启了", "label": "体标"}, {"form": "重启过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把机器关掉再打开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重启", "is_correct": true, "explanation": "正确：“请先重启”指先关机再开机，是没有网络时的常见处理。"}, {"text": "打包", "is_correct": false, "explanation": "语义：“打包”指把东西装箱或包好，与排查网络故障无关。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”针对物体的位移，不用于处理网络故障。"}, {"text": "冲洗", "is_correct": false, "explanation": "语义：“冲洗”指用水清洗，与路由器没有网络无关。"}], "explanations": {"重启": "正确：“请先重启”指先关机再开机，是没有网络时的常见处理。", "打包": "语义：“打包”指把东西装箱或包好，与排查网络故障无关。", "搬运": "搭配：“搬运”针对物体的位移，不用于处理网络故障。", "冲洗": "语义：“冲洗”指用水清洗，与路由器没有网络无关。"}, "sentence_index": 0, "correct_answer": "重启"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友很累，我把他重启了。", "explanation": "这里应该用〈让……休息〉。重启只用于机器或系统，累了的人应说让……休息。"}, {"text": "这条路堵住了，我把它重启了。", "explanation": "这里应该用〈疏通〉。重启只用于机器或系统，堵住的路要疏通。"}, {"text": "这杯水已经凉了，我把它重启了。", "explanation": "这里应该用〈加热〉。重启只用于机器或系统，水凉了要加热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重启", "is_correct": true, "explanation": "正确：“试试重启它”指关机后再开机，适用于出故障的打印机。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与修理打印机无关。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”针对食物，不能用于打印机。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与打印机故障无关。"}], "explanations": {"重启": "正确：“试试重启它”指关机后再开机，适用于出故障的打印机。", "翻译": "语义：“翻译”指转换语言，与修理打印机无关。", "煮": "搭配：“煮”针对食物，不能用于打印机。", "唱": "语义：“唱”指发声演唱，与打印机故障无关。"}, "sentence_index": 6, "correct_answer": "重启"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很渴，所以重启了一罐饮料。", "explanation": "这里应该用〈打开〉。重启只用于机器或系统，不能用于饮料。"}, {"text": "我们重启了那本书，想从头读起。", "explanation": "语义：重启指关机后再开始运行，从头读书应说“重读”。"}, {"text": "我想把这首歌重启到开头，再听一遍。", "explanation": "语义：重启指机器重新开始运行，播放器回到开头应说“倒回”或“重播”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你重启了一下电脑。", "corrected_sentence": "请你重启一下电脑。", "error_description": "祈使句中“重启”后不应加“了”，应说“重启一下”，“了”多余。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视卡住后，我重启了一个。", "corrected_sentence": "电视卡住后，我重启了一次。", "error_description": "“重启”的动量词应为“次”，不能说“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
