INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24504, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容非常特别、伟大，让人尊敬，不可以随便乱碰。", "primary_collocate": null, "pronunciation": "shén shèng", "ipa": "ʂən˧˥ ʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这间屋子很神圣，孩子们不能乱进。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人说，神圣的树不能随便砍。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他心里，那面旗是神圣的。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是神圣的地方，请不要大声说话。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，祖先留下的东西很神圣，不能乱动。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对她而言，这个仪式十分神圣。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们认为河水是神圣的，不会去污染它。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在神圣的场所拍照。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本古书在他们眼里很神圣。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座神圣的山，平时没人敢上去。", "target_word": "神圣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神聖", "label": "繁体"}], "register": "书面", "sense_fingerprint": "伟大而受人尊敬、不可随便触碰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神圣", "is_correct": true, "explanation": "神圣指特别伟大、值得尊敬，“不能乱进”的屋子符合这一语境。"}, {"text": "好笑", "is_correct": false, "explanation": "语义：“好笑”指令人发笑，与“不能乱进”的庄重语境不符。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”是味觉，不能用来形容屋子。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能用来形容屋子。"}], "explanations": {"神圣": "神圣指特别伟大、值得尊敬，“不能乱进”的屋子符合这一语境。", "好笑": "语义：“好笑”指令人发笑，与“不能乱进”的庄重语境不符。", "辣": "搭配：“辣”是味觉，不能用来形容屋子。", "咸": "搭配：“咸”形容味道，不能用来形容屋子。"}, "sentence_index": 0, "correct_answer": "神圣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个游戏很神圣，孩子们玩得很开心。", "explanation": "这里应该用〈有趣〉。神圣指特别伟大、受尊敬，不用于形容游戏。"}, {"text": "他讲的笑话很神圣，大家都笑了。", "explanation": "这里应该用〈好笑〉。神圣不用于形容笑话的趣味。"}, {"text": "这家饭店很神圣，服务员都很热情。", "explanation": "这里应该用〈豪华〉。神圣指伟大、受尊敬，不用于形容饭店的档次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神圣", "is_correct": true, "explanation": "神圣指值得尊敬、不可亵渎，“不会去污染它”与这一语境相符。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”只能形容食物，与“河水”不搭，句意也不成立。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“高速”形容速度，不用于形容河水的性质。"}, {"text": "肮脏", "is_correct": false, "explanation": "语义：“肮脏”与“不会去污染它”的敬重语境相矛盾。"}], "explanations": {"神圣": "神圣指值得尊敬、不可亵渎，“不会去污染它”与这一语境相符。", "好吃": "语义：“好吃”只能形容食物，与“河水”不搭，句意也不成立。", "高速": "搭配：“高速”形容速度，不用于形容河水的性质。", "肮脏": "语义：“肮脏”与“不会去污染它”的敬重语境相矛盾。"}, "sentence_index": 6, "correct_answer": "神圣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很神圣，大家看得很开心。", "explanation": "这里应该用〈精彩〉。神圣不用于形容电影的好看程度。"}, {"text": "她的成绩很神圣，老师很满意。", "explanation": "这里应该用〈优秀〉。神圣指伟大、受尊敬，不用于描述成绩的好坏。"}, {"text": "这条路很神圣，车很多。", "explanation": "这里应该用〈繁忙〉。神圣不用于形容道路的交通状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只祠堂很神圣，孩子们不能乱闯。", "corrected_sentence": "这座祠堂很神圣，孩子们不能乱闯。", "error_description": "错误在量词：“祠堂”是建筑，应用“座”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只神圣的山，平时没人敢靠近。", "corrected_sentence": "那座神圣的山，平时没人敢靠近。", "error_description": "错误在量词：“山”应用“座”，“只”不能用于山。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
