INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把别人说过的话再说一遍。", "primary_collocate": null, "pronunciation": "fù shù", "ipa": "fu⁵¹ ʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "我没听清，你能复述一遍吗？", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他复述了朋友刚才说的话。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我复述老师的意见。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用中文复述这句话。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把客人的要求复述给经理。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们听着故事，然后一起复述。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会复述，听一遍就能说出来。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我复述了一次，他才明白。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说完后，先请小明复述。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话太长，我复述不出来。", "target_word": "复述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复述了", "label": "体标"}, {"form": "复述过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把别人说的话再说一遍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91bde6c-52b5-4ae7-a420-fee8d81555dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复述", "is_correct": true, "explanation": "正确：复述 fù shù，指把别人说过的话再说一遍。"}, {"text": "复苏", "is_correct": false, "explanation": "fù sū（第一声）与 fù shù（第四声）声调不同，意思是恢复生机。"}, {"text": "户数", "is_correct": false, "explanation": "hù shù 与 fù shù 声母不同，意思是户口的数量。"}, {"text": "复书", "is_correct": false, "explanation": "fù shū（第一声）与 fù shù（第四声）声调不同，意思是回信。"}], "explanations": {"复述": "正确：复述 fù shù，指把别人说过的话再说一遍。", "复苏": "fù sū（第一声）与 fù shù（第四声）声调不同，意思是恢复生机。", "户数": "hù shù 与 fù shù 声母不同，意思是户口的数量。", "复书": "fù shū（第一声）与 fù shù（第四声）声调不同，意思是回信。"}, "sentence_index": null, "correct_answer": "复述"}, "level_3": {"options": [{"text": "复述", "is_correct": true, "explanation": "正确：复述指把听到的话再说一遍，与“没听清”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用来要求对方重说。"}, {"text": "启动", "is_correct": false, "explanation": "语义：“启动”指开动机器或程序，与重说一遍无关。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑或设备，与听话无关。"}], "explanations": {"复述": "正确：复述指把听到的话再说一遍，与“没听清”的语境相符。", "修理": "搭配：“修理”针对器物，不能用来要求对方重说。", "启动": "语义：“启动”指开动机器或程序，与重说一遍无关。", "拆除": "语义：“拆除”指拆掉建筑或设备，与听话无关。"}, "sentence_index": 0, "correct_answer": "复述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把那张桌子复述了一遍。", "explanation": "这里应该用〈擦〉。复述只用于话或内容，桌子要擦应说擦。"}, {"text": "她把那杯咖啡复述了一遍。", "explanation": "这里应该用〈喝〉。复述只用于话或内容，咖啡要喝应说喝。"}, {"text": "这段话他一次也没听过，却能完整地复述出来。", "explanation": "这里应该用〈编造〉。复述要求先接触原内容，没听过的内容只能说编造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复述", "is_correct": true, "explanation": "正确：复述指听后把内容说出来，与“听一遍就能说出来”一致。"}, {"text": "抄写", "is_correct": false, "explanation": "语义：抄写是照着原文写下来，与“说出来”的口头动作不符。"}, {"text": "打断", "is_correct": false, "explanation": "搭配：“打断”是中途插话，不能用于“很会……”的能力。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：拍照与听声音、说出内容无关。"}], "explanations": {"复述": "正确：复述指听后把内容说出来，与“听一遍就能说出来”一致。", "抄写": "语义：抄写是照着原文写下来，与“说出来”的口头动作不符。", "打断": "搭配：“打断”是中途插话，不能用于“很会……”的能力。", "拍照": "语义：拍照与听声音、说出内容无关。"}, "sentence_index": 6, "correct_answer": "复述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他复述了一座大楼。", "explanation": "这里应该用〈重建〉。复述只用于话或内容，大楼重新建造应说重建。"}, {"text": "他把那辆车复述了一遍。", "explanation": "这里应该用〈洗〉。复述只用于话或内容，车要洗应说洗。"}, {"text": "我们刚赢了比赛，我想把奖杯复述一遍。", "explanation": "这里应该用〈展示〉。复述只用于话或内容，奖杯要展示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你复述一个刚才的话。", "corrected_sentence": "请你复述一遍刚才的话。", "error_description": "“复述”的动量词应为“遍”，不能用“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的弟弟复述的很清楚。", "corrected_sentence": "我的弟弟复述得很清楚。", "error_description": "“复述”后面的程度补语要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f79eeea-26a5-4266-b27b-1c2adea6f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
