INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "听别人说话的人。", "primary_collocate": null, "pronunciation": "tīng zhě", "ipa": "tʰiŋ˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她很会说话，也是个耐心的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台下的听者越来越多。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲课的人应该关心听者的感受。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱说话，却是最好的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听者听不懂时，说者要讲慢一点。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台收到了许多听者的来信。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对朋友来说，我只是个安静的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听者们都很喜欢这个故事。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要一位愿意倾听的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲完故事，听者提了几个问题。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聽者", "label": "繁体"}], "register": "书面", "sense_fingerprint": "听别人说话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听者", "is_correct": true, "explanation": "听者指听别人说话的人，与前句“她很会说话”相呼应，符合句意。"}, {"text": "沉默者", "is_correct": false, "explanation": "语义：“很会说话”与“沉默者”相反，句意矛盾。"}, {"text": "木偶", "is_correct": false, "explanation": "搭配：“耐心”形容有心理状态的人，不能修饰木偶。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像既不会说话，也没有耐心，与句意冲突。"}], "explanations": {"听者": "听者指听别人说话的人，与前句“她很会说话”相呼应，符合句意。", "沉默者": "语义：“很会说话”与“沉默者”相反，句意矛盾。", "木偶": "搭配：“耐心”形容有心理状态的人，不能修饰木偶。", "雕像": "语义：雕像既不会说话，也没有耐心，与句意冲突。"}, "sentence_index": 0, "correct_answer": "听者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景点里的听者很多，大家都在拍照。", "explanation": "这里应该用〈游客〉。听者指听别人说话的人，逛景点的人应说游客。"}, {"text": "这辆公交车上的听者很多，大家都在看手机。", "explanation": "这里应该用〈乘客〉。听者指听别人说话的人，乘坐公交车的人应说乘客。"}, {"text": "这部电影的听者很多，票都卖光了。", "explanation": "这里应该用〈观众〉。听者指听别人说话的人，看电影的人应说观众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听者", "is_correct": true, "explanation": "听者指听别人说话的人，“只是个安静的听者”说明我不多说话、只是倾听，符合句意。"}, {"text": "喧哗者", "is_correct": false, "explanation": "语义：“喧哗者”指大声吵闹的人，与“安静”相矛盾。"}, {"text": "鼓手", "is_correct": false, "explanation": "语义：鼓手常打出响亮的节奏，与“安静”相反。"}, {"text": "闹事者", "is_correct": false, "explanation": "搭配：“安静的”描述性情或状态，“闹事者”指挑起事端的人，两者搭配不当。"}], "explanations": {"听者": "听者指听别人说话的人，“只是个安静的听者”说明我不多说话、只是倾听，符合句意。", "喧哗者": "语义：“喧哗者”指大声吵闹的人，与“安静”相矛盾。", "鼓手": "语义：鼓手常打出响亮的节奏，与“安静”相反。", "闹事者": "搭配：“安静的”描述性情或状态，“闹事者”指挑起事端的人，两者搭配不当。"}, "sentence_index": 6, "correct_answer": "听者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里的听者越来越多，大家都在排队。", "explanation": "这里应该用〈病人〉。听者指听别人说话的人，就医的人应说病人。"}, {"text": "街上的听者一个接一个地走过，都在赶路。", "explanation": "这里应该用〈行人〉。听者指听别人说话的人，在街上走路的人应说行人。"}, {"text": "球场里的听者个个激动，一直在大声呐喊。", "explanation": "这里应该用〈球迷〉。听者指听别人说话的人，在球场呐喊助威的人应说球迷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只认真的听者。", "corrected_sentence": "他是一位认真的听者。", "error_description": "量词错误：“听者”指人，应用量词“位”或“个”，不能用“只”。正确说法是“一位认真的听者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一位很耐心听者。", "corrected_sentence": "她是一位很耐心的听者。", "error_description": "漏掉“的”：“很耐心的”是修饰“听者”的定语，二者之间要用“的”，应说“很耐心的听者”，不能说“很耐心听者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
