INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话说出来就有神奇的力量。", "primary_collocate": null, "pronunciation": "yán líng", "ipa": "jɛn˧˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "古人相信言灵，所以不随便说坏话。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，好话有言灵，说出来就会成真。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本古代传说中也有言灵的说法。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信言灵，每天早上都对自己说“我可以”。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人觉得过年要说吉利话，因为有言灵。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕言灵应验，所以不敢说不好的话。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传说讲的是言灵怎样改变一个人的命运。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我不懂什么是言灵，只觉得话很重要。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，言灵的意思是话说出来就有力量。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人觉得言灵只是迷信，有人却深信不疑。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "言靈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "相信说出口的话会成真的神奇力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，正是古人“不随便说坏话”的原因，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与说话无关，不能成为“不随便说坏话”的理由。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头与说话没有关系，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“相信”后面接的是信念或观念，“桌子”不能作为相信的内容。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，正是古人“不随便说坏话”的原因，符合句意。", "颜色": "语义：颜色与说话无关，不能成为“不随便说坏话”的理由。", "石头": "语义：石头与说话没有关系，句意不通。", "桌子": "配价：“相信”后面接的是信念或观念，“桌子”不能作为相信的内容。"}, "sentence_index": 0, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这句言灵教我们要诚实。", "explanation": "这里应该用〈格言〉。言灵指话语本身的神秘力量，有教育意义的句子应说格言。"}, {"text": "远处传来一阵奇怪的言灵，把大家都吓醒了。", "explanation": "这里应该用〈声音〉。言灵指话语的神秘力量，不是耳朵能听见的声音。"}, {"text": "她从包里拿出一个言灵，送给了孩子。", "explanation": "这里应该用〈礼物〉。言灵指话语的神秘力量，不是可以拿出来送人的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，“传说讲的是言灵怎样改变命运”符合句意。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间词，不能作为“改变一个人命运”的主体，句意不通。"}, {"text": "标点", "is_correct": false, "explanation": "语义：“标点”是书写符号，不能改变人的命运，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“改变一个人的命运”需要有作用力的主体，“窗户”不能作为主语。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，“传说讲的是言灵怎样改变命运”符合句意。", "星期": "语义：“星期”是时间词，不能作为“改变一个人命运”的主体，句意不通。", "标点": "语义：“标点”是书写符号，不能改变人的命运，句意不通。", "窗户": "搭配：“改变一个人的命运”需要有作用力的主体，“窗户”不能作为主语。"}, "sentence_index": 6, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村子里突然出现了一个言灵，吓坏了大家。", "explanation": "这里应该用〈妖怪〉。言灵指话语的神秘力量，不是会行动的生物。"}, {"text": "人们向言灵祈求平安。", "explanation": "这里应该用〈神明〉。言灵指话语的神秘力量，不是有意志的神明，不能向它祈求。"}, {"text": "他小心地保管着这件言灵。", "explanation": "这里应该用〈宝物〉。言灵是话语的力量，不是可以保管的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书中的主角拥有一只言灵。", "corrected_sentence": "书中的主角拥有一种言灵。", "error_description": "量词错误：“言灵”是抽象的力量，量词应用“种”，不能用“只”。正确说法是“拥有一种言灵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书中有一段很神秘言灵描写。", "corrected_sentence": "书中有一段很神秘的言灵描写。", "error_description": "漏掉“的”：“很神秘”修饰“言灵描写”时中间要加“的”。正确说法是“很神秘的言灵描写”，漏掉“的”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”与“获得”的任何义项都没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与“获得”没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "无关：“观看”与“获得”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。", "思考": "无关：“思考”与“获得”的任何义项都没有反义关系。", "散步": "无关：“散步”与“获得”没有反义关系。", "观看": "无关：“观看”与“获得”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：“跑步”与“获得”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”与“获得”没有反义关系。"}, {"text": "煮饭", "is_correct": false, "explanation": "无关：“煮饭”与“获得”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。", "跑步": "无关：“跑步”与“获得”没有反义关系。", "睡觉": "无关：“睡觉”与“获得”没有反义关系。", "煮饭": "无关：“煮饭”与“获得”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到想要的东西。", "primary_collocate": null, "pronunciation": "huò dé", "ipa": "xu̯ɔ˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他一直想获得那份工作。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王努力学习，想获得好成绩。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望获得一次去中国的机会。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了获得他的信任，她做了很多事。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位选手凭借努力获得了金牌。", "target_word": "获得", "complexity_tier": "T3", "furigana": "zhè wèi xuǎnshǒu píngjiè nǔlì huòdé le jīnpái", "sentence_source": "generated"}, {"text": "他很想获得老师的同意。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于获得了想要的书。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想获得比赛的第一名。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想获得更多的时间学中文。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了很久，终于获得了那张票。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲得", "label": "繁体"}, {"form": "获得了", "label": "体标"}, {"form": "获得过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "经过努力或等待得到自己想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5ba59dc-380a-4728-a304-98f8c579d0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确：“想获得”表示希望得到，与“那份工作”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃那份工作”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱那份工作”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，后面不能直接带宾语“那份工作”。"}], "explanations": {"获得": "正确：“想获得”表示希望得到，与“那份工作”搭配自然。", "吃": "搭配：“吃”的对象是食物，不能说“吃那份工作”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱那份工作”。", "笑": "配价：“笑”是不及物动词，后面不能直接带宾语“那份工作”。"}, "sentence_index": 0, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天获得了一场误会。", "explanation": "这里应该用〈发生〉。“误会”是意外发生的事，“获得”只用于得到想要的东西。"}, {"text": "他昨天获得了感冒。", "explanation": "这里应该用〈患上〉。“获得”指得到想要的东西，不能用来说染上疾病，要说“患上感冒”。"}, {"text": "他昨天获得了一顿批评。", "explanation": "这里应该用〈挨〉。“获得”指得到想要的东西，“批评”是不想要的事，应说“挨一顿批评”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确：“终于获得了”表示经过等待后终于得到想要的书。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“喝想要的书”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语“想要的书”。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”多用于食物或药物，不能说“吞想要的书”。"}], "explanations": {"获得": "正确：“终于获得了”表示经过等待后终于得到想要的书。", "喝": "搭配：“喝”的对象是饮品，不能说“喝想要的书”。", "哭": "配价：“哭”是不及物动词，不能带宾语“想要的书”。", "吞": "搭配：“吞”多用于食物或药物，不能说“吞想要的书”。"}, "sentence_index": 6, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从楼梯上获得了一跤。", "explanation": "这里应该用〈摔〉。“摔一跤”是意外遭遇，“获得”只用于想要的东西。"}, {"text": "这场大火之后，村子获得了一片废墟。", "explanation": "这里应该用〈留下〉。“废墟”是大火留下的结果，“获得”只用于得到想要的东西。"}, {"text": "他这次获得了一场大麻烦。", "explanation": "这里应该用〈惹〉。“惹”指引来不好的事，“获得”只用于想要的好东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们想获得了更多的支持。", "corrected_sentence": "我们想获得更多的支持。", "error_description": "错误形式：“想获得了”。“想”表示意愿、指向未来，不能与表示完成的“了”连用；正确形式为“想获得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于获得着成功。", "corrected_sentence": "他们终于获得了成功。", "error_description": "错误形式：“终于获得着”。“终于”表示动作最终完成，与表示持续的“着”相矛盾；正确形式为“终于获得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散步", "is_correct": false, "explanation": "与“确认”无反义关系：“散步”指慢慢走路，与确认的意思无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“确认”无反义关系：“唱歌”是发声歌唱，与核实、肯定事实无关。"}, {"text": "旅行", "is_correct": false, "explanation": "与“确认”无反义关系：“旅行”指到外地游览，与确认的意思不相对。"}, {"text": "否认", "is_correct": true, "explanation": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}], "correct_answer": "否认", "explanations": {"散步": "与“确认”无反义关系：“散步”指慢慢走路，与确认的意思无关。", "唱歌": "与“确认”无反义关系：“唱歌”是发声歌唱，与核实、肯定事实无关。", "旅行": "与“确认”无反义关系：“旅行”指到外地游览，与确认的意思不相对。", "否认": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跑步", "is_correct": false, "explanation": "与“确认”无反义关系：“跑步”指快速跑动，与确认的意思无关。"}, {"text": "游泳", "is_correct": false, "explanation": "与“确认”无反义关系：“游泳”指在水中活动，与确认的意思不相对。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“确认”无反义关系：“睡觉”指休息入睡，与核实、肯定事实无关。"}, {"text": "否认", "is_correct": true, "explanation": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}], "correct_answer": "否认", "explanations": {"跑步": "与“确认”无反义关系：“跑步”指快速跑动，与确认的意思无关。", "游泳": "与“确认”无反义关系：“游泳”指在水中活动，与确认的意思不相对。", "睡觉": "与“确认”无反义关系：“睡觉”指休息入睡，与核实、肯定事实无关。", "否认": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示肯定、确定，没有疑问。", "primary_collocate": null, "pronunciation": "què rèn", "ipa": "tɕʰɥe˥˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "请你再确认一下时间。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生确认他没有生病。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经确认了明天的飞机票。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "订房间以后，酒店会给你打电话确认。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们确认一下名字对不对。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太确定，想再确认一次。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察确认了那个人的身份。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先确认地址，再寄东西。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经确认今天会来，我们不用再等了。", "target_word": "确认", "complexity_tier": "T3", "furigana": "tā yǐ jīng què rèn jīn tiān huì lái, wǒ men bù yòng zài děng le.", "sentence_source": "generated"}, {"text": "我给朋友发了短信，请他确认收到了。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "确认了", "label": "体标"}, {"form": "确认过", "label": "体标"}, {"form": "确认书", "label": "复合"}, {"form": "確認", "label": "繁体"}], "register": "中性", "sense_fingerprint": "确认：把情况弄清楚并肯定、确定下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
